import { LucideIcon } from "lucide-react";

export interface MenuItem {
  id: string;
  label: string;
  icon: LucideIcon;
  hasSubmenu?: boolean;
  subItems?: string[];
}

export interface Patient {
  id: string;
  // Personal
  firstName: string; // Nombres y Apellidos
  cedula: string;
  birthDate: string;
  address: string;
  phone: string;

  // Medical
  medicalHistory: string; // Antecedentes
  hasDisability: boolean;
  disabilityDescription?: string;

  // Laboral
  company: string;
  jobTitle: string; // Cargo
  entryDate: string;
  employmentStatus: 'fijo' | 'contratado';

  createdAt: string;
}

import { Patient } from '../types';

const STORAGE_KEY = 'alex_consulting_patients';

// Simulates a database connection and save operation
export const savePatientToDB = (patientData: Omit<Patient, 'id' | 'createdAt'>): Promise<Patient> => {
  return new Promise((resolve, reject) => {
    try {
      // Simulate network delay
      setTimeout(() => {
        const existingData = localStorage.getItem(STORAGE_KEY);
        const patients: Patient[] = existingData ? JSON.parse(existingData) : [];

        const newPatient: Patient = {
          ...patientData,
          id: crypto.randomUUID(), // Generate unique ID
          createdAt: new Date().toISOString()
        };

        patients.push(newPatient);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(patients));

        console.log("Database: Record inserted successfully", newPatient);
        resolve(newPatient);
      }, 500);
    } catch (error) {
      reject(error);
    }
  });
};

export const getPatientsFromDB = (): Patient[] => {
  const existingData = localStorage.getItem(STORAGE_KEY);
  return existingData ? JSON.parse(existingData) : [];
};

import React, { useState } from 'react';
import { Save, User, Briefcase, Stethoscope, AlertCircle, CheckCircle2 } from 'lucide-react';
import { savePatientToDB } from '../utils/storage';
import { Patient } from '../types';

const PatientRegistration: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    firstName: '',
    cedula: '',
    birthDate: '',
    address: '',
    phone: '',
    medicalHistory: '',
    hasDisability: false,
    disabilityDescription: '',
    company: '',
    jobTitle: '',
    entryDate: '',
    employmentStatus: 'fijo' as 'fijo' | 'contratado'
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setSuccess(false);

    try {
      await savePatientToDB({
        ...formData,
        // Ensure disability description is clear if toggle is false
        disabilityDescription: formData.hasDisability ? formData.disabilityDescription : undefined
      });

      setSuccess(true);
      // Optional: Reset form
      setFormData({
        firstName: '',
        cedula: '',
        birthDate: '',
        address: '',
        phone: '',
        medicalHistory: '',
        hasDisability: false,
        disabilityDescription: '',
        company: '',
        jobTitle: '',
        entryDate: '',
        employmentStatus: 'fijo'
      });

      // Hide success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving patient", error);
      alert("Error al guardar el paciente");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-10">

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Registro de Paciente</h2>
        {success && (
