export interface MenuItem {
  id: string;
  label: string;
  icon: LucideIcon;
  hasSubmenu?: boolean;
  subItems?: string[];
}

export interface Patient {
  id: string;
  // Personal
  photoUrl?: string; // Campo opcional para la foto
  firstName: string; // Nombres y Apellidos
  cedula: string;
  birthDate: string;
  address: string;
  phone: string;

  // Medical
  medicalHistory: string; // Antecedentes
  hasDisability: boolean;
  disabilityDescription?: string;

