import React, { useState } from 'react';
import { Save, User, Briefcase, Stethoscope, AlertCircle, CheckCircle2, Upload, Trash2, Camera } from 'lucide-react';
import { savePatientToDB } from '../utils/storage';
import { Patient } from '../types';

const PatientRegistration: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    photoUrl: '',
    firstName: '',
    cedula: '',
    birthDate: '',
    address: '',
    phone: '',
    medicalHistory: '',
    hasDisability: false,
    disabilityDescription: '',
    company: '',
    jobTitle: '',
    entryDate: '',
    employmentStatus: 'fijo' as 'fijo' | 'contratado'
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Basic size validation (limit to ~1MB for localStorage safety)
      if (file.size > 1024 * 1024) {
        alert("La imagen es demasiado grande. Por favor seleccione una imagen menor a 1MB.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, photoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removePhoto = () => {
    setFormData(prev => ({ ...prev, photoUrl: '' }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setSuccess(false);

    try {
      await savePatientToDB({
        ...formData,
        // Ensure disability description is clear if toggle is false
        disabilityDescription: formData.hasDisability ? formData.disabilityDescription : undefined
      });

      setSuccess(true);
      // Optional: Reset form
      setFormData({
        photoUrl: '',
        firstName: '',
        cedula: '',
        birthDate: '',
        address: '',
        phone: '',
        medicalHistory: '',
        hasDisability: false,
        disabilityDescription: '',
        company: '',
        jobTitle: '',
        entryDate: '',
        employmentStatus: 'fijo'
      });

      // Hide success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving patient", error);
      alert("Error al guardar el paciente. Es posible que la imagen sea muy pesada para el almacenamiento local.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-10">

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Registro de Paciente</h2>
        {success && (
          <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-2 rounded flex items-center animate-pulse">
            <CheckCircle2 className="w-5 h-5 mr-2" />
            Paciente guardado exitosamente
          </div>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* 1. Datos Personales */}
        <section className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-blue-50 px-6 py-4 border-b border-blue-100 flex items-center gap-2">
            <User className="w-5 h-5 text-blue-600" />
            <h3 className="font-semibold text-blue-900">Datos Personales</h3>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">

            {/* Photo Upload Section */}
            <div className="md:col-span-2 flex flex-col sm:flex-row items-center gap-6 pb-6 border-b border-slate-100 mb-2">
              <div className="relative group shrink-0">
                <div className={`w-32 h-32 rounded-full flex items-center justify-center border-2 border-dashed border-slate-300 overflow-hidden bg-slate-50 relative ${formData.photoUrl ? 'border-blue-200 shadow-md' : ''}`}>
                  {formData.photoUrl ? (
                    <img src={formData.photoUrl} alt="Foto del paciente" className="w-full h-full object-cover" />
                  ) : (
                    <User className="w-12 h-12 text-slate-300" />
                  )}

                  {!formData.photoUrl && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity rounded-full">
                       <Camera className="w-8 h-8 text-slate-500" />
                    </div>
                  )}
                </div>

                <div className="absolute -bottom-2 -right-2 flex gap-2">
                    <label className="bg-blue-600 p-2.5 rounded-full cursor-pointer hover:bg-blue-700 transition-all shadow-md text-white hover:scale-105 active:scale-95" title="Subir foto">
                      <Upload className="w-4 h-4" />
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={handlePhotoChange} 
                        className="hidden" 
                      />
                    </label>
                    {formData.photoUrl && (
                      <button 
                        type="button"
                        onClick={removePhoto}
                        className="bg-red-500 p-2.5 rounded-full cursor-pointer hover:bg-red-600 transition-all shadow-md text-white hover:scale-105 active:scale-95"
                        title="Eliminar foto"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                </div>
              </div>

              <div className="text-center sm:text-left flex-1">
