const MedicalAttention: React.FC = () => {
  // --- States ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');
  const [currentPatient, setCurrentPatient] = useState<Patient | null>(null);

  const [loadingSave, setLoadingSave] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    attentionDate: new Date().toISOString().split('T')[0], // Default to today
    attentionType: 'General' as 'Pre Empleo' | 'Pre Vacaciones' | 'Egreso' | 'Periódica' | 'General',
    diagnosis: '',
    restDays: 0,
    evaluationResult: 'Apto' as 'Apto' | 'No Apto' | 'Postpuesta' | 'No Aplica'
  });

  // --- Helpers ---

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const getRestEndDate = (startDate: string, days: number) => {
    if (!startDate) return '';
    const date = new Date(startDate);
    // Add days. Note: If days is 0, end date = start date (technically 1 day of rest? or 0? 
    // Logic: If I give 1 day of rest starting today, I rest today. Return tomorrow? 
    // Usually medical rest: Start date inclusive. End date inclusive.
    // Let's assume startDate + days - 1 if we want inclusive range, but usually systems do Start + Duration.
    // Let's do simple addition for display purposes: "Hasta: [Date]"
    date.setDate(date.getDate() + Number(days));
    return date.toISOString().split('T')[0];
  };

  // --- Handlers ---

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setSearchError('');
    setCurrentPatient(null);

    try {
      const found = await findPatientByCedula(searchCedula);
      if (found) {
        setCurrentPatient(found);
      } else {
        setSearchError('Paciente no encontrado. Verifique la cédula o registre un nuevo paciente.');
      }
    } catch (err) {
      setSearchError('Error al buscar en la base de datos.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleFormChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentPatient) return;

    setLoadingSave(true);
    setSaveSuccess(false);

    try {
      await saveMedicalAttentionToDB({
        patientId: currentPatient.id,
        patientName: currentPatient.firstName,
        patientCedula: currentPatient.cedula,
        attentionDate: formData.attentionDate,
        attentionType: formData.attentionType,
        diagnosis: formData.diagnosis,
        restDays: Number(formData.restDays),
        restStartDate: formData.attentionDate,
        restEndDate: getRestEndDate(formData.attentionDate, formData.restDays),
        evaluationResult: formData.evaluationResult
      });

      setSaveSuccess(true);
      // Reset form partially, keep patient loaded? Or reset all? 
      // Usually better to keep patient to print report or something, but let's just show success.
      setTimeout(() => setSaveSuccess(false), 3000);

      // Clear diagnosis fields for next entry
      setFormData(prev => ({
        ...prev,
        diagnosis: '',
        restDays: 0,
        evaluationResult: 'Apto'
      }));

    } catch (error) {
      alert('Error al guardar la atención médica.');
    } finally {
      setLoadingSave(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-10">
       <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Atención Médica</h2>
        {saveSuccess && (
          <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-2 rounded flex items-center animate-pulse">
            <CheckCircle2 className="w-5 h-5 mr-2" />
            Atención registrada exitosamente
          </div>
        )}
      </div>

      {/* 1. Búsqueda de Paciente */}
      <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
        <h3 className="text-lg font-semibold text-slate-700 mb-4 flex items-center gap-2">
          <Search className="w-5 h-5 text-blue-600" />
          Búsqueda de Paciente
        </h3>
        <form onSubmit={handleSearch} className="flex gap-4 items-start">
          <div className="flex-1 max-w-md">
            <label className="block text-sm font-medium text-slate-700 mb-1">Cédula del Paciente</label>
            <div className="relative">
              <input 
                type="number" 
                value={searchCedula}
                onChange={(e) => setSearchCedula(e.target.value)}
