                placeholder="Ingrese número de cédula"
              />
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-3" />
            </div>
            {searchError && <p className="text-red-500 text-sm mt-2 flex items-center gap-1"><AlertCircle className="w-3 h-3"/> {searchError}</p>}
          </div>
          <button 
            type="submit"
            disabled={isSearching}
            className="mt-6 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 transition-colors font-medium"
          >
            {isSearching ? 'Buscando...' : 'Buscar'}
          </button>
        </form>
      </section>

      {currentPatient && (
        <form onSubmit={handleSave} className="animate-in fade-in slide-in-from-bottom-4 duration-500">

          {/* Visualización Datos del Paciente (Solo Lectura) */}
          <div className="bg-blue-50 rounded-xl border border-blue-100 p-6 mb-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <User className="w-32 h-32 text-blue-600" />
            </div>
            <h3 className="text-blue-900 font-bold mb-4 flex items-center gap-2">
              <User className="w-5 h-5" />
