import { Patient, MedicalAttention } from '../types';

const STORAGE_KEY_PATIENTS = 'alex_consulting_patients';
const STORAGE_KEY_ATTENTIONS = 'alex_consulting_attentions';

// --- Patients ---

// Simulates a database connection and save operation
export const savePatientToDB = (patientData: Omit<Patient, 'id' | 'createdAt'>): Promise<Patient> => {
  return new Promise((resolve, reject) => {
    try {
      // Simulate network delay
      setTimeout(() => {
        const existingData = localStorage.getItem(STORAGE_KEY_PATIENTS);
        const patients: Patient[] = existingData ? JSON.parse(existingData) : [];

        const newPatient: Patient = {
          ...patientData,
          id: crypto.randomUUID(), // Generate unique ID
          createdAt: new Date().toISOString()
        };

        patients.push(newPatient);
        localStorage.setItem(STORAGE_KEY_PATIENTS, JSON.stringify(patients));

        console.log("Database: Record inserted successfully", newPatient);
        resolve(newPatient);
      }, 500);
    } catch (error) {
      reject(error);
    }
  });
};

export const getPatientsFromDB = (): Patient[] => {
  const existingData = localStorage.getItem(STORAGE_KEY_PATIENTS);
  return existingData ? JSON.parse(existingData) : [];
};

export const findPatientByCedula = (cedula: string): Promise<Patient | undefined> => {
  return new Promise((resolve) => {
    // Simulate lookup delay
    setTimeout(() => {
        const patients = getPatientsFromDB();
        const found = patients.find(p => p.cedula === cedula);
        resolve(found);
    }, 300);
  });
};

// --- Medical Attentions ---

const getAttentionsFromDB = (): MedicalAttention[] => {
  const existingData = localStorage.getItem(STORAGE_KEY_ATTENTIONS);
  return existingData ? JSON.parse(existingData) : [];
};

export const saveMedicalAttentionToDB = (attentionData: Omit<MedicalAttention, 'id' | 'createdAt'>): Promise<MedicalAttention> => {
  return new Promise((resolve, reject) => {
    try {
      setTimeout(() => {
        const attentions = getAttentionsFromDB();

        const newAttention: MedicalAttention = {
            ...attentionData,
            id: crypto.randomUUID(),
            createdAt: new Date().toISOString()
        };

        attentions.push(newAttention);
        localStorage.setItem(STORAGE_KEY_ATTENTIONS, JSON.stringify(attentions));

        console.log("Database: Attention saved", newAttention);
        resolve(newAttention);
      }, 500);
    } catch (error) {
        reject(error);
    }
  });
};

export const getMedicalAttentionsByCedula = (cedula: string): Promise<MedicalAttention[]> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const attentions = getAttentionsFromDB();
      // Filter by patient cedula and sort by date descending
      const filtered = attentions
        .filter(a => a.patientCedula === cedula)
        .sort((a, b) => new Date(b.attentionDate).getTime() - new Date(a.attentionDate).getTime());
      resolve(filtered);
    }, 300);
  });
};

export const updateMedicalAttention = (id: string, updatedData: Partial<MedicalAttention>): Promise<MedicalAttention> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const attentions = getAttentionsFromDB();
      const index = attentions.findIndex(a => a.id === id);

      if (index !== -1) {
        attentions[index] = { ...attentions[index], ...updatedData };
        localStorage.setItem(STORAGE_KEY_ATTENTIONS, JSON.stringify(attentions));
        resolve(attentions[index]);
      } else {
        reject(new Error("Attention not found"));
      }
    }, 500);
  });
};

export const deleteMedicalAttention = (id: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const attentions = getAttentionsFromDB();
      const filtered = attentions.filter(a => a.id !== id);

      if (attentions.length !== filtered.length) {
        localStorage.setItem(STORAGE_KEY_ATTENTIONS, JSON.stringify(filtered));
        resolve();
      } else {
        reject(new Error("Attention not found"));
      }
    }, 500);
  });
};

