type TabMode = 'add' | 'edit' | 'delete';

const PatientRegistration: React.FC = () => {
  // --- Global State ---
  const [activeTab, setActiveTab] = useState<TabMode>('add');
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // --- Search State (Edit/Delete) ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');
  const [foundPatientId, setFoundPatientId] = useState<string | null>(null);

  // --- Form State ---
  const [formData, setFormData] = useState({
    photoUrl: '',
    firstName: '',
    cedula: '',
    birthDate: '',
    address: '',
    phone: '',
    medicalHistory: '',
    hasDisability: false,
    disabilityDescription: '',
    company: '',
    jobTitle: '',
    entryDate: '',
    employmentStatus: 'fijo' as 'fijo' | 'contratado'
  });

  // Reset when changing tabs
  useEffect(() => {
    setSearchCedula('');
    setSearchError('');
    setFoundPatientId(null);
    setSuccessMsg(null);
    resetForm();
  }, [activeTab]);

  const resetForm = () => {
    setFormData({
      photoUrl: '',
      firstName: '',
      cedula: '',
      birthDate: '',
      address: '',
      phone: '',
      medicalHistory: '',
      hasDisability: false,
      disabilityDescription: '',
      company: '',
      jobTitle: '',
      entryDate: '',
      employmentStatus: 'fijo'
    });
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setSearchError('');
    setFoundPatientId(null);
    resetForm();

    try {
      const patient = await findPatientByCedula(searchCedula);
      if (patient) {
        setFoundPatientId(patient.id);
        setFormData({
            photoUrl: patient.photoUrl || '',
            firstName: patient.firstName,
            cedula: patient.cedula,
            birthDate: patient.birthDate,
            address: patient.address,
            phone: patient.phone,
            medicalHistory: patient.medicalHistory,
            hasDisability: patient.hasDisability,
            disabilityDescription: patient.disabilityDescription || '',
            company: patient.company,
            jobTitle: patient.jobTitle,
            entryDate: patient.entryDate,
            employmentStatus: patient.employmentStatus
        });
      } else {
        setSearchError('Paciente no encontrado.');
      }
    } catch (err) {
      setSearchError('Error al buscar paciente.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) {
        alert("La imagen es demasiado grande. Por favor seleccione una imagen menor a 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, photoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removePhoto = () => {
    setFormData(prev => ({ ...prev, photoUrl: '' }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setSuccessMsg(null);

