import React, { useState } from 'react';
import { 
  Search, User, Calendar, AlertCircle, FileText, 
  Building2, Briefcase, Phone, MapPin, Activity,
  ChevronDown, ChevronUp, Printer, Clock
} from 'lucide-react';
import { findPatientByCedula, getMedicalAttentionsByCedula } from '../utils/storage';
import { Patient, MedicalAttention } from '../types';

const ClinicalHistory: React.FC = () => {
  // --- State ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState('');

  const [patient, setPatient] = useState<Patient | null>(null);
  const [attentions, setAttentions] = useState<MedicalAttention[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // --- Helpers ---
  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setError('');
    setPatient(null);
    setAttentions([]);

    try {
      // 1. Get Patient
      const foundPatient = await findPatientByCedula(searchCedula);
      if (!foundPatient) {
        setError('Paciente no encontrado en la base de datos.');
        setIsSearching(false);
        return;
      }

      // 2. Get Attentions
      const foundAttentions = await getMedicalAttentionsByCedula(searchCedula);

      setPatient(foundPatient);
      setAttentions(foundAttentions); // Already sorted desc in storage utility
    } catch (err) {
      setError('Error al recuperar la información.');
    } finally {
      setIsSearching(false);
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const getResultColor = (result: string) => {
    switch (result) {
      case 'Apto': return 'border-green-500 bg-green-50 text-green-800';
      case 'No Apto': return 'border-red-500 bg-red-50 text-red-800';
      case 'Postpuesta': return 'border-orange-500 bg-orange-50 text-orange-800';
      default: return 'border-slate-300 bg-slate-50 text-slate-700';
    }
  };

  return (
    <div className="max-w-5xl mx-auto pb-12">
      <div className="flex justify-between items-end mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Historia Clínica</h2>
          <p className="text-slate-500 text-sm mt-1">Consulta integral de expediente y atenciones.</p>
        </div>
      </div>

      {/* 1. Search Bar */}
      <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-8 print:hidden">
        <form onSubmit={handleSearch} className="flex gap-4 items-end">
          <div className="flex-1 max-w-md">
            <label className="block text-sm font-medium text-slate-700 mb-1">Buscar Paciente</label>
            <div className="relative">
              <input 
                type="number" 
                value={searchCedula}
                onChange={(e) => setSearchCedula(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="Ingrese Cédula de Identidad"
              />
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-3" />
            </div>
          </div>
          <button 
            type="submit"
            disabled={isSearching}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 transition-colors font-medium flex items-center gap-2"
          >
            {isSearching ? 'Buscando...' : 'Consultar Expediente'}
          </button>
        </form>
        {error && <p className="text-red-500 text-sm mt-3 flex items-center gap-1"><AlertCircle className="w-3 h-3"/> {error}</p>}
      </section>

      {/* DOCUMENT VIEW */}
      {patient && (
        <div className="bg-white shadow-2xl border border-slate-200 rounded-none md:rounded-lg overflow-hidden print:shadow-none print:border-0 max-w-[210mm] mx-auto min-h-[297mm] flex flex-col relative">

          {/* Header Branding (Simulated Document Header) */}
          <div className="bg-slate-900 text-white p-8 print:p-0 print:bg-white print:text-black print:border-b-2 print:border-black">
            <div className="flex justify-between items-center">
              <div>
                <h1 className="text-2xl font-bold uppercase tracking-wider">Hoja de Historia Clínica</h1>
                <p className="text-slate-400 print:text-black text-sm">Alex Consulting - Servicios Médicos Ocupacionales</p>
              </div>
              <div className="text-right hidden md:block">
                 <p className="text-xs text-slate-500">Fecha de Impresión</p>
                 <p className="font-mono text-sm">{new Date().toLocaleDateString()}</p>
              </div>
            </div>
          </div>

          <div className="p-8 md:p-12 flex-1">

            {/* 2. Patient Header Data */}
            <section className="mb-10 border-b-2 border-slate-100 pb-8">
              <div className="flex flex-col md:flex-row gap-8">
                {/* Photo */}
                <div className="shrink-0 flex justify-center md:justify-start">
                   <div className="w-32 h-32 md:w-40 md:h-40 rounded-lg border-2 border-slate-200 overflow-hidden bg-slate-100 shadow-inner">
                     {patient.photoUrl ? (
                       <img src={patient.photoUrl} alt="Paciente" className="w-full h-full object-cover" />
                     ) : (
                       <User className="w-full h-full p-8 text-slate-300" />
                     )}
                   </div>
                </div>

                {/* Personal Data */}
                <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-y-4 gap-x-8">
                  <div className="md:col-span-2">
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Paciente</label>
                    <h2 className="text-2xl font-bold text-slate-900">{patient.firstName}</h2>
                  </div>

                  <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Cédula de Identidad</label>
                    <p className="text-lg font-mono font-medium text-slate-800">{patient.cedula}</p>
                  </div>

                  <div>
                     <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Edad / Nacimiento</label>
                     <p className="text-lg text-slate-800">{calculateAge(patient.birthDate)} años <span className="text-slate-400 text-sm">({new Date(patient.birthDate).toLocaleDateString()})</span></p>
                  </div>

                  <div>
                     <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1 flex items-center gap-1"><Phone className="w-3 h-3"/> Teléfono</label>
                     <p className="text-base text-slate-800">{patient.phone}</p>
                  </div>

                  <div className="md:col-span-2">
                     <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1 flex items-center gap-1"><MapPin className="w-3 h-3"/> Dirección</label>
                     <p className="text-base text-slate-800">{patient.address}</p>
                  </div>
                </div>
              </div>

              {/* Extra Info Grid */}
              <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 p-4 rounded-lg border border-slate-100">
                 <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1 flex items-center gap-1"><Building2 className="w-3 h-3"/> Empresa</label>
                    <p className="font-semibold text-slate-800">{patient.company}</p>
                 </div>
                 <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1 flex items-center gap-1"><Briefcase className="w-3 h-3"/> Cargo</label>
                    <p className="font-semibold text-slate-800">{patient.jobTitle}</p>
                 </div>
                 <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Estatus Laboral</label>
                    <p className="font-semibold text-slate-800 capitalize">{patient.employmentStatus}</p>
                 </div>
                 <div className="md:col-span-3 pt-2 border-t border-slate-200">
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Discapacidad</label>
                    {patient.hasDisability ? (
                      <span className="inline-flex items-center gap-2 text-amber-700 font-medium">
                        <AlertCircle className="w-4 h-4"/> Sí - {patient.disabilityDescription}
                      </span>
                    ) : (
                      <span className="text-slate-600">No reportada</span>
