                 <div className="text-center py-12 bg-slate-50 rounded-lg border border-dashed border-slate-300">
                    <FileText className="w-12 h-12 text-slate-300 mx-auto mb-2" />
                    <p className="text-slate-500 font-medium">No hay atenciones médicas registradas para este paciente.</p>
                 </div>
               ) : (
                 <div className="space-y-6 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-slate-200 before:to-transparent">

                    {attentions.map((attention) => (
                       <div key={attention.id} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group is-active">

                          {/* Timeline Dot */}
                          <div className="flex items-center justify-center w-10 h-10 rounded-full border-4 border-white bg-blue-100 text-blue-600 shadow shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 absolute left-0 md:left-1/2 transform -translate-x-1/2 md:relative">
                            <Calendar className="w-4 h-4" />
                          </div>

                          {/* Card Content */}
                          <div className="w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] bg-white border border-slate-200 p-0 rounded-xl shadow-sm hover:shadow-md transition-shadow ml-auto md:ml-0 overflow-hidden">

                             {/* Card Header (Clickable) */}
                             <div 
                                onClick={() => toggleExpand(attention.id)}
                                className={`cursor-pointer border-l-4 p-4 flex justify-between items-start ${getResultColor(attention.evaluationResult)} bg-opacity-10`}
                             >
                                <div>
                                   <p className="text-xs font-bold uppercase opacity-70 mb-1 tracking-wider">{attention.attentionType}</p>
                                   <h4 className="font-bold text-lg text-slate-800 mb-1">{formatDate(attention.attentionDate)}</h4>
