                                </div>
                                <div className="text-slate-400">
                                   {expandedId === attention.id ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                                </div>
                             </div>

                             {/* Expandable Details */}
                             {expandedId === attention.id && (
                               <div className="p-5 border-t border-slate-100 bg-white animate-in slide-in-from-top-2 duration-200">

                                  <div className="mb-4">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Diagnóstico / Patología</label>
