          </div>

          {/* Document Footer */}
          <div className="bg-slate-50 p-6 border-t border-slate-200 text-center print:bg-white print:border-t-2 print:border-black">
             <p className="text-xs text-slate-400 uppercase tracking-widest mb-4">Fin del Documento</p>
             <button 
              onClick={() => window.print()} 
              className="inline-flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm font-medium print:hidden"
             >
                <Printer className="w-4 h-4" /> Imprimir Expediente
             </button>
          </div>
        </div>
      )}
    </div>
  );
