const STORAGE_KEY_PATIENTS = 'alex_consulting_patients';
const STORAGE_KEY_ATTENTIONS = 'alex_consulting_attentions';
const STORAGE_KEY_PRESCRIPTIONS = 'alex_consulting_prescriptions';

// --- Patients ---

// Simulates a database connection and save operation
export const savePatientToDB = (patientData: Omit<Patient, 'id' | 'createdAt'>): Promise<Patient> => {
  return new Promise((resolve, reject) => {
    try {
      // Simulate network delay
      setTimeout(() => {
        const existingData = localStorage.getItem(STORAGE_KEY_PATIENTS);
        const patients: Patient[] = existingData ? JSON.parse(existingData) : [];

        // Check for duplicates (optional but good practice)
        if (patients.some(p => p.cedula === patientData.cedula)) {
             // In a real app we might throw an error, but here we proceed or could reject
             // console.warn("Patient with this cedula already exists");
        }

        const newPatient: Patient = {
          ...patientData,
          id: crypto.randomUUID(), // Generate unique ID
          createdAt: new Date().toISOString()
        };

        patients.push(newPatient);
        localStorage.setItem(STORAGE_KEY_PATIENTS, JSON.stringify(patients));

        console.log("Database: Record inserted successfully", newPatient);
        resolve(newPatient);
      }, 500);
    } catch (error) {
      reject(error);
    }
  });
};

export const getPatientsFromDB = (): Patient[] => {
  const existingData = localStorage.getItem(STORAGE_KEY_PATIENTS);
  return existingData ? JSON.parse(existingData) : [];
};

export const findPatientByCedula = (cedula: string): Promise<Patient | undefined> => {
  return new Promise((resolve) => {
    // Simulate lookup delay
    setTimeout(() => {
        const patients = getPatientsFromDB();
        const found = patients.find(p => p.cedula === cedula);
        resolve(found);
    }, 300);
  });
};

export const updatePatient = (id: string, updatedData: Partial<Patient>): Promise<Patient> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const patients = getPatientsFromDB();
      const index = patients.findIndex(p => p.id === id);

      if (index !== -1) {
        // Keep ID and CreatedAt, update the rest
        patients[index] = { ...patients[index], ...updatedData };
        localStorage.setItem(STORAGE_KEY_PATIENTS, JSON.stringify(patients));
        resolve(patients[index]);
      } else {
        reject(new Error("Patient not found"));
      }
    }, 500);
  });
};

export const deletePatient = (id: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const patients = getPatientsFromDB();
      const filtered = patients.filter(p => p.id !== id);

      if (patients.length !== filtered.length) {
        localStorage.setItem(STORAGE_KEY_PATIENTS, JSON.stringify(filtered));

        // Optional: Also cleanup associated attentions? 
        // For now, we keep them or you'd need to filter STORAGE_KEY_ATTENTIONS too.

        resolve();
      } else {
        reject(new Error("Patient not found"));
      }
    }, 500);
  });
};

