  label: string;
  icon: LucideIcon;
  hasSubmenu?: boolean;
  subItems?: string[];
}

export interface Patient {
  id: string;
  // Personal
  photoUrl?: string; // Campo opcional para la foto
  firstName: string; // Nombres y Apellidos
  cedula: string;
  birthDate: string;
  gender: 'Masculino' | 'Femenino'; // Nuevo campo requerido para SVE
