import React, { useState } from 'react';
import { 
  FolderOpen, 
  Stethoscope, 
  Calendar, 
  FileText, 
  ClipboardList, 
  Activity, 
  FileBarChart, 
  User, 
  ChevronDown, 
  ChevronRight, 
  ShieldPlus,
  BookOpenCheck
} from 'lucide-react';
import { MenuItem } from '../types';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigate: (view: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, onNavigate }) => {
  const [expandedMenu, setExpandedMenu] = useState<string | null>('archivo'); // Default expand archivo for better UX

  const menuItems: MenuItem[] = [
    { 
      id: 'archivo', 
      label: 'Archivo', 
      icon: FolderOpen, 
      hasSubmenu: true,
      subItems: ['Paciente', 'Medicos', 'Empresas', 'Usuarios', 'Historia Clínica', 'Documentos', 'Resultados'] 
    },
    { id: 'atencion', label: 'Atención Médica', icon: Stethoscope },
    { id: 'citas', label: 'Citas', icon: Calendar },
    { id: 'recipe', label: 'Recipe E.', icon: FileText },
    { id: 'reporte', label: 'Reporte', icon: ClipboardList },
    { id: 'diagnostica', label: 'I Diagnóstica', icon: Activity },
    { id: 'informes', label: 'Informes', icon: FileBarChart },
    { id: 'sve', label: 'Informe SVE', icon: BookOpenCheck }, // NEW ITEM
    { 
      id: 'usuario', 
      label: 'Usuario', 
      icon: User, 
      hasSubmenu: true,
      subItems: ['Perfil', 'Configuración', 'Cerrar Sesión']
    },
  ];

  const toggleSubmenu = (id: string) => {
    if (expandedMenu === id) {
      setExpandedMenu(null);
    } else {
      setExpandedMenu(id);
    }
  };

  const handleSubItemClick = (parent: string, item: string) => {
    // Navigate based on item name (converted to simple ID)
    const viewId = item.toLowerCase().replace(' ', '-');
    onNavigate(viewId);

    // Close sidebar on mobile after selection
    if (window.innerWidth < 1024) {
      onClose();
    }
  };

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      {/* Sidebar Container */}
      <aside 
        className={`
          fixed top-0 left-0 z-50 h-full w-72 
          bg-gradient-to-b from-[#0f172a] to-[#1e3a8a] 
          text-white shadow-2xl transition-transform duration-300 ease-in-out
          flex flex-col justify-between print:hidden
          ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
      >
        {/* Header / Logo */}
        <div className="p-6 border-b border-blue-800/50 bg-opacity-20 bg-blue-900">
          <div className="flex items-center gap-3">
            <div className="bg-blue-500 p-2 rounded-lg bg-opacity-20 border border-blue-400">
               <ShieldPlus className="w-8 h-8 text-blue-300" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-blue-100 tracking-wide">Alex Consulting</h1>
              <p className="text-xs text-blue-300 uppercase tracking-widest">Servicios Médicos</p>
            </div>
          </div>
        </div>

        {/* Navigation Items */}
        <nav className="flex-1 overflow-y-auto py-6 px-3 space-y-1 custom-scrollbar">
          {menuItems.map((item) => (
            <div key={item.id} className="mb-1">
              <button
                onClick={() => item.hasSubmenu ? toggleSubmenu(item.id) : onNavigate(item.id)}
                className={`
                  w-full flex items-center justify-between p-3 rounded-lg
                  transition-all duration-200
                  ${expandedMenu === item.id ? 'bg-blue-800/50 text-blue-200' : 'hover:bg-blue-800/30 text-gray-100'}
                `}
              >
                <div className="flex items-center gap-3">
                  <item.icon className={`w-5 h-5 ${expandedMenu === item.id ? 'text-blue-300' : 'text-gray-300'}`} />
                  <span className="font-medium text-sm">{item.label}</span>
                </div>
                {item.hasSubmenu && (
                  expandedMenu === item.id 
                    ? <ChevronDown className="w-4 h-4 text-blue-300" /> 
                    : <ChevronRight className="w-4 h-4 text-gray-400" />
                )}
              </button>

              {/* Submenu */}
              {item.hasSubmenu && expandedMenu === item.id && (
                <div className="ml-4 pl-4 border-l border-blue-700/50 mt-1 space-y-1">
                  {item.subItems?.map((sub, idx) => (
                    <button 
                      key={idx}
                      onClick={() => handleSubItemClick(item.id, sub)}
                      className="w-full text-left p-2 text-sm text-gray-300 hover:text-white hover:bg-blue-800/20 rounded transition-colors"
                    >
                      {sub}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
        </nav>

        {/* Footer */}
        <div className="p-6 border-t border-blue-800/50 bg-[#0b1120]/50 text-center">
          <p className="text-xs text-gray-400 font-light mb-1">
            &copy; {new Date().getFullYear()} Alex Marcano
          </p>
          <p className="text-xs text-gray-500 font-light">
            Todos los derechos Reservados
          </p>
          <p className="text-[10px] text-blue-400/70 mt-2 font-medium">
            Desarrollado por Alex Marcano
          </p>
        </div>
      </aside>
    </>
  );
};

