import React, { useState, useEffect } from 'react';
import { Search, Printer, FileBarChart, AlertCircle, ChevronRight, Briefcase, FileCheck, Clock, UserCheck } from 'lucide-react';
import { findPatientByCedula, getMedicalAttentionsByCedula } from '../utils/storage';
import { Patient, MedicalAttention } from '../types';

interface MedicalReportGeneratorProps {
  type: 'medical' | 'occupational' | 'sick-leave';
}

const MedicalReportGenerator: React.FC<MedicalReportGeneratorProps> = ({ type }) => {
  // --- State ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState('');

  const [patient, setPatient] = useState<Patient | null>(null);
  const [attentions, setAttentions] = useState<MedicalAttention[]>([]);
  const [selectedAttention, setSelectedAttention] = useState<MedicalAttention | null>(null);

  // Clear selection when type changes
  useEffect(() => {
    setSelectedAttention(null);
    setPatient(null);
    setAttentions([]);
    setSearchCedula('');
  }, [type]);

  // --- Logic ---
  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setError('');
    setPatient(null);
    setAttentions([]);
    setSelectedAttention(null);

    try {
      const foundPatient = await findPatientByCedula(searchCedula);
      if (!foundPatient) {
        setError('Paciente no encontrado.');
        setIsSearching(false);
        return;
      }

      const foundAttentions = await getMedicalAttentionsByCedula(searchCedula);

      // Filter for Sick Leave: Only show attentions with restDays > 0
      const filteredAttentions = type === 'sick-leave' 
        ? foundAttentions.filter(a => a.restDays > 0)
        : foundAttentions;

      setPatient(foundPatient);
      setAttentions(filteredAttentions);

      if (filteredAttentions.length === 0 && type === 'sick-leave') {
          setError('El paciente no tiene registros con días de reposo.');
      }

    } catch (err) {
      setError('Error al recuperar datos.');
    } finally {
      setIsSearching(false);
    }
  };

  const getTitle = () => {
    switch(type) {
        case 'medical': return 'Informe Médico General';
        case 'occupational': return 'Informe Ocupacional (Aptitud)';
        case 'sick-leave': return 'Constancia de Reposo Médico';
        default: return 'Reporte';
    }
  };

  const getIcon = () => {
      switch(type) {
          case 'medical': return <FileBarChart className="w-6 h-6 text-blue-600" />;
          case 'occupational': return <Briefcase className="w-6 h-6 text-indigo-600" />;
          case 'sick-leave': return <Clock className="w-6 h-6 text-orange-600" />;
          default: return <FileBarChart className="w-6 h-6" />;
      }
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const formatDate = (dateStr: string) => {
      if (!dateStr) return '';
      return new Date(dateStr).toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  // --- Renders for Documents ---

  const renderHeader = () => (
    <header className="border-b-2 border-slate-800 pb-4 mb-8 flex justify-between items-start">
        <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-blue-900 rounded-lg flex items-center justify-center text-white font-bold">AC</div>
            <div>
                <h1 className="text-xl font-bold text-slate-900 uppercase tracking-wider leading-tight">Alex Consulting</h1>
                <p className="text-sm font-semibold text-slate-600 uppercase tracking-widest">Servicios Médicos Ocupacionales</p>
                <p className="text-[10px] text-slate-500">RIF: J-12345678-9 | Av. Principal, Torre Salud.</p>
            </div>
        </div>
        <div className="text-right">
            <h2 className="text-lg font-bold text-slate-800 uppercase max-w-[200px] leading-tight">{getTitle()}</h2>
            <p className="text-xs text-slate-500 mt-1">Fecha: {new Date().toLocaleDateString()}</p>
        </div>
    </header>
  );

  const renderSignature = () => (
    <div className="mt-auto pt-16 flex justify-center">
        <div className="w-64 text-center">
            <div className="border-t border-slate-900 pt-2">
                <p className="font-bold text-sm uppercase">Dr. Alex Marcano</p>
                <p className="text-xs text-slate-600">Médico Ocupacional</p>
                <p className="text-xs text-slate-500">MPPS: 12345 | CM: 67890 | INPSASEL: LAR-123</p>
            </div>
        </div>
    </div>
  );

  // 1. MEDICAL REPORT CONTENT
  const renderMedicalContent = () => (
      <div className="flex-1 flex flex-col">
          {renderHeader()}

          <div className="space-y-6 text-sm text-slate-800 leading-relaxed">
              <div className="bg-slate-50 p-4 border border-slate-200 rounded">
                  <h3 className="font-bold text-slate-700 uppercase text-xs mb-3 border-b border-slate-300 pb-1">Datos del Paciente</h3>
                  <div className="grid grid-cols-2 gap-4">
                      <p><span className="font-bold">Nombre:</span> {patient?.firstName}</p>
                      <p><span className="font-bold">Cédula:</span> {patient?.cedula}</p>
                      <p><span className="font-bold">Edad:</span> {patient ? calculateAge(patient.birthDate) : ''} años</p>
                      <p><span className="font-bold">Empresa:</span> {patient?.company}</p>
                  </div>
              </div>

              <div>
                  <h3 className="font-bold text-slate-700 uppercase text-xs mb-2 border-b border-slate-300 pb-1">Motivo de Consulta</h3>
                  <p>{selectedAttention?.reason || 'Consulta General'}</p>
              </div>

              <div>
                  <h3 className="font-bold text-slate-700 uppercase text-xs mb-2 border-b border-slate-300 pb-1">Diagnóstico</h3>
                  <div className="whitespace-pre-wrap font-medium">{selectedAttention?.diagnosis}</div>
              </div>

              <div>
                  <h3 className="font-bold text-slate-700 uppercase text-xs mb-2 border-b border-slate-300 pb-1">Observaciones / Hallazgos</h3>
                  <p className="whitespace-pre-wrap">{selectedAttention?.observations || 'Sin hallazgos contributivos reportados.'}</p>
              </div>

              <div>
                  <h3 className="font-bold text-slate-700 uppercase text-xs mb-2 border-b border-slate-300 pb-1">Plan / Recomendaciones</h3>
                  <p className="whitespace-pre-wrap">{selectedAttention?.recommendations || 'Tratamiento según indicaciones médicas entregadas.'}</p>
              </div>
          </div>

          {renderSignature()}
      </div>
  );

  // 2. OCCUPATIONAL REPORT CONTENT
  const renderOccupationalContent = () => (
      <div className="flex-1 flex flex-col">
          {renderHeader()}

          <div className="flex-1 space-y-8 text-sm text-slate-900 leading-relaxed">
              <div className="text-center space-y-1 mb-8">
                  <h2 className="text-xl font-bold uppercase underline decoration-2 underline-offset-4">Certificado de Aptitud</h2>
              </div>

              <p className="text-justify">
                  Quien suscribe, Médico Ocupacional debidamente certificado, hace constar que ha evaluado al ciudadano(a): 
                  <span className="font-bold uppercase"> {patient?.firstName}</span>, 
                  titular de la Cédula de Identidad <span className="font-bold">N° {patient?.cedula}</span>, 
                  quien ocupa (o aspira ocupar) el cargo de: <span className="font-bold uppercase">{patient?.jobTitle}</span> 
                  en la empresa <span className="font-bold uppercase">{patient?.company}</span>.
              </p>

              <div className="border border-slate-300 p-6 rounded bg-slate-50">
                  <h3 className="font-bold uppercase text-center mb-4 text-slate-700">Resultado de la Evaluación</h3>

                  <div className="flex justify-center gap-8 mb-6">
                      <div className={`flex items-center gap-2 px-4 py-2 border-2 rounded-lg ${selectedAttention?.evaluationResult === 'Apto' ? 'border-green-600 bg-green-50' : 'border-slate-200 opacity-50'}`}>
                          <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${selectedAttention?.evaluationResult === 'Apto' ? 'border-green-600' : 'border-slate-400'}`}>
                              {selectedAttention?.evaluationResult === 'Apto' && <div className="w-3 h-3 bg-green-600 rounded-full" />}
                          </div>
                          <span className="font-bold text-lg">APTO</span>
                      </div>

                      <div className={`flex items-center gap-2 px-4 py-2 border-2 rounded-lg ${selectedAttention?.evaluationResult === 'Apto' /* Apto con limitaciones? logic usually here */ ? 'border-slate-200 opacity-50' : ''}`}>
                           {/* Simplified logic for this demo */}
                           <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${selectedAttention?.evaluationResult !== 'Apto' ? 'border-slate-800' : 'border-slate-400'}`}>
                              {selectedAttention?.evaluationResult !== 'Apto' && <div className="w-3 h-3 bg-slate-800 rounded-full" />}
                          </div>
                          <span className="font-bold text-lg uppercase">{selectedAttention?.evaluationResult !== 'Apto' ? selectedAttention?.evaluationResult : 'NO APTO / LIMITADO'}</span>
                      </div>
                  </div>

                  <div className="space-y-4">
                      <div>
                          <p className="font-bold text-xs uppercase text-slate-500">Diagnóstico Presuntivo / Ocupacional:</p>
                          <p className="font-medium">{selectedAttention?.diagnosis}</p>
                      </div>
                      <div>
                          <p className="font-bold text-xs uppercase text-slate-500">Recomendaciones:</p>
                          <p className="italic">{selectedAttention?.recommendations || 'Mantener medidas de higiene y seguridad laboral.'}</p>
                      </div>
                  </div>
              </div>

              <p className="text-xs text-slate-500 text-justify mt-8">
                  Este certificado se emite conforme a lo establecido en la LOPCYMAT y sus reglamentos parciales, basándose en la evaluación médica realizada el día <span className="font-bold">{formatDate(selectedAttention?.attentionDate || '')}</span>.
              </p>
          </div>

          {renderSignature()}
      </div>
  );

  // 3. SICK LEAVE REPORT CONTENT
  const renderSickLeaveContent = () => (
      <div className="flex-1 flex flex-col">
          {renderHeader()}

          <div className="flex-1 space-y-8 text-sm text-slate-900 leading-7">
              <div className="text-center mb-8">
                  <h2 className="text-xl font-bold uppercase">Constancia de Reposo Médico</h2>
              </div>

              <p className="text-justify indent-8">
                  Yo, <span className="font-bold">Dr. Alex Marcano</span>, Médico Ocupacional, certifico que he examinado en la fecha al ciudadano(a):
              </p>

              <div className="bg-slate-50 border-y border-slate-200 py-4 px-8 grid grid-cols-1 gap-2">
                  <p className="text-lg font-bold uppercase text-center">{patient?.firstName}</p>
                  <p className="text-center font-mono text-slate-700">C.I: {patient?.cedula}</p>
              </div>

              <p className="text-justify indent-8">
                  Quien presenta la siguiente condición de salud:
              </p>
              <div className="font-bold text-slate-800 bg-slate-50 p-4 border border-slate-200 rounded whitespace-pre-wrap">
                  {selectedAttention?.diagnosis}
              </div>

              <p className="text-justify indent-8">
                  Por tal motivo, se indica <strong>REPOSO MÉDICO</strong> por un lapso de 
                  <span className="font-bold text-lg mx-2 border-b-2 border-slate-800 px-2">{selectedAttention?.restDays}</span> 
                  días continuos, a contarse desde el:
              </p>

              <div className="flex justify-center gap-12 py-4">
                  <div className="text-center">
                      <p className="text-xs text-slate-500 uppercase tracking-wider">Fecha Inicio</p>
                      <p className="font-bold text-lg border-b border-slate-300 pb-1">{formatDate(selectedAttention?.restStartDate || '')}</p>
                  </div>
                  <div className="text-center">
                      <p className="text-xs text-slate-500 uppercase tracking-wider">Fecha Fin</p>
                      <p className="font-bold text-lg border-b border-slate-300 pb-1">{formatDate(selectedAttention?.restEndDate || '')}</p>
                  </div>
              </div>

              <p className="text-justify text-xs text-slate-500 mt-8">
                  Nota: Esta constancia debe ser validada por el Instituto Venezolano de los Seguros Sociales (IVSS) si el reposo excede los 3 días, conforme a la normativa legal vigente.
              </p>
          </div>

          {renderSignature()}
      </div>
  );

  return (
    <div className="max-w-6xl mx-auto pb-12">
      <h2 className="text-2xl font-bold text-slate-800 mb-2 flex items-center gap-2 print:hidden">
        {getIcon()}
        {getTitle()}
      </h2>
      <p className="text-slate-500 text-sm mb-6 print:hidden">Generación y visualización de documentos.</p>

      {/* SEARCH SECTION (Hidden on print) */}
      <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-8 print:hidden">
        <form onSubmit={handleSearch} className="flex gap-4 items-end">
          <div className="flex-1 max-w-md">
            <label className="block text-sm font-medium text-slate-700 mb-1">Cédula del Paciente</label>
            <div className="relative">
              <input 
                type="number" 
                value={searchCedula}
                onChange={(e) => setSearchCedula(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="Ingrese Cédula"
              />
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-3" />
            </div>
          </div>
          <button 
            type="submit"
            disabled={isSearching}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 transition-colors font-medium"
          >
            {isSearching ? 'Buscando...' : 'Buscar'}
          </button>
        </form>
        {error && <p className="text-red-500 text-sm mt-3 flex items-center gap-1"><AlertCircle className="w-3 h-3"/> {error}</p>}
      </section>

      {/* SELECTION LIST (If multiple attentions and none selected) */}
      {patient && !selectedAttention && attentions.length > 0 && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-8 animate-in fade-in slide-in-from-bottom-4">
            <h3 className="font-semibold text-slate-800 mb-4">Seleccione el registro para generar el documento:</h3>
            <div className="space-y-3">
                {attentions.map((att) => (
                    <div 
                        key={att.id} 
                        onClick={() => setSelectedAttention(att)}
                        className="p-4 border border-slate-200 rounded-lg hover:bg-blue-50 hover:border-blue-200 cursor-pointer transition-all flex justify-between items-center group"
                    >
                        <div>
                            <div className="font-bold text-slate-800 flex items-center gap-2">
                                {formatDate(att.attentionDate)}
                                {att.restDays > 0 && type === 'sick-leave' && (
                                    <span className="bg-orange-100 text-orange-700 text-xs px-2 py-0.5 rounded-full">Reposo: {att.restDays} días</span>
                                )}
                            </div>
                            <div className="text-sm text-slate-600">{att.attentionType} - {att.reason || 'Consulta General'}</div>
                        </div>
                        <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-blue-500" />
                    </div>
                ))}
            </div>
        </div>
      )}

      {patient && attentions.length === 0 && !isSearching && !error && (
          <div className="bg-yellow-50 text-yellow-800 p-4 rounded-lg border border-yellow-200 mb-6 flex items-center gap-2">
              <AlertCircle className="w-5 h-5" /> No se encontraron registros que coincidan con el tipo de reporte solicitado.
          </div>
      )}

      {/* PREVIEW & PRINT AREA */}
      {selectedAttention && patient && (
          <div className="animate-in fade-in zoom-in-95 duration-300">

              {/* Toolbar */}
              <div className="flex justify-between items-center mb-6 print:hidden">
                  <button 
                      onClick={() => setSelectedAttention(null)}
                      className="text-sm text-slate-500 hover:text-slate-800 font-medium underline"
                  >
                      ← Seleccionar otro registro
                  </button>
                  <button 
                      onClick={() => window.print()}
                      className="px-6 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 font-medium shadow-lg flex items-center gap-2"
                  >
                      <Printer className="w-4 h-4" /> Imprimir Documento
                  </button>
              </div>

              {/* The Paper */}
              <div className="bg-white shadow-xl border border-slate-200 rounded-none md:rounded-sm overflow-hidden w-full max-w-[216mm] mx-auto min-h-[279mm] p-[20mm] print:shadow-none print:border-0 print:w-full print:max-w-none print:p-0 flex flex-col">
                  {type === 'medical' && renderMedicalContent()}
                  {type === 'occupational' && renderOccupationalContent()}
                  {type === 'sick-leave' && renderSickLeaveContent()}

                  <div className="mt-8 pt-4 border-t border-slate-200 text-[10px] text-center text-slate-400">
                      Generado electrónicamente por sistema Alex Consulting el {new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}
                  </div>
              </div>
          </div>
      )}

    </div>
  );
};

export default MedicalReportGenerator;

