  const [rawPatients, setRawPatients] = useState<Patient[]>([]);
  const [companiesList, setCompaniesList] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);

  // Filter State
  const [selectedCompany, setSelectedCompany] = useState<string>(''); // Empty = All

  // --- Initial Data Load ---
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [atts, pats, comps] = await Promise.all([
            getAllMedicalAttentions(), 
            getAllPatients(),
            getCompanies()
        ]);
        setRawAttentions(atts);
        setRawPatients(pats);
        setCompaniesList(comps);
      } catch (e) {
        console.error("Error fetching data for reports", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // --- Helpers ---
  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const extractMainPathology = (diagnosis: string): string => {
    if (!diagnosis) return "Sin Diagnóstico";
    // Used primarily for Stats grouping
    const firstLine = diagnosis.split('\n')[0].trim();
    return firstLine.length > 50 ? firstLine.substring(0, 50) + '...' : firstLine;
  };

  // --- Data Processing & Filtering ---

  // 1. Filter Attentions by Date FIRST
  const dateFilteredAttentions = useMemo(() => {
    return rawAttentions.filter(att => {
      const attDate = att.attentionDate; // YYYY-MM-DD

      if (filterType === 'dia') {
        return attDate === dateStart;
      } else if (filterType === 'mes') {
        return attDate.startsWith(month);
      } else if (filterType === 'rango') {
        return attDate >= dateStart && attDate <= dateEnd;
      }
      return true;
    });
  }, [rawAttentions, filterType, dateStart, dateEnd, month]);

  // 2. Merge Patient Data AND Filter by Company (for Attentions & Pathologies tabs)
  const mergedData: MergedAttention[] = useMemo(() => {
    const joined = dateFilteredAttentions.map(att => {
      const patient = rawPatients.find(p => p.cedula === att.patientCedula);
      return {
        ...att,
        patientAge: patient ? calculateAge(patient.birthDate) : 0,
        patientCompany: patient ? patient.company : 'N/A',
        patientJob: patient ? patient.jobTitle : 'N/A',
        patientGender: patient ? patient.gender : 'N/A'
      };
    });

    // Apply Company Filter
    if (selectedCompany) {
        return joined.filter(item => item.patientCompany === selectedCompany);
    }

    return joined.sort((a, b) => new Date(a.attentionDate).getTime() - new Date(b.attentionDate).getTime());
  }, [dateFilteredAttentions, rawPatients, selectedCompany]);

  // 3. Filter Patients List (for Patients tab)
  const filteredPatients = useMemo(() => {
      if (selectedCompany) {
          return rawPatients.filter(p => p.company === selectedCompany);
      }
      return rawPatients;
  }, [rawPatients, selectedCompany]);

  // 4. Calculate Pathology Stats from the Merged (and filtered) Data
  const pathologyStats = useMemo(() => {
    const stats: Record<string, number> = {};
    mergedData.forEach(item => {
      const patho = extractMainPathology(item.diagnosis);
      stats[patho] = (stats[patho] || 0) + 1;
    });

    const sortedStats = Object.entries(stats)
      .map(([name, count]) => ({ name, count, percentage: ((count / mergedData.length) * 100).toFixed(1) }))
      .sort((a, b) => b.count - a.count);

    return sortedStats;
  }, [mergedData]);

  // --- Export Functions ---

  const exportToExcel = (fileName: string, sheetName: string, data: any[]) => {
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, sheetName);
    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportAttentions = () => {
    const exportData = mergedData.map(item => ({
      "Fecha": item.attentionDate,
      "Cédula": item.patientCedula,
      "Paciente": item.patientName,
      "Sexo": item.patientGender,
      "Edad": item.patientAge,
      "Empresa": item.patientCompany,
      "Cargo": item.patientJob,
      "Tipo Atención": item.attentionType,
      "Días Reposo": item.restDays,
      "Diagnóstico Completo": item.diagnosis, // Full diagnosis
      "Resultado": item.evaluationResult
    }));
    exportToExcel("Reporte_Atenciones", "Atenciones", exportData);
  };

  const handleExportPatients = () => {
    const exportData = filteredPatients.map(p => ({
      "Cédula": p.cedula,
      "Nombres y Apellidos": p.firstName,
      "Sexo": p.gender,
      "Fecha Nacimiento": p.birthDate,
      "Edad": calculateAge(p.birthDate),
      "Empresa": p.company,
      "Cargo": p.jobTitle,
      "Fecha Ingreso": p.entryDate,
      "Estatus": p.employmentStatus,
      "Teléfono": p.phone
    }));
    exportToExcel("Maestro_Pacientes", "Pacientes", exportData);
  };

  // --- Renders ---

  const renderFilters = () => (
    <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 mb-6 flex flex-col gap-4 animate-in fade-in slide-in-from-top-2">

      {/* Top Row: Company Selection */}
      <div className="flex items-center gap-4 pb-4 border-b border-slate-100">
          <Building2 className="w-5 h-5 text-slate-400" />
          <div className="flex-1">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Filtrar por Empresa</label>
              <select 
                value={selectedCompany}
                onChange={(e) => setSelectedCompany(e.target.value)}
                className="w-full max-w-md px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm bg-white"
              >
                  <option value="">-- Todas las Empresas --</option>
                  {companiesList.map(c => (
                      <option key={c.id} value={c.name}>{c.name}</option>
                  ))}
              </select>
          </div>
      </div>

      {/* Bottom Row: Date Filters (Only for Atenciones and Patologias) */}
      {activeTab !== 'pacientes' && (
        <div className="flex flex-col md:flex-row gap-4 items-end">
            <div className="w-full md:w-auto">
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Rango de Fecha</label>
                <div className="flex bg-slate-100 p-1 rounded-lg">
                <button 
                    onClick={() => setFilterType('dia')}
                    className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${filterType === 'dia' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    Día
                </button>
                <button 
                    onClick={() => setFilterType('mes')}
                    className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${filterType === 'mes' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    Mes
                </button>
                <button 
                    onClick={() => setFilterType('rango')}
                    className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${filterType === 'rango' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    Rango
                </button>
                </div>
            </div>

            {filterType === 'dia' && (
                <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Seleccionar Fecha</label>
                <input 
                    type="date" 
                    value={dateStart} 
                    onChange={(e) => setDateStart(e.target.value)}
                    className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
                </div>
            )}

            {filterType === 'mes' && (
                <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Seleccionar Mes</label>
                <input 
                    type="month" 
                    value={month} 
                    onChange={(e) => setMonth(e.target.value)}
                    className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
                </div>
            )}

            {filterType === 'rango' && (
                <div className="flex gap-2 items-end">
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Desde</label>
                    <input 
                    type="date" 
                    value={dateStart} 
                    onChange={(e) => setDateStart(e.target.value)}
                    className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Hasta</label>
                    <input 
                    type="date" 
                    value={dateEnd} 
                    onChange={(e) => setDateEnd(e.target.value)}
                    className="px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                    />
                </div>
                </div>
            )}

            <div className="ml-auto text-sm text-slate-500 pb-2">
                {mergedData.length} registros encontrados
            </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="max-w-6xl mx-auto pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <FileBarChart className="w-7 h-7 text-blue-600" />
            Centro de Reportes
          </h2>
          <p className="text-slate-500 mt-1">Generación de informes operativos y epidemiológicos.</p>
        </div>

        {/* Main Tabs */}
        <div className="flex p-1 bg-slate-100 rounded-xl">
           <button 
             onClick={() => setActiveTab('atenciones')}
             className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'atenciones' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
           >
             <Stethoscope className="w-4 h-4" /> Atenciones
           </button>
           <button 
             onClick={() => setActiveTab('patologias')}
             className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'patologias' ? 'bg-white text-purple-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
           >
             <Activity className="w-4 h-4" /> Patologías
           </button>
           <button 
             onClick={() => setActiveTab('pacientes')}
             className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'pacientes' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
           >
             <Users className="w-4 h-4" /> Pacientes
           </button>
        </div>
      </div>

      {/* --- REPORTE DE ATENCIONES --- */}
      {activeTab === 'atenciones' && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
           {renderFilters()}

           <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                 <h3 className="font-semibold text-slate-800">
                     Detalle Operacional de Consultas 
                     {selectedCompany && <span className="text-blue-600 ml-2">({selectedCompany})</span>}
                 </h3>
                 <button 
                   onClick={handleExportAttentions}
                   disabled={mergedData.length === 0}
                   className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:bg-slate-300 text-sm font-medium transition-colors"
                 >
                   <Download className="w-4 h-4" /> Exportar .xlsx
                 </button>
              </div>

              <div className="overflow-x-auto">
                 <table className="w-full text-sm text-left">
                    <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                       <tr>
                          <th className="px-4 py-3">Fecha</th>
                          <th className="px-4 py-3">Paciente</th>
                          <th className="px-4 py-3">Cédula</th>
                          <th className="px-4 py-3">Sexo</th>
                          <th className="px-4 py-3">Edad</th>
                          <th className="px-4 py-3">Empresa / Cargo</th>
                          <th className="px-4 py-3">Tipo Atención</th>
                          <th className="px-4 py-3 text-center">Reposo</th>
                          <th className="px-4 py-3">Diagnóstico</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {mergedData.length === 0 ? (
                         <tr>
                            <td colSpan={9} className="px-4 py-8 text-center text-slate-500 italic">No se encontraron registros para el período o empresa seleccionada.</td>
                         </tr>
                       ) : (
                         mergedData.map((row) => (
                           <tr key={row.id} className="hover:bg-slate-50">
                              <td className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">{row.attentionDate}</td>
                              <td className="px-4 py-3">{row.patientName}</td>
                              <td className="px-4 py-3 font-mono text-slate-600">{row.patientCedula}</td>
                              <td className="px-4 py-3">{row.patientGender}</td>
                              <td className="px-4 py-3">{row.patientAge}</td>
                              <td className="px-4 py-3">
                                 <div className="font-medium text-slate-800">{row.patientCompany}</div>
                                 <div className="text-xs text-slate-500">{row.patientJob}</div>
                              </td>
                              <td className="px-4 py-3">
                                 <span className="px-2 py-1 rounded-full bg-blue-50 text-blue-700 text-xs font-semibold">{row.attentionType}</span>
                              </td>
                              <td className="px-4 py-3 text-center">
                                 {row.restDays > 0 ? <span className="font-bold text-orange-600">{row.restDays} días</span> : '-'}
                              </td>
                              <td className="px-4 py-3 text-slate-600 text-xs whitespace-pre-wrap">
                                 {row.diagnosis}
                              </td>
                           </tr>
                         ))
                       )}
                    </tbody>
                 </table>
              </div>
           </div>
        </div>
      )}

      {/* --- REPORTE DE PATOLOGÍAS --- */}
      {activeTab === 'patologias' && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8">
           {renderFilters()}

           {/* Top Stats Cards */}
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
                 <div className="bg-purple-100 p-3 rounded-full mb-3 text-purple-600">
                    <Activity className="w-8 h-8" />
                 </div>
                 <h3 className="text-3xl font-bold text-slate-800">{mergedData.length}</h3>
                 <p className="text-sm text-slate-500 uppercase tracking-wide font-medium">Total Casos</p>
              </div>

              <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                 <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                   <PieChartIcon className="w-5 h-5 text-purple-600" />
                   Top 3 Causas de Morbilidad {selectedCompany && `(${selectedCompany})`}
                 </h4>
                 <div className="flex flex-col md:flex-row items-center gap-8">
                    <div className="h-48 w-48 relative">
                       {pathologyStats.length > 0 ? (
                         <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                              <Pie
                                data={pathologyStats.slice(0, 3)}
                                innerRadius={40}
                                outerRadius={80}
                                paddingAngle={5}
                                dataKey="count"
                              >
                                {pathologyStats.slice(0, 3).map((entry, index) => (
                                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                ))}
                              </Pie>
                              <RechartsTooltip />
                            </PieChart>
                         </ResponsiveContainer>
                       ) : <div className="flex items-center justify-center h-full text-slate-300">Sin datos</div>}
                    </div>
                    <div className="flex-1 space-y-3 w-full">
                       {pathologyStats.slice(0, 3).map((item, index) => (
                          <div key={index} className="flex items-center justify-between p-2 rounded bg-slate-50 border border-slate-100">
                             <div className="flex items-center gap-3">
                                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index] }}></div>
                                <span className="font-medium text-slate-700 truncate max-w-[150px] md:max-w-xs" title={item.name}>{item.name}</span>
                             </div>
                             <div className="text-right">
                                <span className="block font-bold text-slate-900">{item.count} casos</span>
                                <span className="text-xs text-slate-500">{item.percentage}%</span>
                             </div>
                          </div>
                       ))}
                       {pathologyStats.length === 0 && <p className="text-slate-500 italic text-sm">No hay registros para mostrar</p>}
                    </div>
                 </div>
              </div>
           </div>

           {/* Top 10 Chart & Table */}
           <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                 <h4 className="font-bold text-slate-800 mb-6">Top 10 Patologías Frecuentes</h4>
                 <div className="h-[350px] w-full">
                    {pathologyStats.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart
                          data={pathologyStats.slice(0, 10)}
                          layout="vertical"
                          margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
                        >
                          <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} />
                          <XAxis type="number" hide />
                          <YAxis type="category" dataKey="name" width={100} tick={{fontSize: 10}} interval={0} />
                          <RechartsTooltip />
                          <Bar dataKey="count" fill="#8884d8" radius={[0, 4, 4, 0]}>
                            {pathologyStats.slice(0, 10).map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="flex items-center justify-center h-full text-slate-400">Sin datos para graficar</div>
                    )}
                 </div>
              </div>

              <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                 <div className="p-4 bg-slate-50 border-b border-slate-200">
                    <h4 className="font-bold text-slate-800">Detalle de Morbilidad</h4>
                 </div>
                 <div className="overflow-y-auto max-h-[350px]">
                    <table className="w-full text-sm">
                       <thead className="bg-white sticky top-0 z-10 shadow-sm">
                          <tr className="text-xs text-slate-500 uppercase">
                             <th className="px-4 py-3 text-left">Patología</th>
                             <th className="px-4 py-3 text-right">Frecuencia</th>
                             <th className="px-4 py-3 text-right">%</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {pathologyStats.map((stat, idx) => (
                             <tr key={idx} className="hover:bg-slate-50">
                                <td className="px-4 py-2 font-medium text-slate-700">{stat.name}</td>
                                <td className="px-4 py-2 text-right">{stat.count}</td>
                                <td className="px-4 py-2 text-right text-slate-500">{stat.percentage}%</td>
                             </tr>
                          ))}
                          {pathologyStats.length === 0 && (
                            <tr><td colSpan={3} className="p-4 text-center text-slate-400">Sin datos</td></tr>
                          )}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* --- REPORTE DE PACIENTES --- */}
      {activeTab === 'pacientes' && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {renderFilters()}

           <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6 flex justify-between items-center">
              <div>
                 <h3 className="text-lg font-bold text-slate-800">
                     Maestro de Pacientes 
                     {selectedCompany && <span className="text-blue-600 ml-2">({selectedCompany})</span>}
                 </h3>
                 <p className="text-slate-500 text-sm">Listado general de empleados registrados en el sistema.</p>
              </div>
              <button 
                 onClick={handleExportPatients}
                 disabled={filteredPatients.length === 0}
                 className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white rounded-lg hover:bg-green-700 font-medium shadow-md transition-all hover:-translate-y-0.5 disabled:bg-slate-300"
               >
                 <Download className="w-4 h-4" /> Descargar Listado (.xlsx)
               </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                 <table className="w-full text-sm text-left">
                    <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                       <tr>
                          <th className="px-4 py-3">Cédula</th>
                          <th className="px-4 py-3">Nombre Completo</th>
                          <th className="px-4 py-3">Sexo</th>
                          <th className="px-4 py-3">Edad</th>
                          <th className="px-4 py-3">Empresa</th>
                          <th className="px-4 py-3">Cargo</th>
                          <th className="px-4 py-3">Fecha Ingreso</th>
                          <th className="px-4 py-3">Estatus</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {filteredPatients.length === 0 ? (
                         <tr><td colSpan={8} className="px-4 py-8 text-center text-slate-500">No hay pacientes registrados para esta selección.</td></tr>
                       ) : (
                        filteredPatients.sort((a,b) => a.cedula.localeCompare(b.cedula)).map((p) => (
                           <tr key={p.id} className="hover:bg-slate-50">
                              <td className="px-4 py-3 font-mono font-medium text-slate-700">{p.cedula}</td>
                              <td className="px-4 py-3">
                                 <div className="font-semibold text-slate-900">{p.firstName}</div>
                              </td>
                              <td className="px-4 py-3">{p.gender}</td>
                              <td className="px-4 py-3 text-slate-600">{calculateAge(p.birthDate)} años</td>
                              <td className="px-4 py-3">{p.company}</td>
                              <td className="px-4 py-3">{p.jobTitle}</td>
                              <td className="px-4 py-3 text-slate-500">{p.entryDate}</td>
                              <td className="px-4 py-3">
                                 <span className={`px-2 py-1 rounded text-xs font-semibold capitalize ${p.employmentStatus === 'fijo' ? 'bg-indigo-50 text-indigo-700' : 'bg-orange-50 text-orange-700'}`}>
                                    {p.employmentStatus}
                                 </span>
                              </td>
                           </tr>
                         ))
                       )}
                    </tbody>
                 </table>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useEffect, useMemo } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies } from '../utils/storage';
import { MedicalAttention, Patient, Company } from '../types';
import { Printer, ShieldCheck, Building2 } from 'lucide-react';
import { 
  PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, ResponsiveContainer 
} from 'recharts';

// --- Types ---
type Quarter = 'I' | 'II' | 'III' | 'IV';

// --- Constants ---
const REPORT_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

const SVEReport: React.FC = () => {
  // --- State ---
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');

  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);

  // Filter State
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  // --- Initial Data Load ---
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // --- Helpers ---
  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2]; // Jan, Feb, Mar
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const getQuarterRange = () => {
    const months = getQuarterMonths(selectedQuarter);
    return `Del 01 de ${getMonthName(months[0])} al ${new Date(selectedYear, months[2] + 1, 0).getDate()} de ${getMonthName(months[2])} de ${selectedYear}`;
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const getAgeGroup = (age: number) => {
    if (age < 25) return '18-24';
    if (age < 35) return '25-34';
    if (age < 45) return '35-44';
    if (age < 55) return '45-54';
    return '55+';
  };

  // --- Filtered Data Logic ---

  // 1. Filter Patients by Selected Company
  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return allPatients;
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  // 2. Filter Attentions by Patients in Scope (Company)
  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      // Get set of cedulas for O(1) lookup
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  // 3. Current Company Object
  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);


  // --- Statistics Calculation ---

  // 1. Attentions in current Quarter (Filtered by Company via attentionsInScope)
  const quarterAttentions = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    return attentionsInScope.filter(att => {
      const d = new Date(att.attentionDate);
      return d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
  }, [attentionsInScope, selectedYear, selectedQuarter]);

  // 2. Worker Stats Per Month Logic (Filtered by Company via patientsInScope)
  const getMonthlyWorkerStats = (monthIndex: number) => {
    // Active patients at the end of that month (entryDate <= last day of month)
    const lastDayOfMonth = new Date(selectedYear, monthIndex + 1, 0);
    const activePatients = patientsInScope.filter(p => new Date(p.entryDate) <= lastDayOfMonth);

    // Stats
    let male = 0, female = 0, disabled = 0;
    const ageGroups: Record<string, number> = {};

    activePatients.forEach(p => {
        if (p.gender === 'Masculino') male++; else female++;
        if (p.hasDisability) disabled++;
        const group = getAgeGroup(calculateAge(p.birthDate));
        ageGroups[group] = (ageGroups[group] || 0) + 1;
    });

    return { total: activePatients.length, male, female, disabled, ageGroups };
  };

  // 3. Exam Stats
  const examStats = useMemo(() => {
    const data = {
      'Pre Empleo': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Pre Vacaciones': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Egreso': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Periódica': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
    };

    quarterAttentions.forEach(att => {
       if (data[att.attentionType as keyof typeof data] && att.evaluationResult !== 'No Aplica') {
           data[att.attentionType as keyof typeof data].Total++;
           if (['Apto', 'No Apto', 'Postpuesta'].includes(att.evaluationResult)) {
               // @ts-ignore
               data[att.attentionType as keyof typeof data][att.evaluationResult]++;
           }
       }
    });
    return data;
  }, [quarterAttentions]);

  // 4. Morbidity & Accidents
  const morbidity = useMemo(() => {
     return {
        'Enfermedad Común': quarterAttentions.filter(a => a.reason === 'Enfermedad Común'),
        'Enfermedad Ocupacional': quarterAttentions.filter(a => a.reason === 'Enfermedad Ocupacional'),
        'Accidente Común': quarterAttentions.filter(a => a.reason === 'Accidente Común'),
        'Accidente Ocupacional': quarterAttentions.filter(a => a.reason === 'Accidente Ocupacional'),
     };
  }, [quarterAttentions]);

  // 5. Reposos Summary
  const restStats = useMemo(() => {
     const stats = {
        'Enfermedad Común': { count: 0, days: 0 },
        'Enfermedad Ocupacional': { count: 0, days: 0 },
        'Accidente Común': { count: 0, days: 0 },
        'Accidente Ocupacional': { count: 0, days: 0 },
     };
     quarterAttentions.forEach(a => {
        if (a.reason && a.restDays > 0) {
            stats[a.reason].count++;
            stats[a.reason].days += a.restDays;
        }
     });
     return stats;
  }, [quarterAttentions]);

  // 6. Referrals
  const referrals = useMemo(() => {
      return quarterAttentions.filter(a => a.medicalReferral && a.medicalReferral.trim() !== '');
  }, [quarterAttentions]);


  // --- Render Sections ---

  const HeaderSection = () => (
    <div className="flex justify-between items-center mb-8 border-b-2 border-slate-800 pb-4">
       <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-200 rounded flex items-center justify-center text-xs text-slate-500 font-bold border border-slate-300">LOGO</div>
          <div>
             <h1 className="text-xl font-bold text-slate-900 uppercase">
                 {currentCompany ? currentCompany.name : 'ALEX CONSULTING C.A.'}
             </h1>
             <p className="text-sm font-semibold text-slate-700">
                 {currentCompany ? `RIF: ${currentCompany.rif}` : 'RIF: J-12345678-9'}
             </p>
             <p className="text-sm text-slate-600">Servicio de Seguridad y Salud en el Trabajo</p>
          </div>
       </div>
       <div className="text-right">
          <h2 className="text-lg font-bold text-slate-800 uppercase">Informe Trimestral SVE</h2>
          <p className="text-sm font-medium text-slate-700">Trimestre: {selectedQuarter} - {selectedYear}</p>
          <p className="text-xs text-slate-500 mt-1">{new Date().toLocaleDateString()}</p>
       </div>
    </div>
  );

  const FooterSignature = ({ isLastPage = false }: { isLastPage?: boolean }) => (
     <div className="mt-auto pt-8">
        {isLastPage && (
            <div className="grid grid-cols-3 gap-8 mb-12">
               <div className="text-center">
                  <div className="border-t border-slate-800 pt-2 mb-1"></div>
                  <p className="font-bold text-xs uppercase">Comité de Seguridad y Salud (CSSL)</p>
                  <p className="text-[10px] text-slate-500">Delegado de Prevención</p>
               </div>
               <div className="text-center">
                  <div className="border-t border-slate-800 pt-2 mb-1"></div>
                  <p className="font-bold text-xs uppercase">Comité de Seguridad y Salud (CSSL)</p>
                  <p className="text-[10px] text-slate-500">Representante Patrono</p>
               </div>
               <div className="text-center">
                  <div className="border-t border-slate-800 pt-2 mb-1"></div>
                  <p className="font-bold text-xs uppercase">Ing. Seguridad Industrial</p>
                  <p className="text-[10px] text-slate-500">Reg. INPSASEL: LAR-123456</p>
               </div>
            </div>
        )}

        {/* Doctor Signs All Pages */}
        <div className="flex justify-center">
           <div className="text-center w-64">
              <div className="border-t border-slate-800 pt-2 mb-1"></div>
              <p className="font-bold text-xs uppercase">Dr. Alex Marcano</p>
              <p className="text-[10px] text-slate-600 font-medium">Médico Ocupacional</p>
              <p className="text-[10px] text-slate-500">CM: 12345 | MPPS: 67890</p>
           </div>
        </div>
        <div className="text-center mt-4">
           <p className="text-[10px] text-slate-400">Pag. <span className="page-number"></span></p>
        </div>
     </div>
  );

  if (loading) return <div className="p-8 text-center text-slate-500">Generando reporte...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">

      {/* --- Controls (Hidden on Print) --- */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 print:hidden flex flex-col gap-6">

         <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
            <ShieldCheck className="w-5 h-5 text-blue-600" />
            <div>
                <h2 className="text-lg font-bold text-slate-800">Generador de Informe SVE</h2>
                <p className="text-xs text-slate-500">Epidemiología Ocupacional (LOPCYMAT / NT-03-2016)</p>
            </div>
         </div>

         <div className="flex flex-col md:flex-row gap-4 items-end">
             {/* Company Select */}
            <div className="flex-1 w-full">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Empresa a Reportar</label>
               <div className="relative">
                   <select 
                     value={selectedCompanyName}
                     onChange={(e) => setSelectedCompanyName(e.target.value)}
                     className="w-full px-3 py-2 pl-9 border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                   >
                       <option value="">-- Seleccionar Empresa --</option>
                       {companies.map(c => (
                           <option key={c.id} value={c.name}>{c.name}</option>
                       ))}
                   </select>
                   <Building2 className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
               </div>
            </div>

            {/* Year Select */}
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Año</label>
               <input 
                 type="number" 
                 value={selectedYear} 
                 onChange={(e) => setSelectedYear(Number(e.target.value))}
                 className="px-3 py-2 border border-slate-300 rounded-lg text-sm w-24 outline-none focus:ring-2 focus:ring-blue-500"
               />
            </div>

            {/* Quarter Select */}
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Trimestre</label>
               <select 
                 value={selectedQuarter} 
                 onChange={(e) => setSelectedQuarter(e.target.value as Quarter)}
                 className="px-3 py-2 border border-slate-300 rounded-lg text-sm w-32 outline-none focus:ring-2 focus:ring-blue-500 bg-white"
               >
                 <option value="I">I (Ene-Mar)</option>
                 <option value="II">II (Abr-Jun)</option>
                 <option value="III">III (Jul-Sep)</option>
                 <option value="IV">IV (Oct-Dic)</option>
               </select>
            </div>

            <button 
              onClick={() => window.print()}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 flex items-center gap-2 h-[38px] shadow-sm"
            >
              <Printer className="w-4 h-4" /> Imprimir
            </button>
         </div>
      </div>

      {/* --- REPORT PAGES CONTAINER (Visible in Print) --- */}
      <div className="print-container text-slate-900 bg-white md:p-12 print:p-0 rounded-xl shadow-lg print:shadow-none">

        {/* CSS for printing simulation */}
        <style>{`
          @media print {
            body { background: white; -webkit-print-color-adjust: exact; }
            .print-hidden { display: none !important; }
            .print-container { box-shadow: none; padding: 0; }
            .page-break { page-break-after: always; min-height: 100vh; display: flex; flex-direction: column; padding: 15mm; }
            .page-break:last-child { page-break-after: auto; }
            /* Footer positioning hack for simplified layout */
            @page { size: A4; margin: 0; }
          }
          .page-break { min-height: 297mm; position: relative; display: flex; flex-direction: column; background: white; margin-bottom: 20px; box-shadow: 0 0 10px rgba(0,0,0,0.05); padding: 20mm; }
          @media print { .page-break { margin-bottom: 0; box-shadow: none; } }

          table { width: 100%; border-collapse: collapse; font-size: 11px; }
          th, td { border: 1px solid #cbd5e1; padding: 6px; text-align: left; }
          th { background-color: #f1f5f9; font-weight: bold; text-transform: uppercase; color: #334155; }
        `}</style>

        {/* --- PAGE 1: PORTADA Y REGISTRO DE TRABAJADORES --- */}
        <div className="page-break">
            <HeaderSection />

            <div className="flex-1">
               <div className="bg-slate-100 p-6 rounded-lg border border-slate-300 mb-8 text-center">
                  <h1 className="text-2xl font-bold text-slate-800 uppercase mb-2">Informe Trimestral de Vigilancia Epidemiológica</h1>
                  <h3 className="text-lg font-medium text-slate-600">{getQuarterRange()}</h3>
                  <div className="mt-6 text-left max-w-md mx-auto text-sm space-y-2 bg-white p-4 rounded border border-slate-200">
                     <p><strong>Entidad de Trabajo:</strong> {currentCompany ? currentCompany.name : 'ALEX CONSULTING C.A.'}</p>
                     <p><strong>Dirección:</strong> {currentCompany ? currentCompany.address : 'Av. Principal, Edif. Torre Salud, Piso 3.'}</p>
                     <p><strong>Actividad Económica:</strong> {currentCompany ? 'Empresa Registrada' : 'Servicios Profesionales de Salud.'}</p>
                  </div>
               </div>

               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1 mt-8">1. Registro Mensual de Trabajadores (Discriminación)</h3>

               <table className="mb-6">
                  <thead>
                     <tr>
                        <th>Mes</th>
                        <th>Total</th>
                        <th>Hombres</th>
                        <th>Mujeres</th>
                        <th>Discapacidad</th>
                        <th>18-24</th>
                        <th>25-34</th>
                        <th>35-44</th>
                        <th>45-54</th>
                        <th>55+</th>
                     </tr>
                  </thead>
                  <tbody>
                     {getQuarterMonths(selectedQuarter).map(monthIndex => {
                        const stats = getMonthlyWorkerStats(monthIndex);
                        return (
                           <tr key={monthIndex}>
                              <td className="font-bold">{getMonthName(monthIndex)}</td>
                              <td className="font-bold bg-slate-50 text-center">{stats.total}</td>
                              <td className="text-center">{stats.male}</td>
                              <td className="text-center">{stats.female}</td>
                              <td className="text-center">{stats.disabled}</td>
                              <td className="text-center">{stats.ageGroups['18-24'] || 0}</td>
                              <td className="text-center">{stats.ageGroups['25-34'] || 0}</td>
                              <td className="text-center">{stats.ageGroups['35-44'] || 0}</td>
                              <td className="text-center">{stats.ageGroups['45-54'] || 0}</td>
                              <td className="text-center">{stats.ageGroups['55+'] || 0}</td>
                           </tr>
                        );
                     })}
                  </tbody>
               </table>
            </div>

            <FooterSignature />
        </div>

        {/* --- PAGE 2: MORBILIDAD Y ACCIDENTALIDAD --- */}
        <div className="page-break">
            <HeaderSection />

            <div className="flex-1 space-y-8">
               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">2. Registro de Accidentes y Enfermedades</h3>

               {/* Grid for 4 categories */}
               <div className="grid grid-cols-1 gap-6">
                  {Object.entries(morbidity).map(([type, list]: [string, MedicalAttention[]]) => (
                     <div key={type} className="border border-slate-200 rounded p-4">
                        <h4 className="font-bold text-xs uppercase mb-3 bg-slate-50 p-2 border-b border-slate-200 flex justify-between">
                           {type}
                           <span className="bg-slate-800 text-white px-2 rounded text-[10px] flex items-center">{list.length} Casos</span>
                        </h4>

                        {list.length > 0 ? (
                           <table className="text-[10px]">
                              <thead>
                                 <tr>
                                    <th>Fecha</th>
                                    <th>Paciente</th>
                                    <th>Diagnóstico</th>
                                    <th>Reposo</th>
                                 </tr>
                              </thead>
                              <tbody>
                                 {list.map(item => (
                                    <tr key={item.id}>
                                       <td>{new Date(item.attentionDate).toLocaleDateString()}</td>
                                       <td>{item.patientName}</td>
                                       <td className="whitespace-pre-wrap">{item.diagnosis}</td>
                                       <td>{item.restDays > 0 ? `${item.restDays} días` : '-'}</td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        ) : (
                           <p className="text-xs text-slate-400 italic text-center py-2">Sin registros en este trimestre.</p>
                        )}
                     </div>
                  ))}
               </div>

               {/* REPOSOS SUMMARY */}
               <div className="mt-6">
                  <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">3. Registro de Reposos (Resumen)</h3>
                  <table>
                     <thead>
                        <tr>
                           <th>Motivo</th>
                           <th className="text-center">N° de Casos</th>
                           <th className="text-center">Total Días Perdidos</th>
                        </tr>
                     </thead>
                     <tbody>
                        {Object.entries(restStats).map(([reason, stat]: [string, { count: number; days: number }]) => (
                           <tr key={reason}>
                              <td>{reason}</td>
                              <td className="text-center font-bold">{stat.count}</td>
                              <td className="text-center font-bold">{stat.days}</td>
                           </tr>
                        ))}
                        <tr className="bg-slate-50 font-bold">
                           <td>TOTAL GENERAL</td>
                           <td className="text-center">{Object.values(restStats).reduce((acc: number, curr: { count: number; days: number }) => acc + curr.count, 0)}</td>
                           <td className="text-center">{Object.values(restStats).reduce((acc: number, curr: { count: number; days: number }) => acc + curr.days, 0)}</td>
                        </tr>
                     </tbody>
                  </table>
               </div>
            </div>

            <FooterSignature />
        </div>

        {/* --- PAGE 3: RESULTADOS EXÁMENES Y REFERENCIAS --- */}
        <div className="page-break">
            <HeaderSection />

            <div className="flex-1 space-y-8">

               {/* EXAMENES */}
               <div>
                   <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">4. Resultados de Exámenes de Salud</h3>
                   <div className="grid grid-cols-2 gap-6 mb-6">
                      {Object.entries(examStats).map(([type, stats]: [string, { Apto: number; 'No Apto': number; Postpuesta: number; Total: number }], idx) => (
                         stats.Total > 0 && (
                            <div key={type} className="border border-slate-200 p-4 rounded bg-slate-50 break-inside-avoid">
                               <h5 className="font-bold text-xs uppercase text-center mb-2">{type}</h5>
                               <div className="h-40 relative">
                                  <ResponsiveContainer width="100%" height="100%">
                                     <PieChart>
                                        <Pie
                                           data={[
                                              { name: 'Apto', value: stats.Apto },
                                              { name: 'No Apto', value: stats['No Apto'] },
                                              { name: 'Postpuesta', value: stats.Postpuesta }
                                           ]}
                                           cx="50%" cy="50%"
                                           innerRadius={30} outerRadius={60}
                                           dataKey="value"
                                        >
                                           <Cell fill="#22c55e" /> {/* Apto */}
                                           <Cell fill="#ef4444" /> {/* No Apto */}
                                           <Cell fill="#f59e0b" /> {/* Postpuesta */}
                                        </Pie>
                                        <Legend verticalAlign="bottom" height={36} iconSize={8} wrapperStyle={{fontSize: '10px'}}/>
                                        <RechartsTooltip />
                                     </PieChart>
                                  </ResponsiveContainer>
                               </div>
                               <div className="text-[10px] text-center mt-1 space-x-2">
                                  <span>Total Evaluados: <strong>{stats.Total}</strong></span>
                               </div>
                            </div>
                         )
                      ))}
                   </div>
                   {Object.values(examStats).every((s: { Total: number }) => s.Total === 0) && (
                      <p className="text-sm text-slate-500 italic border border-dashed border-slate-300 p-4 text-center rounded">No se registraron evaluaciones médicas ocupacionales en este período.</p>
                   )}
               </div>

               {/* REFERENCIAS */}
               <div>
                  <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">5. Referencias a Centros Especializados</h3>
                  {referrals.length > 0 ? (
                     <table>
                        <thead>
                           <tr>
                              <th>Fecha</th>
                              <th>Paciente</th>
                              <th>Especialidad / Centro</th>
                              <th>Motivo / Diagnóstico Presuntivo</th>
                           </tr>
                        </thead>
                        <tbody>
                           {referrals.map(ref => (
                              <tr key={ref.id}>
                                 <td>{new Date(ref.attentionDate).toLocaleDateString()}</td>
                                 <td>{ref.patientName}</td>
                                 <td className="font-bold">{ref.medicalReferral}</td>
                                 <td className="text-xs whitespace-pre-wrap">{ref.diagnosis}</td>
                              </tr>
                           ))}
                        </tbody>
                     </table>
                  ) : (
                     <p className="text-sm text-slate-500 italic border border-dashed border-slate-300 p-4 text-center rounded">No se generaron referencias médicas en este período.</p>
                  )}
               </div>

               {/* FACTORES DE RIESGO (Static for now) */}
               <div>
                  <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">6. Factores de Riesgo y Discapacidad</h3>
                  <div className="text-xs text-slate-700 space-y-2 border border-slate-200 p-4 rounded">
                     <p><strong>Población con Discapacidad Certificada:</strong> {patientsInScope.filter(p => p.hasDisability).length} Trabajadores.</p>
                     <p className="mt-2 font-bold">Principales Factores de Riesgo Identificados (Matriz de Riesgos):</p>
                     <ul className="list-disc pl-5 space-y-1">
                        <li>Ergonómicos: Posturas forzadas y movimientos repetitivos (Áreas Administrativas y Operativas).</li>
                        <li>Físicos: Ruido intermitente (Área de Planta).</li>
                        <li>Psicosociales: Estrés laboral asociado a carga de trabajo.</li>
                     </ul>
                  </div>
               </div>

            </div>

            <FooterSignature isLastPage={true} />
        </div>

      </div>
    </div>
  );
};

