interface LoginProps {
  onLogin: (user: AppUser) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const users = await getUsers();
      // Simple Auth check (In production, use hashing)
      const user = users.find(u => u.username === username && u.password === password);

      if (user) {
        // Simulate network delay for effect
        setTimeout(() => {
            onLogin(user);
        }, 500);
      } else {
        setLoading(false);
        setError('Credenciales inválidas. Intente nuevamente.');
      }
    } catch (err) {
      setLoading(false);
      setError('Error al conectar con la base de datos local.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-500">

