                        <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                            <div>
                                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                    <Clock className="w-5 h-5 text-blue-600" />
                                    Citas del Día
                                </h3>
                                <p className="text-xs text-slate-500 mt-0.5 capitalize">
                                    {new Date().toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                                </p>
                            </div>
                            <span className="bg-blue-100 text-blue-700 text-xs font-bold px-3 py-1 rounded-full">
                                {todayAppointments.length} Total
                            </span>
                        </div>

                        <div className="flex-1 overflow-y-auto max-h-[500px] p-2">
                            {todayAppointments.length === 0 ? (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 p-8">
                                    <Calendar className="w-12 h-12 mb-3 opacity-20" />
                                    <p>No hay citas programadas para hoy.</p>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {todayAppointments.map((app) => (
                                        <div key={app.id} className="flex items-center gap-4 p-4 bg-white border border-slate-100 rounded-lg hover:shadow-md hover:border-blue-200 transition-all group">
                                            {/* Time Column */}
                                            <div className="flex flex-col items-center justify-center w-16 h-16 bg-blue-50 text-blue-700 rounded-lg shrink-0 border border-blue-100">
                                                <span className="text-lg font-bold">{app.time}</span>
                                            </div>

                                            {/* Info Column */}
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 mb-0.5">
                                                    <h4 className="font-bold text-slate-800 truncate">{app.patientName}</h4>
                                                    <span className={`text-[10px] px-2 py-0.5 rounded-full uppercase font-bold tracking-wider ${
                                                        app.type.includes('Examen') ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                                                    }`}>
                                                        {app.type.replace('Examen ', '')}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-4 text-sm text-slate-500">
                                                    <span className="flex items-center gap-1 font-mono bg-slate-50 px-1.5 rounded text-xs">
                                                        C.I: {app.patientCedula}
                                                    </span>
                                                </div>
                                            </div>

                                            {/* Action/Status Column */}
                                            <div className="shrink-0 text-right">
                                                 <button 
                                                    onClick={() => setCurrentView('atencion')}
                                                    className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-full transition-colors"
                                                    title="Ir a Atención"
                                                 >
                                                     <CheckCircle2 className="w-5 h-5" />
                                                 </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

            </div>
          </div>
        );
    }
  };

  // --- Auth Guard ---
  if (!user) {
      return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex">
      {/* Sidebar Component */}
      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        onNavigate={(view) => {
            if(view === 'cerrar-sesión') handleLogout();
            else setCurrentView(view);
        }}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col lg:ml-72 transition-all duration-300">

        {/* Mobile Header Bar */}
        <header className="lg:hidden bg-white shadow-sm p-4 flex items-center justify-between sticky top-0 z-30 print:hidden">
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="p-2 hover:bg-slate-100 rounded-md text-slate-700"
            >
              <Menu className="w-6 h-6" />
            </button>
            <span className="font-semibold text-slate-800">Afamed Ocupacional</span>
          </div>
        </header>

        {/* Content Placeholder */}
        <main className="p-6 md:p-8 overflow-y-auto min-h-[calc(100vh-64px)] lg:min-h-screen">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

