                        </div>

                        <div className="flex-1 overflow-y-auto max-h-[500px] p-2">
                            {todayAppointments.length === 0 ? (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 p-8">
                                    <Calendar className="w-12 h-12 mb-3 opacity-20" />
                                    <p>No hay citas programadas para hoy.</p>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {todayAppointments.map((app) => (
                                        <div key={app.id} className="flex items-center gap-4 p-4 bg-white border border-slate-100 rounded-lg hover:shadow-md hover:border-blue-200 transition-all group">
                                            {/* Time Column */}
                                            <div className="flex flex-col items-center justify-center w-16 h-16 bg-blue-50 text-blue-700 rounded-lg shrink-0 border border-blue-100">
                                                <span className="text-lg font-bold">{app.time}</span>
                                            </div>

                                            {/* Info Column */}
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 mb-0.5">
                                                    <h4 className="font-bold text-slate-800 truncate">{app.patientName}</h4>
                                                    <span className={`text-[10px] px-2 py-0.5 rounded-full uppercase font-bold tracking-wider ${
                                                        app.type.includes('Examen') ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                                                    }`}>
                                                        {app.type.replace('Examen ', '')}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-4 text-sm text-slate-500">
                                                    <span className="flex items-center gap-1 font-mono bg-slate-50 px-1.5 rounded text-xs">
                                                        C.I: {app.patientCedula}
                                                    </span>
                                                </div>
                                            </div>

                                            {/* Action/Status Column */}
                                            <div className="shrink-0 text-right">
                                                 <button 
                                                    onClick={() => setCurrentView('atencion')}
