                  </div>
               </div>

               {/* TABLA DE CARGOS (New Section) */}
               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1 mt-4">Distribución de Trabajadores por Cargo</h3>
               <table className="mb-8">
                  <thead>
