                        <th className="text-center">Cantidad de Trabajadores</th>
                     </tr>
                  </thead>
                  <tbody>
                     {jobTitleStats.length === 0 ? (
                        <tr>
                            <td colSpan={2} className="text-center text-slate-400 italic py-4">No se encontraron trabajadores registrados para esta empresa.</td>
                        </tr>
                     ) : (
