                  <thead>
                     <tr>
                        <th>Mes</th>
                        <th>Total</th>
                        <th>Hombres</th>
                        <th>Mujeres</th>
                        <th>Discapacidad</th>
                        <th>18-24</th>
                        <th>25-34</th>
                        <th>35-44</th>
                        <th>45-54</th>
                        <th>55+</th>
                     </tr>
                  </thead>
