                         stats.Total > 0 && (
                            <div key={type} className="border border-slate-200 p-4 rounded bg-slate-50 break-inside-avoid">
                               <h5 className="font-bold text-xs uppercase text-center mb-2">{type}</h5>
                               <div className="h-40 relative">
                                  <ResponsiveContainer width="100%" height="100%">
                                     <PieChart>
                                        <Pie
                                           data={[
                                              { name: 'Apto', value: stats.Apto },
                                              { name: 'No Apto', value: stats['No Apto'] },
                                              { name: 'Postpuesta', value: stats.Postpuesta }
                                           ]}
                                           cx="50%" cy="50%"
                                           innerRadius={30} outerRadius={60}
                                           dataKey="value"
                                        >
                                           <Cell fill="#22c55e" /> {/* Apto */}
                                           <Cell fill="#ef4444" /> {/* No Apto */}
                                           <Cell fill="#f59e0b" /> {/* Postpuesta */}
                                        </Pie>
                                        <Legend verticalAlign="bottom" height={36} iconSize={8} wrapperStyle={{fontSize: '10px'}}/>
                                        <RechartsTooltip />
                                     </PieChart>
                                  </ResponsiveContainer>
                               </div>
                               <div className="text-[10px] text-center mt-1 space-x-2">
                                  <span>Total Evaluados: <strong>{stats.Total}</strong></span>
                               </div>
                            </div>
                         )
                      ))}
                   </div>
                   {Object.values(examStats).every((s: { Total: number }) => s.Total === 0) && (
                      <p className="text-sm text-slate-500 italic border border-dashed border-slate-300 p-4 text-center rounded">No se registraron evaluaciones médicas ocupacionales en este período.</p>
                   )}
               </div>

               {/* REFERENCIAS */}
               <div>
                  <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">5. Referencias a Centros Especializados</h3>
                  {referrals.length > 0 ? (
                     <table>
                        <thead>
                           <tr>
                              <th>Fecha</th>
                              <th>Paciente</th>
                              <th>Especialidad / Centro</th>
                              <th>Motivo / Diagnóstico Presuntivo</th>
                           </tr>
                        </thead>
                        <tbody>
                           {referrals.map(ref => (
                              <tr key={ref.id}>
                                 <td>{new Date(ref.attentionDate).toLocaleDateString()}</td>
                                 <td>{ref.patientName}</td>
                                 <td className="font-bold">{ref.medicalReferral}</td>
                                 <td className="text-xs whitespace-pre-wrap">{ref.diagnosis}</td>
                              </tr>
                           ))}
                        </tbody>
                     </table>
                  ) : (
                     <p className="text-sm text-slate-500 italic border border-dashed border-slate-300 p-4 text-center rounded">No se generaron referencias médicas en este período.</p>
                  )}
               </div>

               {/* FACTORES DE RIESGO */}
               <div>
                  <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">6. Factores de Riesgo y Discapacidad</h3>
                  <div className="text-xs text-slate-700 space-y-2 border border-slate-200 p-4 rounded">
                     <p><strong>Población con Discapacidad Certificada:</strong> {patientsInScope.filter(p => p.hasDisability).length} Trabajadores.</p>
                     <p className="mt-2 font-bold">Principales Factores de Riesgo Identificados (Matriz de Riesgos):</p>
                     <ul className="list-disc pl-5 space-y-1">
                        <li>Ergonómicos: Posturas forzadas y movimientos repetitivos (Áreas Administrativas y Operativas).</li>
                        <li>Físicos: Ruido intermitente (Área de Planta).</li>
                        <li>Psicosociales: Estrés laboral asociado a carga de trabajo.</li>
                     </ul>
                  </div>
               </div>

            </div>

            <FooterSignature isLastPage={true} />
        </div>

      </div>
    </div>
  );
};

