import React, { useState, useEffect, useMemo } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies } from '../utils/storage';
import { MedicalAttention, Patient, Company } from '../types';
import { Printer, ShieldCheck, Building2 } from 'lucide-react';
import { 
  PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, ResponsiveContainer 
} from 'recharts';

// --- Types ---
type Quarter = 'I' | 'II' | 'III' | 'IV';

// --- Constants ---
const COLORS_GENDER = ['#2563eb', '#db2777']; // Blue, Pink
const COLORS_DISABILITY = ['#059669', '#dc2626']; // Green, Red
const COLORS_AGE = ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444'];

const SVEReport: React.FC = () => {
  // --- State ---
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');

  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  // --- Initial Data Load ---
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // --- Helpers ---
  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2];
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const getQuarterRange = () => {
    const months = getQuarterMonths(selectedQuarter);
    return `Del 01 de ${getMonthName(months[0])} al ${new Date(selectedYear, months[2] + 1, 0).getDate()} de ${getMonthName(months[2])} de ${selectedYear}`;
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const getAgeGroup = (age: number) => {
    if (age < 25) return '18-24';
    if (age < 35) return '25-34';
    if (age < 45) return '35-44';
    if (age < 55) return '45-54';
    return '55+';
  };

  // --- Filtered Data Logic ---
  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return allPatients;
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);

  // --- Statistics Logic (Demographics) ---
  const demographics = useMemo(() => {
    const total = patientsInScope.length;
    if (total === 0) return null;

    const stats = {
        gender: { male: 0, female: 0 },
        disability: { yes: 0, no: 0 },
        age: { '18-24': 0, '25-34': 0, '35-44': 0, '45-54': 0, '55+': 0 }
    };

    patientsInScope.forEach(p => {
        // Sexo
        if (p.gender === 'Masculino') stats.gender.male++; else stats.gender.female++;
        // Discapacidad
        if (p.hasDisability) stats.disability.yes++; else stats.disability.no++;
        // Edad
        const group = getAgeGroup(calculateAge(p.birthDate));
        // @ts-ignore
        stats.age[group]++;
    });

    return stats;
  }, [patientsInScope]);

  const jobTitleStats = useMemo(() => {
    const stats: Record<string, number> = {};
    patientsInScope.forEach(p => {
        const title = p.jobTitle || 'Sin Cargo Definido';
        stats[title] = (stats[title] || 0) + 1;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [patientsInScope]);

  // --- Render Helpers ---

  const HeaderSection = () => (
    <div className="flex justify-between items-center mb-8 border-b-2 border-slate-800 pb-4">
       <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-200 rounded flex items-center justify-center text-xs text-slate-500 font-bold border border-slate-300">LOGO</div>
          <div>
             <h1 className="text-xl font-bold text-slate-900 uppercase">
                 {currentCompany ? currentCompany.name : 'ALEX CONSULTING'}
             </h1>
             <p className="text-sm font-semibold text-slate-700">
                 {currentCompany ? `RIF: ${currentCompany.rif}` : 'RIF: J-12345678-9'}
             </p>
             <p className="text-sm text-slate-600">Servicio de Seguridad y Salud en el Trabajo</p>
          </div>
       </div>
       <div className="text-right">
          <h2 className="text-lg font-bold text-slate-800 uppercase">Informe Trimestral SVE</h2>
          <p className="text-sm font-medium text-slate-700">Trimestre: {selectedQuarter} - {selectedYear}</p>
          <p className="text-xs text-slate-500 mt-1">{new Date().toLocaleDateString()}</p>
       </div>
    </div>
  );

  const FooterSignature = () => (
     <div className="mt-auto pt-8 flex justify-center">
        <div className="text-center w-64">
           <div className="border-t border-slate-800 pt-2 mb-1"></div>
           <p className="font-bold text-xs uppercase">Dr. Alex Marcano</p>
           <p className="text-[10px] text-slate-600 font-medium">Médico Ocupacional</p>
           <p className="text-[10px] text-slate-500">CM: 12345 | MPPS: 67890</p>
        </div>
     </div>
  );

  if (loading) return <div className="p-8 text-center text-slate-500">Generando reporte...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">

      {/* --- Controls --- */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 print:hidden flex flex-col gap-6">
         <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
            <ShieldCheck className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-bold text-slate-800">Generador de Informe SVE</h2>
         </div>
         <div className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Empresa</label>
               <select 
                 value={selectedCompanyName}
                 onChange={(e) => setSelectedCompanyName(e.target.value)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
               >
                   <option value="">-- Seleccionar Empresa --</option>
                   {companies.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
               </select>
            </div>
            <button onClick={() => window.print()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm">
              <Printer className="w-4 h-4" /> Imprimir
            </button>
         </div>
      </div>

      {/* --- REPORT PAGES --- */}
      <div className="print-container text-slate-900 bg-white md:p-12 print:p-0 rounded-xl shadow-lg print:shadow-none">

        <style>{`
          @media print {
            body { background: white; }
            .print-hidden { display: none !important; }
            .page-break { page-break-after: always; min-height: 100vh; display: flex; flex-direction: column; padding: 15mm; }
            .page-break:last-child { page-break-after: auto; }
            @page { size: A4; margin: 0; }
          }
          .page-break { min-height: 297mm; position: relative; display: flex; flex-direction: column; background: white; margin-bottom: 20px; box-shadow: 0 0 10px rgba(0,0,0,0.05); padding: 15mm; }
          table { width: 100%; border-collapse: collapse; font-size: 11px; }
          th, td { border: 1px solid #cbd5e1; padding: 6px; text-align: left; }
          th { background-color: #f8fafc; font-weight: bold; text-transform: uppercase; }
        `}</style>

        {/* --- PAGE 1: PORTADA Y CARGOS --- */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1">
               <div className="bg-slate-50 p-8 rounded-lg border border-slate-200 mb-8 text-center">
                  <h1 className="text-2xl font-bold text-slate-800 uppercase mb-2">Informe Trimestral de Vigilancia Epidemiológica</h1>
                  <h3 className="text-lg font-medium text-slate-600">{getQuarterRange()}</h3>
                  <div className="mt-6 text-left max-w-md mx-auto text-sm space-y-2 bg-white p-4 rounded border border-slate-100">
                     <p><strong>Entidad de Trabajo:</strong> {selectedCompanyName || 'N/A'}</p>
                     <p><strong>RIF:</strong> {currentCompany?.rif || 'N/A'}</p>
                     <p><strong>Dirección:</strong> {currentCompany?.address || 'N/A'}</p>
                  </div>
               </div>

               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1 mt-4">Distribución de Trabajadores por Cargo</h3>
               <table className="mb-8">
                  <thead>
                     <tr>
                        <th>Cargo / Puesto de Trabajo</th>
                        <th className="text-center w-32">Cantidad</th>
                     </tr>
                  </thead>
                  <tbody>
                     {jobTitleStats.map(([title, count]) => (
                        <tr key={title}>
                           <td className="font-medium">{title}</td>
                           <td className="text-center font-bold">{count}</td>
                        </tr>
                     ))}
                     <tr className="bg-slate-100 font-bold">
                        <td className="uppercase">Total General de Trabajadores</td>
                        <td className="text-center text-sm">{patientsInScope.length}</td>
                     </tr>
                  </tbody>
               </table>
            </div>
            <FooterSignature />
        </div>

        {/* --- PAGE 2: DESGLOSE DEMOGRÁFICO --- */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1 space-y-10">
               <h3 className="text-sm font-bold uppercase mb-4 border-b-2 border-slate-800 pb-1">1. Registro y Análisis de Trabajadores (Discriminación)</h3>

               {demographics && (
                 <>
                   {/* 1.1 SEXO */}
                   <section className="space-y-4">
                      <h4 className="text-xs font-bold uppercase text-blue-800">1.1. Distribución por Sexo</h4>
                      <div className="grid grid-cols-2 gap-8 items-center">
                         <div className="h-48">
                            <ResponsiveContainer width="100%" height="100%">
                               <PieChart>
                                  <Pie data={[
                                     { name: 'Masculino', value: demographics.gender.male },
                                     { name: 'Femenino', value: demographics.gender.female }
                                  ]} cx="50%" cy="50%" innerRadius={40} outerRadius={70} dataKey="value">
                                     <Cell fill={COLORS_GENDER[0]} /><Cell fill={COLORS_GENDER[1]} />
                                  </Pie>
                                  <Legend verticalAlign="bottom" height={36} iconSize={10} wrapperStyle={{fontSize: '11px'}}/>
                                  <RechartsTooltip />
                               </PieChart>
                            </ResponsiveContainer>
                         </div>
                         <table>
                            <thead><tr><th>Género</th><th className="text-center">Cant.</th><th className="text-center">%</th></tr></thead>
                            <tbody>
                               <tr><td>Masculino</td><td className="text-center">{demographics.gender.male}</td><td className="text-center">{((demographics.gender.male/patientsInScope.length)*100).toFixed(1)}%</td></tr>
                               <tr><td>Femenino</td><td className="text-center">{demographics.gender.female}</td><td className="text-center">{((demographics.gender.female/patientsInScope.length)*100).toFixed(1)}%</td></tr>
                               <tr className="font-bold"><td>TOTAL</td><td className="text-center">{patientsInScope.length}</td><td className="text-center">100%</td></tr>
                            </tbody>
                         </table>
                      </div>
                      <p className="text-xs text-slate-600 italic bg-slate-50 p-3 rounded border-l-4 border-blue-500">
                         <strong>Análisis:</strong> La población laboral está compuesta predominantemente por el sexo {demographics.gender.male >= demographics.gender.female ? 'Masculino' : 'Femenino'}, 
                         representando un {Math.max((demographics.gender.male/patientsInScope.length)*100, (demographics.gender.female/patientsInScope.length)*100).toFixed(1)}% del total.
                      </p>
                   </section>

                   {/* 1.2 DISCAPACIDAD */}
                   <section className="space-y-4">
                      <h4 className="text-xs font-bold uppercase text-blue-800">1.2. Población con Discapacidad</h4>
                      <div className="grid grid-cols-2 gap-8 items-center">
                         <table>
                            <thead><tr><th>Condición</th><th className="text-center">Cant.</th><th className="text-center">%</th></tr></thead>
                            <tbody>
                               <tr><td>Con Discapacidad</td><td className="text-center">{demographics.disability.yes}</td><td className="text-center">{((demographics.disability.yes/patientsInScope.length)*100).toFixed(1)}%</td></tr>
                               <tr><td>Sin Discapacidad</td><td className="text-center">{demographics.disability.no}</td><td className="text-center">{((demographics.disability.no/patientsInScope.length)*100).toFixed(1)}%</td></tr>
                            </tbody>
                         </table>
                         <div className="h-48">
                            <ResponsiveContainer width="100%" height="100%">
                               <PieChart>
                                  <Pie data={[
                                     { name: 'Con Discapacidad', value: demographics.disability.yes },
                                     { name: 'Sin Discapacidad', value: demographics.disability.no }
                                  ]} cx="50%" cy="50%" innerRadius={40} outerRadius={70} dataKey="value">
                                     <Cell fill={COLORS_DISABILITY[1]} /><Cell fill={COLORS_DISABILITY[0]} />
                                  </Pie>
                                  <Legend verticalAlign="bottom" height={36} iconSize={10} wrapperStyle={{fontSize: '11px'}}/>
                                  <RechartsTooltip />
                               </PieChart>
                            </ResponsiveContainer>
                         </div>
                      </div>
                      <p className="text-xs text-slate-600 italic bg-slate-50 p-3 rounded border-l-4 border-emerald-500">
                         <strong>Análisis:</strong> Se identifican {demographics.disability.yes} trabajadores con discapacidad certificada o declarada. 
                         {demographics.disability.yes > 0 
                            ? ' Se recomienda el seguimiento continuo de sus condiciones de salud para garantizar la adecuación del puesto de trabajo.' 
                            : ' La empresa cumple actualmente con los estándares generales de salud, sin casos de discapacidad reportados en este grupo.'}
                      </p>
                   </section>

                   {/* 1.3 EDAD */}
                   <section className="space-y-4">
                      <h4 className="text-xs font-bold uppercase text-blue-800">1.3. Distribución por Grupos Etarios</h4>
                      <div className="grid grid-cols-2 gap-8 items-center">
                         <div className="h-48">
                            <ResponsiveContainer width="100%" height="100%">
                               <PieChart>
                                  <Pie data={Object.entries(demographics.age).map(([name, value]) => ({ name, value }))} cx="50%" cy="50%" outerRadius={70} dataKey="value">
                                     {COLORS_AGE.map((c, i) => <Cell key={i} fill={c} />)}
                                  </Pie>
                                  <Legend verticalAlign="bottom" height={36} iconSize={10} wrapperStyle={{fontSize: '10px'}}/>
                                  <RechartsTooltip />
                               </PieChart>
                            </ResponsiveContainer>
                         </div>
                         <table>
                            <thead><tr><th>Rango Edad</th><th className="text-center">Cant.</th><th className="text-center">%</th></tr></thead>
                            <tbody>
                               {Object.entries(demographics.age).map(([range, count]) => (
                                  <tr key={range}><td>{range} años</td><td className="text-center">{count}</td><td className="text-center">{((count/patientsInScope.length)*100).toFixed(1)}%</td></tr>
                               ))}
                            </tbody>
                         </table>
                      </div>
                      <p className="text-xs text-slate-600 italic bg-slate-50 p-3 rounded border-l-4 border-purple-500">
                         <strong>Análisis:</strong> El grupo etario predominante se encuentra en el rango de {Object.entries(demographics.age).reduce((a, b) => b[1] > a[1] ? b : a)[0]} años. 
                         Esta distribución sugiere una fuerza laboral {demographics.age['18-24'] + demographics.age['25-34'] > patientsInScope.length/2 ? 'joven y activa' : 'madura y con experiencia'}, 
                         factor determinante para la planificación de programas preventivos de enfermedades crónicas no transmisibles.
                      </p>
                   </section>
                 </>
               )}
            </div>
            <FooterSignature />
        </div>
      </div>
    </div>
  );
};

