                     </tr>
                  </tbody>
               </table>
            </div>
            <FooterSignature />
        </div>

        {/* PAGE 3: EVALUACIONES Y REFERENCIAS */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1 space-y-8">
               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">4. Resultados de Exámenes de Salud</h3>
               <div className="grid grid-cols-2 gap-6">
                  {Object.entries(examStats).map(([type, stats]) => (
                     stats.Total > 0 && (
                        <div key={type} className="border border-slate-200 p-4 rounded bg-slate-50">
                           <h5 className="font-bold text-xs uppercase text-center mb-2">{type}</h5>
                           <div className="h-40">
                              <ResponsiveContainer width="100%" height="100%">
                                 <PieChart>
                                    <Pie
                                       data={[
                                          { name: 'Apto', value: stats.Apto },
                                          { name: 'No Apto', value: stats['No Apto'] },
                                          { name: 'Postpuesta', value: stats.Postpuesta }
                                       ]}
                                       cx="50%" cy="50%" innerRadius={30} outerRadius={60} dataKey="value"
                                    >
                                       <Cell fill="#22c55e" /><Cell fill="#ef4444" /><Cell fill="#f59e0b" />
