                  <p className="text-sm text-slate-500 italic border border-dashed border-slate-300 p-4 text-center rounded">No se generaron referencias médicas en este período.</p>
               )}

               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">6. Factores de Riesgo y Discapacidad</h3>
               <div className="text-xs text-slate-700 space-y-2 border border-slate-200 p-4 rounded bg-slate-50">
                  <p><strong>Población con Discapacidad:</strong> {patientsInScope.filter(p => p.hasDisability).length} Trabajadores.</p>
                  <p className="mt-2 font-bold uppercase text-[10px] text-slate-500">Factores de Riesgo Identificados:</p>
                  <ul className="list-disc pl-5 space-y-1">
                     <li>Ergonómicos: Posturas forzadas y movimientos repetitivos.</li>
                     <li>Psicosociales: Carga de trabajo y factores de organización.</li>
                  </ul>
               </div>
            </div>
            <FooterSignature />
        </div>

      </div>
    </div>
  );
};

export default SVEReport;

import React, { useState, useEffect, useMemo } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies } from '../utils/storage';
import { MedicalAttention, Patient, Company } from '../types';
import { Printer, ShieldCheck, Building2 } from 'lucide-react';
import { 
  PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, ResponsiveContainer 
} from 'recharts';

// --- Types ---
type Quarter = 'I' | 'II' | 'III' | 'IV';

// --- Constants ---
const REPORT_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

const SVEReport: React.FC = () => {
  // --- State ---
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');

  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  // --- Initial Data Load ---
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // --- Helpers ---
  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2]; // Jan, Feb, Mar
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const getQuarterRange = () => {
    const months = getQuarterMonths(selectedQuarter);
    return `Del 01 de ${getMonthName(months[0])} al ${new Date(selectedYear, months[2] + 1, 0).getDate()} de ${getMonthName(months[2])} de ${selectedYear}`;
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const getAgeGroup = (age: number) => {
    if (age < 25) return '18-24';
    if (age < 35) return '25-34';
    if (age < 45) return '35-44';
    if (age < 55) return '45-54';
    return '55+';
  };

  // --- Filtered Data Logic ---
  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return allPatients;
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);

  const jobTitleStats = useMemo(() => {
    const stats: Record<string, number> = {};
    patientsInScope.forEach(p => {
        const title = p.jobTitle || 'Sin Cargo Definido';
        stats[title] = (stats[title] || 0) + 1;
    });
    return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [patientsInScope]);

  // --- Monthly Statistics for Table ---
  const getMonthlyWorkerStats = (monthIndex: number) => {
    const lastDayOfMonth = new Date(selectedYear, monthIndex + 1, 0);
    const activePatients = patientsInScope.filter(p => new Date(p.entryDate) <= lastDayOfMonth);

    let male = 0, female = 0, disabled = 0;
    const ageGroups: Record<string, number> = { '18-24': 0, '25-34': 0, '35-44': 0, '45-54': 0, '55+': 0 };

    activePatients.forEach(p => {
        if (p.gender === 'Masculino') male++; else female++;
        if (p.hasDisability) disabled++;
        const group = getAgeGroup(calculateAge(p.birthDate));
        ageGroups[group]++;
    });

    return { total: activePatients.length, male, female, disabled, ageGroups };
  };

  const quarterAttentions = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    return attentionsInScope.filter(att => {
      const d = new Date(att.attentionDate);
      return d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
  }, [attentionsInScope, selectedYear, selectedQuarter]);

  const examStats = useMemo(() => {
    const data = {
      'Pre Empleo': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Pre Vacaciones': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Egreso': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
      'Periódica': { Apto: 0, 'No Apto': 0, Postpuesta: 0, Total: 0 },
    };
    quarterAttentions.forEach(att => {
       if (data[att.attentionType as keyof typeof data] && att.evaluationResult !== 'No Aplica') {
           data[att.attentionType as keyof typeof data].Total++;
           if (['Apto', 'No Apto', 'Postpuesta'].includes(att.evaluationResult)) {
               // @ts-ignore
               data[att.attentionType as keyof typeof data][att.evaluationResult]++;
           }
       }
    });
    return data;
  }, [quarterAttentions]);

  const morbidity = useMemo(() => {
     return {
        'Enfermedad Común': quarterAttentions.filter(a => a.reason === 'Enfermedad Común'),
        'Enfermedad Ocupacional': quarterAttentions.filter(a => a.reason === 'Enfermedad Ocupacional'),
        'Accidente Común': quarterAttentions.filter(a => a.reason === 'Accidente Común'),
        'Accidente Ocupacional': quarterAttentions.filter(a => a.reason === 'Accidente Ocupacional'),
     };
  }, [quarterAttentions]);

  const restStats = useMemo(() => {
     const stats = {
        'Enfermedad Común': { count: 0, days: 0 },
        'Enfermedad Ocupacional': { count: 0, days: 0 },
        'Accidente Común': { count: 0, days: 0 },
        'Accidente Ocupacional': { count: 0, days: 0 },
     };
     quarterAttentions.forEach(a => {
        if (a.reason && a.restDays > 0) {
            stats[a.reason as keyof typeof stats].count++;
            stats[a.reason as keyof typeof stats].days += a.restDays;
        }
     });
     return stats;
  }, [quarterAttentions]);

  const referrals = useMemo(() => {
      return quarterAttentions.filter(a => a.medicalReferral && a.medicalReferral.trim() !== '');
  }, [quarterAttentions]);

  // --- Render Sections ---

  const HeaderSection = () => (
    <div className="flex justify-between items-center mb-8 border-b-2 border-slate-800 pb-4">
       <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-200 rounded flex items-center justify-center text-xs text-slate-500 font-bold border border-slate-300">LOGO</div>
          <div>
             <h1 className="text-xl font-bold text-slate-900 uppercase">
                 {currentCompany ? currentCompany.name : 'ALEX CONSULTING'}
             </h1>
             <p className="text-sm font-semibold text-slate-700">
                 {currentCompany ? `RIF: ${currentCompany.rif}` : 'RIF: J-12345678-9'}
             </p>
             <p className="text-sm text-slate-600">Servicio de Seguridad y Salud en el Trabajo</p>
          </div>
       </div>
       <div className="text-right">
          <h2 className="text-lg font-bold text-slate-800 uppercase">Informe Trimestral SVE</h2>
          <p className="text-sm font-medium text-slate-700">Trimestre: {selectedQuarter} - {selectedYear}</p>
          <p className="text-xs text-slate-500 mt-1">{new Date().toLocaleDateString()}</p>
       </div>
    </div>
  );

  const FooterSignature = ({ isLastPage = false }: { isLastPage?: boolean }) => (
     <div className="mt-auto pt-8">
        <div className="flex justify-center">
           <div className="text-center w-64">
              <div className="border-t border-slate-800 pt-2 mb-1"></div>
              <p className="font-bold text-xs uppercase">Dr. Alex Marcano</p>
              <p className="text-[10px] text-slate-600 font-medium">Médico Ocupacional</p>
              <p className="text-[10px] text-slate-500">CM: 12345 | MPPS: 67890</p>
           </div>
        </div>
     </div>
  );

  if (loading) return <div className="p-8 text-center text-slate-500">Generando reporte...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">

      {/* Controls */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 print:hidden flex flex-col gap-6">
         <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
            <ShieldCheck className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-bold text-slate-800">Generador de Informe SVE</h2>
         </div>
         <div className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Empresa</label>
               <select 
                 value={selectedCompanyName}
                 onChange={(e) => setSelectedCompanyName(e.target.value)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
               >
                   <option value="">-- Seleccionar Empresa --</option>
                   {companies.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
               </select>
            </div>
            <button onClick={() => window.print()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm">
              <Printer className="w-4 h-4" /> Imprimir
            </button>
         </div>
      </div>

      {/* Report Container */}
      <div className="print-container text-slate-900 bg-white md:p-12 print:p-0 rounded-xl shadow-lg print:shadow-none">

        <style>{`
          @media print {
            body { background: white; }
            .page-break { page-break-after: always; min-height: 100vh; display: flex; flex-direction: column; padding: 15mm; }
            .page-break:last-child { page-break-after: auto; }
            @page { size: A4; margin: 0; }
          }
          .page-break { min-height: 297mm; position: relative; display: flex; flex-direction: column; background: white; margin-bottom: 20px; box-shadow: 0 0 10px rgba(0,0,0,0.05); padding: 15mm; }
          table { width: 100%; border-collapse: collapse; font-size: 11px; }
          th, td { border: 1px solid #cbd5e1; padding: 6px; text-align: left; }
          th { background-color: #f8fafc; font-weight: bold; text-transform: uppercase; }
        `}</style>

        {/* PAGE 1: PORTADA Y REGISTRO MENSUAL */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1">
               <div className="bg-slate-50 p-8 rounded-lg border border-slate-200 mb-8 text-center">
                  <h1 className="text-2xl font-bold text-slate-800 uppercase mb-2">Informe Trimestral de Vigilancia Epidemiológica</h1>
                  <h3 className="text-lg font-medium text-slate-600">{getQuarterRange()}</h3>
                  <div className="mt-6 text-left max-w-md mx-auto text-sm space-y-2 bg-white p-4 rounded border border-slate-100">
                     <p><strong>Entidad de Trabajo:</strong> {selectedCompanyName || 'N/A'}</p>
                     <p><strong>RIF:</strong> {currentCompany?.rif || 'N/A'}</p>
                     <p><strong>Dirección:</strong> {currentCompany?.address || 'N/A'}</p>
                  </div>
               </div>

               {/* TABLA DE CARGOS */}
               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1 mt-4">Distribución de Trabajadores por Cargo</h3>
               <table className="mb-8">
                  <thead>
                     <tr>
                        <th>Cargo / Puesto de Trabajo</th>
                        <th className="text-center w-32">Cantidad</th>
                     </tr>
                  </thead>
                  <tbody>
                     {jobTitleStats.map(([title, count]) => (
                        <tr key={title}>
