                              <td className="text-center">{stats.ageGroups['35-44']}</td>
                              <td className="text-center">{stats.ageGroups['45-54']}</td>
                              <td className="text-center">{stats.ageGroups['55+']}</td>
                           </tr>
                        );
                     })}
                  </tbody>
               </table>
            </div>
            <FooterSignature />
        </div>

        {/* PAGE 2: MORBILIDAD Y REPOSOS */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1 space-y-8">
               <h3 className="text-sm font-bold uppercase mb-4 border-b border-slate-300 pb-1">2. Registro de Accidentes y Enfermedades</h3>
               <div className="grid grid-cols-1 gap-6">
                  {/* Fixed TypeScript error by adding explicit type casting to Object.entries for morbidity */}
                  {(Object.entries(morbidity) as [string, MedicalAttention[]][]).map(([type, list]) => (
