    // Initialize DB with default user if empty (for User Management module)
    initializeAuth();
  }, []);

  // Load Dashboard Data whenever we switch to it
  useEffect(() => {
    if (currentView === 'dashboard') {
        const loadDashboardData = async () => {
            try {
                const allAppointments = await getAppointments();
                // Get local date string YYYY-MM-DD
                const today = new Date();

                // Better local date handling
                const offset = today.getTimezoneOffset();
                const localDate = new Date(today.getTime() - (offset*60*1000));
                const localDateStr = localDate.toISOString().split('T')[0];

                const filtered = allAppointments
                    .filter(a => a.date === localDateStr && a.status !== 'Cancelada')
                    .sort((a, b) => a.time.localeCompare(b.time));

                setTodayAppointments(filtered);
            } catch (error) {
                console.error("Error loading dashboard data", error);
            }
        };
        loadDashboardData();
    }
  }, [currentView]);

