                                                    title="Ir a Atención"
                                                 >
                                                     <CheckCircle2 className="w-5 h-5" />
                                                 </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

            </div>
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex">
      {/* Sidebar Component */}
      <Sidebar 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)}
        onNavigate={(view) => {
            setCurrentView(view);
        }}
      />

      {/* Main Content Area */}
