            </button>
            <span className="font-semibold text-slate-800">Alex Consulting</span>
          </div>
        </header>

        {/* Content Placeholder */}
        <main className="p-6 md:p-8 overflow-y-auto min-h-[calc(100vh-64px)] lg:min-h-screen">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

