import React, { useState, useEffect } from 'react';
import { Search, Printer, FileBarChart, AlertCircle, ChevronRight, Briefcase, FileCheck, Clock, UserCheck, Stethoscope, ClipboardList, Building } from 'lucide-react';
import { findPatientByCedula, getMedicalAttentionsByCedula, getDoctors } from '../utils/storage';
import { Patient, MedicalAttention, Doctor } from '../types';

interface MedicalReportGeneratorProps {
  type: 'medical' | 'occupational' | 'sick-leave' | 'external-sick-leave';
}

const MedicalReportGenerator: React.FC<MedicalReportGeneratorProps> = ({ type }) => {
  // --- State ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState('');

  const [patient, setPatient] = useState<Patient | null>(null);
  const [attentions, setAttentions] = useState<MedicalAttention[]>([]);
  const [selectedAttention, setSelectedAttention] = useState<MedicalAttention | null>(null);

  // Doctor Selection State
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<string>('');

  // External Leave Manual Data
  const [externalData, setExternalData] = useState({
      doctorName: '',
      institution: '',
      diagnosis: '',
      days: 0,
      startDate: new Date().toISOString().split('T')[0]
  });

  // Ergonomics Manual Data State
  const [ergonomics, setErgonomics] = useState({
      postures: 'Postura sedente prolongada (administrativo) o bipedestación prolongada (operativo).',
      repetitive: 'Movimientos repetitivos en miembros superiores (uso de teclado/mouse o herramientas).',
      force: 'No aplica / Levantamiento ocasional de cargas menores a 5kg.',
      environment: 'Iluminación y temperatura confortables. Ruido ambiente bajo.',
      protection: 'Uniforme habitual. No requiere EPP específicos.'
  });

  // Load Doctors on Mount
  useEffect(() => {
    const fetchDoctors = async () => {
        const docs = await getDoctors();
        setDoctors(docs);
        if (docs.length > 0) {
            setSelectedDoctorId(docs[0].id);
        }
    };
    fetchDoctors();
  }, []);

  // Clear selection when type changes
  useEffect(() => {
    setSelectedAttention(null);
    setPatient(null);
    setAttentions([]);
    setSearchCedula('');
    setErgonomics({
        postures: 'Postura sedente prolongada (administrativo) o bipedestación prolongada (operativo).',
        repetitive: 'Movimientos repetitivos en miembros superiores (uso de teclado/mouse o herramientas).',
        force: 'No aplica / Levantamiento ocasional de cargas menores a 5kg.',
        environment: 'Iluminación y temperatura confortables. Ruido ambiente bajo.',
        protection: 'Uniforme habitual. No requiere EPP específicos.'
    });
    setExternalData({
        doctorName: '',
        institution: '',
        diagnosis: '',
        days: 0,
        startDate: new Date().toISOString().split('T')[0]
    });
  }, [type]);

  useEffect(() => {
    if (selectedAttention && selectedAttention.doctorId) {
        const match = doctors.find(d => d.id === selectedAttention.doctorId);
        if (match) {
            setSelectedDoctorId(match.id);
        }
    }
  }, [selectedAttention, doctors]);

  // --- Logic ---
  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setError('');
    setPatient(null);
    setAttentions([]);
    setSelectedAttention(null);

    try {
      const foundPatient = await findPatientByCedula(searchCedula);
      if (!foundPatient) {
        setError('Paciente no encontrado.');
        setIsSearching(false);
        return;
      }

      const foundAttentions = await getMedicalAttentionsByCedula(searchCedula);

      const filteredAttentions = type === 'sick-leave' 
        ? foundAttentions.filter(a => a.restDays > 0)
        : foundAttentions;

      setPatient(foundPatient);
      setAttentions(filteredAttentions);

      if (filteredAttentions.length === 0 && type === 'sick-leave') {
          setError('El paciente no tiene registros con días de reposo.');
      }

      // In External mode, we might just want to fill the form even if there are no attentions
      if (type === 'external-sick-leave' && filteredAttentions.length === 0) {
          // No error, we just create a dummy attention or allow manual entry
          setSelectedAttention({ id: 'external', patientId: foundPatient.id, patientName: foundPatient.firstName, patientCedula: foundPatient.cedula, attentionDate: new Date().toISOString().split('T')[0], attentionType: 'General', diagnosis: '', restDays: 0, restStartDate: '', restEndDate: '', evaluationResult: 'No Aplica', createdAt: '' } as MedicalAttention);
      } else if (type === 'external-sick-leave' && filteredAttentions.length > 0) {
           setSelectedAttention(null); // Show list to select or "create new"
      }

    } catch (err) {
      setError('Error al recuperar datos.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleExternalChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setExternalData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleErgoChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setErgonomics(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const getTitle = () => {
    switch(type) {
        case 'medical': return 'Informe Médico General';
        case 'occupational': return 'Informe Ocupacional (Aptitud)';
        case 'sick-leave': return 'Constancia de Reposo Médico';
        case 'external-sick-leave': return 'Validación de Reposo Externo';
        default: return 'Reporte';
    }
  };

  const getIcon = () => {
      switch(type) {
          case 'medical': return <FileBarChart className="w-6 h-6 text-blue-600" />;
          case 'occupational': return <Briefcase className="w-6 h-6 text-indigo-600" />;
          case 'sick-leave': return <Clock className="w-6 h-6 text-orange-600" />;
