                      <p className="font-bold text-lg border-b border-slate-300 pb-1">{formatDate(selectedAttention?.restEndDate || '')}</p>
                  </div>
              </div>
              <p className="text-justify text-xs text-slate-500 mt-8">
                  Nota: Esta constancia debe ser validada por el Instituto Venezolano de los Seguros Sociales (IVSS) si el reposo excede los 3 días, conforme a la normativa legal vigente.
              </p>
          </div>
          {renderSignature()}
      </div>
  );

  // 4. EXTERNAL LEAVE CONTENT
  const renderExternalLeaveContent = () => (
      <div className="flex-1 flex flex-col">
          {renderHeader()}
          <div className="flex-1 space-y-6 text-sm text-slate-900 leading-relaxed">
              <div className="text-center mb-8">
                  <h2 className="text-xl font-bold uppercase underline">Validación de Reposo Externo</h2>
              </div>

              <div className="p-4 border border-slate-200 rounded bg-slate-50">
                  <h3 className="font-bold text-xs uppercase mb-2 text-slate-500">Datos del Empleado</h3>
                  <p><span className="font-bold">Nombre:</span> {patient?.firstName}</p>
                  <p><span className="font-bold">Cédula:</span> {patient?.cedula}</p>
                  <p><span className="font-bold">Cargo:</span> {patient?.jobTitle}</p>
              </div>

              <div className="space-y-4 pt-4">
                  <p className="text-justify">
                      Se ha recibido y validado por parte del Servicio de Seguridad y Salud en el Trabajo, el reposo médico emitido por:
                  </p>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-50 p-4 border border-slate-300 rounded">
                      <div>
                          <p className="text-[10px] font-bold text-slate-500 uppercase">Médico Tratante Externo</p>
                          <p className="font-bold text-base">{externalData.doctorName || '__________'}</p>
                      </div>
                      <div>
                          <p className="text-[10px] font-bold text-slate-500 uppercase">Institución / Centro de Salud</p>
