                      </div>
                  </div>

                  <div>
                      <p className="text-[10px] font-bold text-slate-500 uppercase mb-1">Diagnóstico Reportado</p>
                      <div className="p-3 border border-slate-200 rounded italic bg-white whitespace-pre-wrap">
                          {externalData.diagnosis || 'Sin diagnóstico especificado en el registro.'}
