      {/* EXTERNAL SICK LEAVE DATA ENTRY */}
      {selectedAttention && type === 'external-sick-leave' && (
          <div className="bg-red-50 border border-red-200 rounded-xl p-6 mb-8 print:hidden">
              <h3 className="font-bold text-red-900 mb-4 flex items-center gap-2">
                  <ClipboardList className="w-5 h-5" />
                  Datos del Reposo Externo
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                      <label className="block text-xs font-bold text-red-800 uppercase mb-1">Médico Externo</label>
                      <input 
                        type="text" 
                        name="doctorName"
