                        value={externalData.institution}
                        onChange={handleExternalChange}
                        className="w-full px-3 py-2 border border-red-300 rounded focus:ring-2 focus:ring-red-500 outline-none text-sm"
                        placeholder="Ej. IVSS, Clínica Méndez..."
                      />
                  </div>
                  <div className="col-span-1 md:col-span-2">
                      <label className="block text-xs font-bold text-red-800 uppercase mb-1">Diagnóstico</label>
                      <textarea 
                        name="diagnosis"
                        value={externalData.diagnosis}
                        onChange={handleExternalChange}
                        rows={2}
                        className="w-full px-3 py-2 border border-red-300 rounded focus:ring-2 focus:ring-red-500 outline-none text-sm resize-none"
                      />
                  </div>
                   <div>
                      <label className="block text-xs font-bold text-red-800 uppercase mb-1">Días de Reposo</label>
                      <input 
                        type="number" 
                        name="days"
                        value={externalData.days}
                        onChange={handleExternalChange}
                        className="w-full px-3 py-2 border border-red-300 rounded focus:ring-2 focus:ring-red-500 outline-none text-sm"
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-red-800 uppercase mb-1">Fecha de Inicio</label>
                      <input 
                        type="date" 
                        name="startDate"
                        value={externalData.startDate}
                        onChange={handleExternalChange}
                        className="w-full px-3 py-2 border border-red-300 rounded focus:ring-2 focus:ring-red-500 outline-none text-sm"
                      />
                  </div>
              </div>
          </div>
      )}

      {/* ERGONOMICS ENTRY */}
      {selectedAttention && type === 'occupational' && (
          <div className="bg-indigo-50 border border-indigo-200 rounded-xl p-6 mb-8 print:hidden">
              <h3 className="font-bold text-indigo-900 mb-4 flex items-center gap-2">
                  <ClipboardList className="w-5 h-5" />
                  Datos de Ergonomía (Manuales)
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="col-span-1 md:col-span-2">
                      <label className="block text-xs font-bold text-indigo-800 uppercase mb-1">Posturas</label>
                      <input 
                        type="text" 
                        name="postures"
                        value={ergonomics.postures}
                        onChange={handleErgoChange}
                        className="w-full px-3 py-2 border border-indigo-300 rounded focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                        placeholder="Ej. Sedente prolongada, Bipedestación..."
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-indigo-800 uppercase mb-1">Repetitividad</label>
                      <textarea 
                        rows={2}
                        name="repetitive"
                        value={ergonomics.repetitive}
                        onChange={handleErgoChange}
                        className="w-full px-3 py-2 border border-indigo-300 rounded focus:ring-2 focus:ring-indigo-500 outline-none text-sm resize-none"
                      />
                  </div>
                   <div>
                      <label className="block text-xs font-bold text-indigo-800 uppercase mb-1">Manipulación de Cargas</label>
                      <textarea 
                        rows={2}
                        name="force"
                        value={ergonomics.force}
                        onChange={handleErgoChange}
                        className="w-full px-3 py-2 border border-indigo-300 rounded focus:ring-2 focus:ring-indigo-500 outline-none text-sm resize-none"
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-indigo-800 uppercase mb-1">Condiciones Ambientales</label>
                      <input 
                        type="text" 
                        name="environment"
                        value={ergonomics.environment}
                        onChange={handleErgoChange}
                        className="w-full px-3 py-2 border border-indigo-300 rounded focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-indigo-800 uppercase mb-1">Equipos de Protección (EPP)</label>
                      <input 
                        type="text" 
                        name="protection"
                        value={ergonomics.protection}
                        onChange={handleErgoChange}
                        className="w-full px-3 py-2 border border-indigo-300 rounded focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                      />
                  </div>
              </div>
          </div>
      )}

      {/* PREVIEW & PRINT AREA */}
      {selectedAttention && patient && (
          <div className="animate-in fade-in zoom-in-95 duration-300">
              <div className="flex justify-between items-center mb-6 print:hidden">
                  <button 
                      onClick={() => setSelectedAttention(null)}
                      className="text-sm text-slate-500 hover:text-slate-800 font-medium underline"
                  >
                      ← Seleccionar otro registro
                  </button>
                  <button 
                      onClick={() => window.print()}
                      className="px-6 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 font-medium shadow-lg flex items-center gap-2"
                  >
                      <Printer className="w-4 h-4" /> Imprimir Documento
                  </button>
              </div>

              <div className="bg-white shadow-xl border border-slate-200 rounded-none md:rounded-sm w-full max-w-[216mm] mx-auto min-h-[279mm] p-[20mm] print:shadow-none print:border-0 print:w-full print:max-w-none print:p-0 flex flex-col">
                  {type === 'medical' && renderMedicalContent()}
                  {type === 'occupational' && renderOccupationalContent()}
                  {type === 'sick-leave' && renderSickLeaveContent()}
                  {type === 'external-sick-leave' && renderExternalLeaveContent()}

                  <div className="mt-8 pt-4 border-t border-slate-200 text-[10px] text-center text-slate-400">
                      Generado electrónicamente por sistema Alex Consulting el {new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default MedicalReportGenerator;

import React, { useState, useEffect } from 'react';
import { Search, Printer, FileBarChart, AlertCircle, ChevronRight, Briefcase, Clock, Stethoscope, ClipboardList, Save, CheckCircle2 } from 'lucide-react';
import { findPatientByCedula, getMedicalAttentionsByCedula, getDoctors, saveMedicalAttentionToDB } from '../utils/storage';
import { Patient, MedicalAttention, Doctor } from '../types';

interface MedicalReportGeneratorProps {
  type: 'medical' | 'occupational' | 'sick-leave' | 'external-sick-leave';
}

const MedicalReportGenerator: React.FC<MedicalReportGeneratorProps> = ({ type }) => {
  // --- State ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [patient, setPatient] = useState<Patient | null>(null);
  const [attentions, setAttentions] = useState<MedicalAttention[]>([]);
  const [selectedAttention, setSelectedAttention] = useState<MedicalAttention | null>(null);

  // Doctor Selection State
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<string>('');

  // Sick Leave Manual Data (Internal)
  const [sickLeaveData, setSickLeaveData] = useState({
      diagnosis: '',
      days: 1,
      startDate: new Date().toISOString().split('T')[0],
      endDate: ''
  });

  // External Leave Manual Data
  const [externalData, setExternalData] = useState({
      doctorName: '',
      institution: '',
      diagnosis: '',
      days: 1,
      startDate: new Date().toISOString().split('T')[0]
  });

  // Ergonomics Manual Data
  const [ergonomics, setErgonomics] = useState({
      postures: 'Postura sedente prolongada.',
      repetitive: 'Movimientos repetitivos en miembros superiores.',
      force: 'Levantamiento ocasional de cargas.',
      environment: 'Condiciones ambientales controladas.',
      protection: 'Uniforme de seguridad estándar.'
  });

  // Load Doctors on Mount
  useEffect(() => {
    const fetchDoctors = async () => {
        const docs = await getDoctors();
        setDoctors(docs);
        if (docs.length > 0) setSelectedDoctorId(docs[0].id);
    };
    fetchDoctors();
  }, []);

  // Calculate End Date automatically for Sick Leave
  useEffect(() => {
    const calculateEndDate = (start: string, days: number) => {
        if (!start || days < 1) return '';
        const date = new Date(start);
        date.setDate(date.getDate() + (Number(days) - 1));
        return date.toISOString().split('T')[0];
    };

    if (type === 'sick-leave') {
        setSickLeaveData(prev => ({ ...prev, endDate: calculateEndDate(prev.startDate, prev.days) }));
    } else if (type === 'external-sick-leave') {
        // For external just keep simple or calculate too
    }
  }, [sickLeaveData.startDate, sickLeaveData.days, type]);

  // Reset when type changes
  useEffect(() => {
    setSelectedAttention(null);
    setPatient(null);
    setAttentions([]);
    setSearchCedula('');
    setError('');
    setSuccess('');
    setSickLeaveData({
        diagnosis: '',
        days: 1,
        startDate: new Date().toISOString().split('T')[0],
        endDate: ''
    });
  }, [type]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setError('');
    setSuccess('');
    setPatient(null);
    setAttentions([]);
    setSelectedAttention(null);

    try {
      const foundPatient = await findPatientByCedula(searchCedula);
      if (!foundPatient) {
        setError('Trabajador no encontrado.');
        setIsSearching(false);
        return;
      }

      const foundAttentions = await getMedicalAttentionsByCedula(searchCedula);
      setPatient(foundPatient);
      setAttentions(foundAttentions);

      if (type === 'sick-leave' && foundAttentions.length === 0) {
          // If no previous attentions, we just let them fill the manual form
      }
    } catch (err) {
      setError('Error al recuperar datos.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleSaveSickLeave = async () => {
    if (!patient || !selectedDoctorId || !sickLeaveData.diagnosis) {
        setError('Por favor complete el diagnóstico y seleccione un médico.');
        return;
    }

    const doc = doctors.find(d => d.id === selectedDoctorId);

    const newAttention: Omit<MedicalAttention, 'id' | 'createdAt'> = {
        patientId: patient.id,
        patientName: patient.firstName,
        patientCedula: patient.cedula,
        attentionDate: sickLeaveData.startDate,
        attentionType: 'General',
        diagnosis: sickLeaveData.diagnosis,
        restDays: sickLeaveData.days,
        restStartDate: sickLeaveData.startDate,
        restEndDate: sickLeaveData.endDate,
        evaluationResult: 'No Aplica',
        doctorId: selectedDoctorId,
        doctorName: doc ? `${doc.title} ${doc.firstName}` : ''
    };

    try {
        const saved = await saveMedicalAttentionToDB(newAttention);
        setSelectedAttention(saved);
        setSuccess('Reposo registrado y guardado exitosamente.');
        setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
        setError('Error al guardar el registro.');
    }
  };

  const getTitle = () => {
    switch(type) {
        case 'medical': return 'Informe Médico General';
        case 'occupational': return 'Informe Ocupacional';
        case 'sick-leave': return 'Reposo Médico (Interno)';
        case 'external-sick-leave': return 'Validación Reposo Externo';
        default: return 'Reporte';
    }
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const formatDate = (dateStr: string) => {
      if (!dateStr) return '-';
      return new Date(dateStr).toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  const renderHeader = () => (
    <header className="border-b-2 border-slate-800 pb-4 mb-8 flex justify-between items-start">
        <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-blue-900 rounded-lg flex items-center justify-center text-white font-bold">AC</div>
            <div>
                <h1 className="text-xl font-bold text-slate-900 uppercase tracking-wider leading-tight">Alex Consulting</h1>
                <p className="text-sm font-semibold text-slate-600 uppercase tracking-widest">Servicios Médicos Ocupacionales</p>
                <p className="text-[10px] text-slate-500">RIF: J-12345678-9 | Sede Administrativa</p>
            </div>
        </div>
        <div className="text-right">
            <h2 className="text-lg font-bold text-slate-800 uppercase">{getTitle()}</h2>
            <p className="text-xs text-slate-500 mt-1">Fecha: {new Date().toLocaleDateString()}</p>
        </div>
    </header>
  );

  const renderSignature = () => {
    const signingDoctor = doctors.find(d => d.id === selectedDoctorId);
    return (
        <div className="mt-auto pt-16 flex justify-center print:break-inside-avoid">
            <div className="w-64 text-center">
                <div className="border-t border-slate-900 pt-2">
                    {signingDoctor ? (
                        <>
                            <p className="font-bold text-sm uppercase">{signingDoctor.title} {signingDoctor.firstName}</p>
                            <p className="text-xs text-slate-600">Médico Ocupacional</p>
                            <p className="text-[10px] text-slate-500 mt-0.5">MPPS: {signingDoctor.mpps} | CM: {signingDoctor.collegeId}</p>
                        </>
                    ) : <p className="text-xs text-red-500 italic">Sin firma configurada</p>}
                </div>
            </div>
        </div>
    );
  };

  return (
    <div className="max-w-6xl mx-auto pb-12">
      <div className="flex justify-between items-center mb-6 print:hidden">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            {type === 'sick-leave' ? <Clock className="w-6 h-6 text-orange-600" /> : <FileBarChart className="w-6 h-6 text-blue-600" />}
            {getTitle()}
        </h2>
        {success && <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce"><CheckCircle2 className="w-4 h-4"/> {success}</div>}
      </div>

      {/* --- SEARCH SECTION --- */}
      <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-8 print:hidden">
        <form onSubmit={handleSearch} className="flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <label className="block text-sm font-bold text-slate-600 mb-1 uppercase tracking-tight">Buscar Trabajador (Cédula)</label>
            <div className="relative">
              <input 
                type="number" 
                value={searchCedula}
                onChange={(e) => setSearchCedula(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-lg font-mono"
                placeholder="Ej. 12345678"
              />
              <Search className="w-5 h-5 text-slate-400 absolute left-3 top-3.5" />
            </div>
          </div>
          <button 
            type="submit"
            disabled={isSearching}
            className="w-full md:w-auto px-8 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:bg-blue-300 transition-all font-bold shadow-lg"
          >
