              <div className="w-full md:w-64">
                <label className="block text-[10px] font-bold text-blue-400 uppercase mb-1">Médico que certifica:</label>
                <select 
                    value={selectedDoctorId}
                    onChange={(e) => setSelectedDoctorId(e.target.value)}
                    className="w-full px-3 py-2 border border-blue-200 rounded-lg text-sm bg-white"
                >
                    {doctors.map(doc => <option key={doc.id} value={doc.id}>{doc.title} {doc.firstName}</option>)}
                </select>
              </div>
          </div>
      )}

      {/* --- SICK LEAVE ENTRY FORM (INTERNAL) --- */}
      {patient && type === 'sick-leave' && !selectedAttention && (
          <div className="bg-white rounded-xl shadow-md border border-slate-200 p-8 mb-8 print:hidden animate-in fade-in zoom-in-95">
              <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2 border-b pb-4">
                  <ClipboardList className="w-5 h-5 text-blue-600" />
