               <div className="section-title">11.- Estadísticas de Accidentalidad y Morbilidad</div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 border rounded bg-slate-50 text-[9px]">
                     <p className="font-bold border-b mb-1 uppercase text-slate-500">Frecuencia Bruta (IFB)</p>
                     <p className="text-blue-600 font-black text-lg">
                       {((structuredMorbidity['Accidentes de Trabajo'].length / (patientsInScope.length || 1)) * 100).toFixed(2)}
