import React, { useState, useEffect, useMemo, useRef } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies, getDoctors } from '../utils/storage';
import { MedicalAttention, Patient, Company, Doctor } from '../types';
import { Printer, ShieldCheck, Building2, Table as TableIcon, BarChart3, FileText, FileDown } from 'lucide-react';

type Quarter = 'I' | 'II' | 'III' | 'IV';

const SVEReport: React.FC = () => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');
  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps, docs] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies(),
            getDoctors()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
        setDoctors(docs);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2];
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return allPatients;
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);

  const quarterAttentions = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    return attentionsInScope.filter(att => {
      const d = new Date(att.attentionDate);
      return d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
  }, [attentionsInScope, selectedYear, selectedQuarter]);

  // Statistics for Section (Monthly and Annual Occurrence)
  const annualOccurrenceStats = useMemo(() => {
    const stats: Record<number, { ac: number, at: number, ec: number, eo: number }> = {};

    // Initialize all 12 months
    for (let i = 0; i < 12; i++) {
        stats[i] = { ac: 0, at: 0, ec: 0, eo: 0 };
    }

    // Process only attentions for the selected year
    attentionsInScope.forEach(att => {
        const d = new Date(att.attentionDate);
        if (d.getFullYear() === selectedYear) {
            const month = d.getMonth();
            if (att.reason === 'Accidente Común') stats[month].ac++;
            else if (att.reason === 'Accidente Ocupacional') stats[month].at++;
            else if (att.reason === 'Enfermedad Común') stats[month].ec++;
            else if (att.reason === 'Enfermedad Ocupacional') stats[month].eo++;
        }
    });

    return stats;
  }, [attentionsInScope, selectedYear]);

  const examStats = useMemo(() => {
    const data = {
      'Ingreso (Pre-empleo)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Prevacacional': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Postvacacional (Periódica)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Egreso': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Especiales / Otros': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
    };

    quarterAttentions.forEach(att => {
       let key: keyof typeof data | null = null;
       if (att.attentionType === 'Pre Empleo') key = 'Ingreso (Pre-empleo)';
       else if (att.attentionType === 'Pre Vacaciones') key = 'Prevacacional';
       else if (att.attentionType === 'Egreso') key = 'Egreso';
       else if (att.attentionType === 'Periódica') key = 'Postvacacional (Periódica)';
       else if (att.attentionType === 'General') key = 'Especiales / Otros';

       if (key && data[key]) {
           data[key].Total++;
           const result = att.evaluationResult;
           if (result === 'Apto') data[key].Apto++;
           else if (result === 'No Apto') data[key]['No Apto']++;
           else if (result === 'Postpuesta') data[key].Postpuesta++;
           else data[key]['No Aplica']++;
       }
    });
    return data;
  }, [quarterAttentions]);

  const structuredMorbidity = useMemo(() => {
     return {
        'Accidentes Comunes': quarterAttentions.filter(a => a.reason === 'Accidente Común'),
        'Accidentes de Trabajo': quarterAttentions.filter(a => a.reason === 'Accidente Ocupacional'),
        'Enfermedades Comunes': quarterAttentions.filter(a => a.reason === 'Enfermedad Común'),
        'Enfermedades Ocupacionales': quarterAttentions.filter(a => a.reason === 'Enfermedad Ocupacional'),
     };
  }, [quarterAttentions]);

  const restStats = useMemo(() => {
     const stats = {
        'Accidentes Comunes': { count: 0, days: 0 },
        'Accidentes de Trabajo': { count: 0, days: 0 },
        'Enfermedades Comunes': { count: 0, days: 0 },
        'Enfermedades Ocupacionales': { count: 0, days: 0 },
     };
     quarterAttentions.forEach(a => {
        let key = '';
        if (a.reason === 'Accidente Común') key = 'Accidentes Comunes';
        else if (a.reason === 'Accidente Ocupacional') key = 'Accidentes de Trabajo';
        else if (a.reason === 'Enfermedad Común') key = 'Enfermedad Común';
        else if (a.reason === 'Enfermedad Ocupacional') key = 'Enfermedad Ocupacional';

        if (key && a.restDays > 0) {
            stats[key as keyof typeof stats].count++;
            stats[key as keyof typeof stats].days += a.restDays;
        }
     });
     return stats;
  }, [quarterAttentions]);

  const handleExportWord = () => {
    if (!reportRef.current) return;

    const content = reportRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
            "xmlns:w='urn:schemas-microsoft-com:office:word' " +
            "xmlns='http://www.w3.org/TR/REC-html40'>" +
            "<head><meta charset='utf-8'><title>Informe SVE</title>" +
            "<style>" +
            "body { font-family: 'Arial', sans-serif; font-size: 10pt; }" +
            "table { border-collapse: collapse; width: 100%; margin-bottom: 10px; }" +
            "th, td { border: 1px solid #000; padding: 5px; text-align: left; }" +
            "th { background-color: #f3f4f6; font-weight: bold; }" +
            ".section-title { font-weight: bold; text-transform: uppercase; border-bottom: 2px solid #000; margin-top: 20px; margin-bottom: 10px; }" +
            ".page-break { page-break-after: always; }" +
            "</style></head><body>";
    const footer = "</body></html>";
    const sourceHTML = header + content + footer;

    const blob = new Blob(['\ufeff', sourceHTML], {
        type: 'application/msword'
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `SVE_${selectedCompanyName || 'Reporte'}_T${selectedQuarter}_${selectedYear}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const HeaderSection = () => (
