    const [isProcessing, setIsProcessing] = useState(false);
    const [status, setStatus] = useState<{ type: 'success' | 'error' | 'info', text: string } | null>(null);
    const [stats, setStats] = useState<{ created: number, updated: number } | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const [companies, setCompanies] = useState<string[]>([]);
    const [jobs, setJobs] = useState<string[]>([]);

    useEffect(() => {
        const loadRefs = async () => {
            const [c, j] = await Promise.all([getCompanies(), getJobTitles()]);
            setCompanies(c.map(item => item.name));
            setJobs(j.map(item => item.name));
        };
        loadRefs();
    }, []);

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsLoading(true);
        setStatus(null);
        setStats(null);

        const reader = new FileReader();
        reader.onload = (evt) => {
            try {
                const bstr = evt.target?.result;
                const wb = XLSX.read(bstr, { type: 'binary' });
                const wsname = wb.SheetNames[0];
                const ws = wb.Sheets[wsname];
                const data = XLSX.utils.sheet_to_json(ws);

                if (data.length === 0) {
                    setStatus({ type: 'error', text: 'El archivo está vacío o no tiene el formato correcto.' });
                } else {
                    setFileData(data);
                    setStatus({ type: 'info', text: `Se han detectado ${data.length} registros en el archivo.` });
                }
            } catch (err) {
                setStatus({ type: 'error', text: 'Error al procesar el archivo Excel.' });
            } finally {
                setIsLoading(false);
            }
        };
        reader.readAsBinaryString(file);
    };

    const downloadTemplate = () => {
        const templateData = [
            {
                "CEDULA": "12345678",
                "NOMBRES_APELLIDOS": "JUAN PEREZ",
                "FECHA_NACIMIENTO": "1990-05-15",
                "SEXO": "Masculino",
                "TELEFONO": "0414-1234567",
                "DIRECCION": "AV. BOLIVAR NRO 10",
                "EMPRESA": companies[0] || "EMPRESA EJEMPLO",
                "CARGO": jobs[0] || "CARGO EJEMPLO",
                "FECHA_INGRESO": "2023-01-01",
                "ESTATUS_LABORAL": "fijo",
                "MANO_DOMINANTE": "Diestro",
                "ED_INSTRUCCION": "Universitario"
            }
        ];

        const ws = XLSX.utils.json_to_sheet(templateData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Plantilla_Pacientes");
        XLSX.writeFile(wb, "Plantilla_Carga_Masiva_Afamed.xlsx");
    };

    const processData = async () => {
        if (fileData.length === 0) return;

        setIsProcessing(true);
        try {
            const mappedPatients = fileData.map((row: any) => ({
                firstName: String(row.NOMBRES_APELLIDOS || '').toUpperCase(),
                cedula: String(row.CEDULA || ''),
                birthDate: String(row.FECHA_NACIMIENTO || ''),
                gender: (row.SEXO === 'Femenino' ? 'Femenino' : 'Masculino') as 'Masculino' | 'Femenino',
                phone: String(row.TELEFONO || ''),
                address: String(row.DIRECCION || ''),
                company: String(row.EMPRESA || ''),
                jobTitle: String(row.CARGO || ''),
                entryDate: String(row.FECHA_INGRESO || ''),
                employmentStatus: (row.ESTATUS_LABORAL === 'contratado' ? 'contratado' : 'fijo') as 'fijo' | 'contratado',
                dominantHand: (row.MANO_DOMINANTE || 'Diestro') as any,
                educationLevel: (row.ED_INSTRUCCION || 'Secundaria') as any,
                medicalHistory: '',
                hasDisability: false
            }));

            const result = await batchSavePatients(mappedPatients as any);
            setStats(result);
            setStatus({ type: 'success', text: 'Proceso de carga masiva finalizado.' });
            setFileData([]);
            if (fileInputRef.current) fileInputRef.current.value = '';
        } catch (err) {
            setStatus({ type: 'error', text: 'Error al guardar los datos en el sistema.' });
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <div className="max-w-5xl mx-auto pb-20 animate-in fade-in duration-500">
            <div className="flex items-center gap-3 mb-8">
                <div className="p-3 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100">
                    <Database className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Carga Masiva de Datos</h2>
                    <p className="text-slate-500 text-sm">Importe su nómina de trabajadores desde archivos Excel de forma segura.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* INSTRUCTIONS */}
                <div className="lg:col-span-1 space-y-6">
                    <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                        <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                            <Info className="w-5 h-5 text-blue-600" />
                            Instrucciones
                        </h3>
                        <ul className="space-y-4 text-sm text-slate-600">
                            <li className="flex gap-3">
                                <span className="flex-shrink-0 w-5 h-5 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center text-xs font-bold">1</span>
                                <p>Descargue la plantilla oficial para asegurar que los nombres de las columnas coincidan.</p>
                            </li>
                            <li className="flex gap-3">
                                <span className="flex-shrink-0 w-5 h-5 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center text-xs font-bold">2</span>
                                <p>Complete los datos de sus trabajadores en el archivo Excel.</p>
                            </li>
                            <li className="flex gap-3">
                                <span className="flex-shrink-0 w-5 h-5 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center text-xs font-bold">3</span>
                                <p>Suba el archivo y el sistema detectará automáticamente si son ingresos nuevos o actualizaciones.</p>
                            </li>
                        </ul>

                        <button 
                            onClick={downloadTemplate}
                            className="w-full mt-8 flex items-center justify-center gap-2 px-4 py-3 bg-slate-50 text-slate-700 rounded-xl border border-slate-200 font-bold text-sm hover:bg-slate-100 transition-all"
                        >
                            <Download className="w-4 h-4" />
                            Descargar Plantilla (.xlsx)
                        </button>
                    </div>

                    <div className="bg-amber-50 p-6 rounded-2xl border border-amber-100">
                        <h4 className="font-bold text-amber-900 text-sm mb-2 flex items-center gap-2">
                            <AlertCircle className="w-4 h-4" />
                            Nota Importante
                        </h4>
                        <p className="text-xs text-amber-800 leading-relaxed">
                            El sistema utiliza la <strong>Cédula</strong> como identificador único. Si sube una cédula que ya existe, los datos de ese trabajador se actualizarán con la información del Excel.
                        </p>
                    </div>
                </div>

                {/* UPLOAD AREA */}
                <div className="lg:col-span-2 space-y-6">
                    <div 
                        className={`
                            relative border-2 border-dashed rounded-3xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer
                            ${fileData.length > 0 ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-slate-200 hover:border-indigo-400 hover:bg-slate-50'}
                        `}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input 
                            type="file" 
                            ref={fileInputRef}
                            className="hidden" 
                            accept=".xlsx, .xls, .csv"
                            onChange={handleFileUpload}
                        />

                        {isLoading ? (
                            <Loader2 className="w-16 h-16 text-indigo-500 animate-spin mb-4" />
                        ) : fileData.length > 0 ? (
                            <FileSpreadsheet className="w-16 h-16 text-indigo-600 mb-4" />
                        ) : (
                            <Upload className="w-16 h-16 text-slate-300 mb-4" />
                        )}

                        <p className="text-lg font-bold text-slate-700 mb-1">
                            {fileData.length > 0 ? 'Archivo listo para procesar' : 'Haga clic para subir su Excel'}
                        </p>
                        <p className="text-slate-500 text-sm">o arrastre y suelte el archivo aquí</p>
                    </div>

                    {status && (
                        <div className={`p-4 rounded-xl flex items-start gap-3 border animate-in slide-in-from-top-2 ${
                            status.type === 'success' ? 'bg-green-50 text-green-800 border-green-200' : 
                            status.type === 'info' ? 'bg-blue-50 text-blue-800 border-blue-200' : 
                            'bg-red-50 text-red-800 border-red-200'
                        }`}>
                            {status.type === 'success' ? <CheckCircle2 className="w-5 h-5 shrink-0" /> : <AlertCircle className="w-5 h-5 shrink-0" />}
                            <div className="text-sm">
                                <p className="font-bold">{status.text}</p>
                                {stats && (
                                    <div className="mt-2 grid grid-cols-2 gap-4">
                                        <div className="bg-white/50 p-2 rounded-lg border border-green-200">
                                            <span className="block text-xs uppercase font-black opacity-50">Nuevos Ingresos</span>
                                            <span className="text-xl font-bold">{stats.created}</span>
                                        </div>
                                        <div className="bg-white/50 p-2 rounded-lg border border-green-200">
                                            <span className="block text-xs uppercase font-black opacity-50">Actualizados</span>
                                            <span className="text-xl font-bold">{stats.updated}</span>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {fileData.length > 0 && !isProcessing && (
                        <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-lg animate-in fade-in zoom-in-95">
                            <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                                <h3 className="font-bold text-slate-800 text-sm">Vista previa de datos ({fileData.length})</h3>
                                <button 
                                    onClick={processData}
                                    className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 shadow-md shadow-indigo-100 transition-all"
                                >
                                    Confirmar y Cargar Datos
                                </button>
                            </div>
                            <div className="overflow-x-auto max-h-[400px]">
                                <table className="w-full text-xs text-left">
                                    <thead className="bg-white sticky top-0 border-b border-slate-200 z-10">
                                        <tr className="text-slate-500 uppercase font-black">
                                            <th className="px-4 py-3">Cédula</th>
                                            <th className="px-4 py-3">Nombre</th>
                                            <th className="px-4 py-3">Cargo</th>
                                            <th className="px-4 py-3">Empresa</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {fileData.slice(0, 10).map((row, idx) => (
                                            <tr key={idx} className="hover:bg-slate-50">
                                                <td className="px-4 py-2 font-mono">{row.CEDULA}</td>
                                                <td className="px-4 py-2 font-bold">{row.NOMBRES_APELLIDOS}</td>
                                                <td className="px-4 py-2 text-slate-500">{row.CARGO}</td>
                                                <td className="px-4 py-2 text-slate-500">{row.EMPRESA}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                                {fileData.length > 10 && (
                                    <div className="p-3 text-center text-slate-400 italic text-xs border-t border-slate-100">
                                        ... y {fileData.length - 10} registros más.
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {isProcessing && (
                        <div className="bg-white rounded-2xl border border-indigo-200 p-12 flex flex-col items-center justify-center text-center shadow-lg">
                            <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
                            <h3 className="text-xl font-bold text-slate-800">Procesando Carga Masiva</h3>
                            <p className="text-slate-500 mt-2">Estamos validando y guardando los datos en la base de datos local. Por favor no cierre esta ventana.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DataImport;

import React, { useState } from 'react';
import { 
  FolderOpen, 
  Stethoscope, 
  Calendar, 
  FileText, 
  ClipboardList, 
  Activity, 
  FileBarChart, 
  ChevronDown, 
  ChevronRight, 
  ShieldPlus,
  BookOpenCheck,
  Settings,
  Database
} from 'lucide-react';
import { MenuItem } from '../types';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigate: (view: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, onNavigate }) => {
  const [expandedMenu, setExpandedMenu] = useState<string | null>('archivo');

  const menuItems: MenuItem[] = [
    { 
      id: 'archivo', 
      label: 'Archivo', 
      icon: FolderOpen, 
      hasSubmenu: true,
      subItems: ['Paciente', 'Medicos', 'Empresas', 'Usuarios', 'Historia Clínica', 'Cargos'] 
    },
    { id: 'atencion', label: 'Atención Médica', icon: Stethoscope },
    { id: 'citas', label: 'Citas', icon: Calendar },
    { id: 'recipe', label: 'Recipe E.', icon: FileText },
    { id: 'reporte', label: 'Reporte', icon: ClipboardList },
    { id: 'diagnostica', label: 'I Diagnóstica', icon: Activity },
    { 
      id: 'informes', 
      label: 'Informes', 
      icon: FileBarChart,
      hasSubmenu: true,
      subItems: ['Informes Medicos', 'Informe Ocupacional', 'Reposo Medico', 'Reposos Externos']
    },
    { id: 'sve', label: 'Informe SVE', icon: BookOpenCheck },
    { id: 'datos', label: 'Carga Masiva', icon: Database }, // Nueva opción
    { id: 'configuracion', label: 'Configuración', icon: Settings },
  ];

  const toggleSubmenu = (id: string) => {
    if (expandedMenu === id) {
      setExpandedMenu(null);
    } else {
      setExpandedMenu(id);
    }
  };

  const handleSubItemClick = (parent: string, item: string) => {
    const viewId = item.toLowerCase()
      .replace(/ /g, '-')
      .normalize("NFD").replace(/[\u0300-\u036f]/g, ""); 

    onNavigate(viewId);

    if (window.innerWidth < 1024) {
      onClose();
    }
  };

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      {/* Sidebar Container */}
      <aside 
        className={`
          fixed top-0 left-0 z-50 h-full w-72 
          bg-gradient-to-b from-[#0f172a] to-[#1e3a8a] 
          text-white shadow-2xl transition-transform duration-300 ease-in-out
          flex flex-col justify-between print:hidden
          ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
      >
        {/* Header / Logo */}
        <div className="p-6 border-b border-blue-800/50 bg-opacity-20 bg-blue-900">
          <div className="flex items-center gap-3">
            <div className="bg-blue-500 p-2 rounded-lg bg-opacity-20 border border-blue-400">
               <ShieldPlus className="w-8 h-8 text-blue-300" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-blue-100 tracking-wide">ALEX CONSULTING</h1>
              <p className="text-[10px] text-blue-300 uppercase tracking-widest">Servicios Médicos</p>
            </div>
          </div>
        </div>

        {/* Navigation Items */}
        <nav className="flex-1 overflow-y-auto py-6 px-3 space-y-1 custom-scrollbar">
          {menuItems.map((item) => (
            <div key={item.id} className="mb-1">
              <button
                onClick={() => item.hasSubmenu ? toggleSubmenu(item.id) : onNavigate(item.id)}
                className={`
                  w-full flex items-center justify-between p-3 rounded-lg
                  transition-all duration-200
                  ${expandedMenu === item.id ? 'bg-blue-800/50 text-blue-200' : 'hover:bg-blue-800/30 text-gray-100'}
                `}
              >
                <div className="flex items-center gap-3">
                  <item.icon className={`w-5 h-5 ${expandedMenu === item.id ? 'text-blue-300' : 'text-gray-300'}`} />
                  <span className="font-medium text-sm">{item.label}</span>
                </div>
                {item.hasSubmenu && (
                  expandedMenu === item.id 
                    ? <ChevronDown className="w-4 h-4 text-blue-300" /> 
                    : <ChevronRight className="w-4 h-4 text-gray-400" />
                )}
              </button>

              {/* Submenu */}
              {item.hasSubmenu && expandedMenu === item.id && (
                <div className="ml-4 pl-4 border-l border-blue-700/50 mt-1 space-y-1">
                  {item.subItems?.map((sub, idx) => (
                    <button 
                      key={idx}
                      onClick={() => handleSubItemClick(item.id, sub)}
                      className="w-full text-left p-2 text-sm text-gray-300 hover:text-white hover:bg-blue-800/20 rounded transition-colors"
                    >
                      {sub}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
        </nav>

        {/* Footer */}
        <div className="p-6 border-t border-blue-800/50 bg-[#0b1120]/50 text-center">
          <p className="text-xs text-gray-400 font-light mb-1">
            &copy; {new Date().getFullYear()} Alex Consulting
          </p>
          <p className="text-xs text-gray-500 font-light">
            Servicios Médicos
          </p>
        </div>
      </aside>
    </>
  );
};

