const MedicalReportGenerator: React.FC<MedicalReportGeneratorProps> = ({ type }) => {
  // --- State ---
  const [searchCedula, setSearchCedula] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [patient, setPatient] = useState<Patient | null>(null);
  const [attentions, setAttentions] = useState<MedicalAttention[]>([]);
  const [selectedAttention, setSelectedAttention] = useState<MedicalAttention | null>(null);

  // Doctor Selection State (Physician who validates)
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<string>('');

  // Forms Data
  const [formData, setFormData] = useState({
      diagnosis: '',
      days: 1,
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      reason: 'Enfermedad Común' as MedicalAttention['reason'],
      // Only for external
      externalDoctor: '',
      externalInstitution: ''
  });

  // Load Doctors on Mount
  useEffect(() => {
    const fetchDoctors = async () => {
        const docs = await getDoctors();
        setDoctors(docs);
        if (docs.length > 0) setSelectedDoctorId(docs[0].id);
    };
    fetchDoctors();
  }, []);

  // Calculate End Date automatically
  useEffect(() => {
    const calculateEndDate = (start: string, days: number) => {
        if (!start || days < 1) return '';
        const date = new Date(start);
        date.setDate(date.getDate() + (Number(days) - 1));
        return date.toISOString().split('T')[0];
    };

    setFormData(prev => ({ ...prev, endDate: calculateEndDate(prev.startDate, prev.days) }));
  }, [formData.startDate, formData.days]);

  // Reset when type changes
  useEffect(() => {
    setSelectedAttention(null);
    setPatient(null);
    setAttentions([]);
    setSearchCedula('');
    setError('');
    setSuccess('');
    setFormData({
        diagnosis: '',
        days: 1,
        startDate: new Date().toISOString().split('T')[0],
        endDate: '',
        reason: 'Enfermedad Común',
        externalDoctor: '',
        externalInstitution: ''
    });
  }, [type]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchCedula.trim()) return;

    setIsSearching(true);
    setError('');
    setSuccess('');
    setPatient(null);
    setAttentions([]);
    setSelectedAttention(null);

    try {
      const foundPatient = await findPatientByCedula(searchCedula);
      if (!foundPatient) {
        setError('Trabajador no encontrado.');
        setIsSearching(false);
        return;
      }

      const foundAttentions = await getMedicalAttentionsByCedula(searchCedula);
      setPatient(foundPatient);
      setAttentions(foundAttentions);
    } catch (err) {
      setError('Error al recuperar datos.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleSaveLeave = async () => {
    if (!patient || !selectedDoctorId || !formData.diagnosis) {
        setError('Por favor complete el diagnóstico y seleccione el médico que valida.');
        return;
    }

    if (type === 'external-sick-leave' && (!formData.externalDoctor || !formData.externalInstitution)) {
        setError('Debe indicar el médico tratante externo y la institución de origen.');
        return;
    }

    const doc = doctors.find(d => d.id === selectedDoctorId);

    const newAttention: Omit<MedicalAttention, 'id' | 'createdAt'> = {
        patientId: patient.id,
        patientName: patient.firstName,
        patientCedula: patient.cedula,
        attentionDate: formData.startDate,
        attentionType: 'General',
        reason: formData.reason,
        diagnosis: formData.diagnosis,
        restDays: formData.days,
        restStartDate: formData.startDate,
        restEndDate: formData.endDate,
        evaluationResult: 'No Aplica',
        doctorId: selectedDoctorId,
        doctorName: doc ? `${doc.title} ${doc.firstName}` : '',
        isExternal: type === 'external-sick-leave',
        externalDoctor: type === 'external-sick-leave' ? formData.externalDoctor : undefined,
        externalInstitution: type === 'external-sick-leave' ? formData.externalInstitution : undefined
    };

    try {
        const saved = await saveMedicalAttentionToDB(newAttention);
        setSelectedAttention(saved);
        setSuccess('Registro guardado exitosamente para el informe SVE.');
        setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
        setError('Error al guardar el registro.');
    }
  };

  const getTitle = () => {
    switch(type) {
        case 'medical': return 'Informe Médico General';
        case 'occupational': return 'Informe Ocupacional';
        case 'sick-leave': return 'Reposo Médico (Interno)';
        case 'external-sick-leave': return 'Validación de Reposo Externo';
        default: return 'Reporte';
    }
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const formatDate = (dateStr: string) => {
      if (!dateStr) return '-';
      return new Date(dateStr).toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  const renderHeader = () => (
    <header className="border-b-2 border-slate-800 pb-4 mb-8 flex justify-between items-start">
        <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-blue-900 rounded-lg flex items-center justify-center text-white font-bold">AC</div>
            <div>
                <h1 className="text-xl font-bold text-slate-900 uppercase tracking-wider leading-tight">Alex Consulting</h1>
