                    <p className="text-justify text-base">
                        Se procede a la {selectedAttention.isExternal ? 'convalidación' : 'asignación'} del reposo médico por un lapso de 
                        <span className="text-xl font-black mx-2 border-b-2 border-slate-900 px-2">{selectedAttention.restDays}</span> 
                        días continuos, clasificado epidemiológicamente como <strong>{selectedAttention.reason}</strong>.
                    </p>

                    <div className="grid grid-cols-2 gap-8 py-4">
                        <div className="text-center p-4 border-2 border-slate-100 rounded-2xl">
