                        <th className="text-center">N° de Casos</th>
                        <th className="text-center">Días Internos</th>
                        <th className="text-center">Días Externos</th>
                        <th className="text-center bg-slate-100">Días Totales</th>
                     </tr>
                  </thead>
                  <tbody>
                     {(Object.entries(restStats) as [string, { count: number, days: number, internal: number, external: number }][]).map(([cat, s]) => (
                        <tr key={cat}>
                           <td className="font-medium">{cat}</td>
                           <td className="text-center font-bold">{s.count}</td>
                           <td className="text-center">{s.internal} d</td>
                           <td className="text-center">{s.external} d</td>
                           <td className="text-center font-bold bg-slate-50">{s.days} d</td>
                        </tr>
                     ))}
                     <tr className="bg-slate-200 font-bold">
                        <td>TOTAL TRIMESTRAL ACUMULADO</td>
                        <td className="text-center">{Object.values(restStats).reduce((a,c) => a + c.count, 0)}</td>
                        <td className="text-center">{Object.values(restStats).reduce((a,c) => a + c.internal, 0)} d</td>
                        <td className="text-center">{Object.values(restStats).reduce((a,c) => a + c.external, 0)} d</td>
                        <td className="text-center bg-slate-800 text-white">{Object.values(restStats).reduce((a,c) => a + c.days, 0)} d</td>
                     </tr>
                  </tbody>
               </table>

               <div className="section-title flex items-center gap-2">
                   <ClipboardCheck className="w-3.5 h-3.5" />
                   7.2 Relación de Reposos Externos Validados
               </div>
               <table className="text-[8px]">
                  <thead>
                     <tr>
                        <th className="w-20">Fecha Inicio</th>
                        <th>Trabajador</th>
                        <th className="w-16">Días</th>
                        <th>Motivo SVE</th>
                        <th>Médico Externo / Institución</th>
                        <th>Diagnóstico Referido</th>
                     </tr>
                  </thead>
                  <tbody>
                     {externalRepososList.length > 0 ? externalRepososList.map((rep) => (
                        <tr key={rep.id}>
                           <td>{rep.restStartDate}</td>
                           <td className="font-bold uppercase">{rep.patientName}</td>
                           <td className="text-center font-bold">{rep.restDays}</td>
                           <td>{rep.reason}</td>
                           <td className="uppercase text-[7px]">{rep.externalDoctor} / {rep.externalInstitution}</td>
                           <td className="italic">{rep.diagnosis}</td>
                        </tr>
                     )) : (
                        <tr><td colSpan={6} className="text-center py-4 italic text-slate-400">No se registraron reposos externos validados en el trimestre.</td></tr>
                     )}
                  </tbody>
               </table>

               <div className="section-title">11.- Estadísticas de Accidentalidad y Morbilidad</div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 border rounded bg-slate-50 text-[9px]">
                     <p className="font-bold border-b mb-1 uppercase text-slate-500">Frecuencia Bruta (IFB)</p>
                     <p className="text-blue-600 font-black text-lg">
                       {((structuredMorbidity['Accidentes de Trabajo'].length / (patientsInScope.length || 1)) * 100).toFixed(2)}
                     </p>
                  </div>
                  <div className="p-3 border rounded bg-slate-50 text-[9px]">
                     <p className="font-bold border-b mb-1 uppercase text-slate-500">Índice de Gravedad (IG)</p>
                     <p className="text-blue-600 font-black text-lg">
                       {((restStats['Accidentes de Trabajo'].days / (patientsInScope.length || 1)) * 100).toFixed(2)}
                     </p>
                  </div>
               </div>
            </div>
            <FooterSignatures pageType="last" />
        </div>

      </div>
    </div>
  );
};

export default SVEReport;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies, getDoctors } from '../utils/storage';
import { MedicalAttention, Patient, Company, Doctor } from '../types';
import { Printer, ShieldCheck, Building2, Table as TableIcon, BarChart3, FileText, FileDown, Users as UsersIcon, PieChart as PieIcon, FileSearch, ClipboardCheck } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';

type Quarter = 'I' | 'II' | 'III' | 'IV';

const COLORS = ['#1e3a8a', '#db2777', '#0ea5e9', '#f43f5e'];

const SVEReport: React.FC = () => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');
  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps, docs] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies(),
            getDoctors()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
        setDoctors(docs);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2];
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return [];
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  // General Demographic Stats for analysis
  const demographicStats = useMemo(() => {
      if (patientsInScope.length === 0) return null;

      const total = patientsInScope.length;
      const males = patientsInScope.filter(p => p.gender === 'Masculino').length;
      const females = total - males;
      const withDisability = patientsInScope.filter(p => p.hasDisability).length;

      const ageGroups = { '18-24': 0, '25-34': 0, '35-44': 0, '45-54': 0, '55+': 0 };
      patientsInScope.forEach(p => {
          const age = calculateAge(p.birthDate);
          if (age < 25) ageGroups['18-24']++;
          else if (age < 35) ageGroups['25-34']++;
          else if (age < 45) ageGroups['35-44']++;
          else if (age < 55) ageGroups['45-54']++;
          else ageGroups['55+']++;
      });

      const predominantGender = males >= females ? 'Masculino' : 'Femenino';
      const predominantGenderPercent = ((predominantGender === 'Masculino' ? males : females) / total * 100).toFixed(1);

      const sortedAges = Object.entries(ageGroups).sort((a, b) => b[1] - a[1]);
      const mainAgeGroup = sortedAges[0][0];

      return {
          total, males, females, withDisability, 
          disabilityPercent: (withDisability / total * 100).toFixed(1),
          predominantGender, predominantGenderPercent, mainAgeGroup
      };
  }, [patientsInScope]);

  // Job distribution stats
  const jobDistribution = useMemo(() => {
      const stats: Record<string, number> = {};
      patientsInScope.forEach(p => {
          const job = p.jobTitle || 'No especificado';
          stats[job] = (stats[job] || 0) + 1;
      });
      return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [patientsInScope]);

  const genderDistribution = useMemo(() => {
      const males = patientsInScope.filter(p => p.gender === 'Masculino').length;
      const females = patientsInScope.filter(p => p.gender === 'Femenino').length;
      const total = patientsInScope.length || 1;
      return [
          { name: 'Masculino', value: males, percentage: ((males / total) * 100).toFixed(1) },
          { name: 'Femenino', value: females, percentage: ((females / total) * 100).toFixed(1) }
      ];
  }, [patientsInScope]);

  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);

  const quarterAttentions = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    return attentionsInScope.filter(att => {
      const d = new Date(att.attentionDate);
      return d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
  }, [attentionsInScope, selectedYear, selectedQuarter]);

  const annualOccurrenceStats = useMemo(() => {
    const stats: Record<number, { ac: number, at: number, ec: number, eo: number }> = {};
    for (let i = 0; i < 12; i++) {
        stats[i] = { ac: 0, at: 0, ec: 0, eo: 0 };
    }
    attentionsInScope.forEach(att => {
        const d = new Date(att.attentionDate);
        if (d.getFullYear() === selectedYear) {
            const month = d.getMonth();
            if (att.reason === 'Accidente Común') stats[month].ac++;
            else if (att.reason === 'Accidente Ocupacional') stats[month].at++;
            else if (att.reason === 'Enfermedad Común') stats[month].ec++;
            else if (att.reason === 'Enfermedad Ocupacional') stats[month].eo++;
        }
    });
    return stats;
  }, [attentionsInScope, selectedYear]);

  const examStats = useMemo(() => {
    const data = {
      'Ingreso (Pre-empleo)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Prevacacional': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Postvacacional (Periódica)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Egreso': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Especiales / Otros': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
    };
    quarterAttentions.forEach(att => {
       if (att.isExternal) return; // Exclude external leaves from exam stats as they are validation only
       let key: keyof typeof data | null = null;
       if (att.attentionType === 'Pre Empleo') key = 'Ingreso (Pre-empleo)';
       else if (att.attentionType === 'Pre Vacaciones') key = 'Prevacacional';
       else if (att.attentionType === 'Egreso') key = 'Egreso';
       else if (att.attentionType === 'Periódica') key = 'Postvacacional (Periódica)';
       else if (att.attentionType === 'General') key = 'Especiales / Otros';
       if (key && data[key]) {
           data[key].Total++;
           const result = att.evaluationResult;
           if (result === 'Apto') data[key].Apto++;
           else if (result === 'No Apto') data[key]['No Apto']++;
           else if (result === 'Postpuesta') data[key].Postpuesta++;
           else data[key]['No Aplica']++;
       }
    });
    return data;
  }, [quarterAttentions]);

  const structuredMorbidity = useMemo(() => {
     return {
        'Accidentes Comunes': quarterAttentions.filter(a => a.reason === 'Accidente Común'),
        'Accidentes de Trabajo': quarterAttentions.filter(a => a.reason === 'Accidente Ocupacional'),
        'Enfermedades Comunes': quarterAttentions.filter(a => a.reason === 'Enfermedad Común'),
        'Enfermedades Ocupacionales': quarterAttentions.filter(a => a.reason === 'Enfermedad Ocupacional'),
     };
  }, [quarterAttentions]);

  const restStats = useMemo(() => {
     const stats = {
        'Accidentes Comunes': { count: 0, days: 0, internal: 0, external: 0 },
        'Accidentes de Trabajo': { count: 0, days: 0, internal: 0, external: 0 },
        'Enfermedades Comunes': { count: 0, days: 0, internal: 0, external: 0 },
        'Enfermedades Ocupacionales': { count: 0, days: 0, internal: 0, external: 0 },
     };
     quarterAttentions.forEach(a => {
        let key = '';
        if (a.reason === 'Accidente Común') key = 'Accidentes Comunes';
        else if (a.reason === 'Accidente Ocupacional') key = 'Accidentes de Trabajo';
        else if (a.reason === 'Enfermedad Común') key = 'Enfermedad Común';
        else if (a.reason === 'Enfermedad Ocupacional') key = 'Enfermedad Ocupacional';
        if (key && a.restDays > 0) {
            stats[key as keyof typeof stats].count++;
            stats[key as keyof typeof stats].days += a.restDays;
            if (a.isExternal) {
                stats[key as keyof typeof stats].external += a.restDays;
            } else {
                stats[key as keyof typeof stats].internal += a.restDays;
            }
        }
     });
     return stats;
  }, [quarterAttentions]);

  const externalRepososList = useMemo(() => {
      return quarterAttentions.filter(a => a.isExternal && a.restDays > 0);
  }, [quarterAttentions]);

  const handleExportWord = () => {
    if (!reportRef.current) return;
    const content = reportRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
            "xmlns:w='urn:schemas-microsoft-com:office:word' " +
            "xmlns='http://www.w3.org/TR/REC-html40'>" +
            "<head><meta charset='utf-8'><title>Informe SVE</title>" +
            "<style>" +
            "body { font-family: 'Arial', sans-serif; font-size: 10pt; }" +
            "table { border-collapse: collapse; width: 100%; margin-bottom: 10px; }" +
            "th, td { border: 1px solid #000; padding: 5px; text-align: left; }" +
            "th { background-color: #f3f4f6; font-weight: bold; }" +
            ".section-title { font-weight: bold; text-transform: uppercase; border-bottom: 2px solid #000; margin-top: 20px; margin-bottom: 10px; }" +
            ".page-break { page-break-after: always; }" +
            "</style></head><body>";
    const footer = "</body></html>";
    const sourceHTML = header + content + footer;
    const blob = new Blob(['\ufeff', sourceHTML], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `SVE_${selectedCompanyName || 'Reporte'}_T${selectedQuarter}_${selectedYear}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const HeaderSection = () => (
    <div className="flex justify-between items-center mb-6 border-b-2 border-slate-900 pb-4">
       <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-100 rounded flex items-center justify-center border border-slate-300">
             {currentCompany ? <Building2 className="w-8 h-8 text-slate-400"/> : "LOGO"}
          </div>
          <div>
             <h1 className="text-lg font-bold text-slate-900 uppercase">
                 {currentCompany?.name || 'ENTIDAD DE TRABAJO'}
             </h1>
             <p className="text-xs font-semibold text-slate-700">RIF: {currentCompany?.rif || 'N/A'}</p>
             <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Servicio de Seguridad y Salud en el Trabajo</p>
          </div>
       </div>
       <div className="text-right">
          <h2 className="text-sm font-bold text-slate-800 uppercase">Informe Trimestral SVE</h2>
          <p className="text-xs font-medium text-slate-700">Trimestre: {selectedQuarter} - Año: {selectedYear}</p>
          <p className="text-[9px] text-slate-400 mt-1 uppercase">LOPCYMAT / NT-03-2016 / NT-04-2023</p>
       </div>
    </div>
  );

  const FooterSignatures = ({ pageType }: { pageType: 'first' | 'middle' | 'last' }) => (
    <div className="mt-auto pt-6 border-t border-slate-200">
      <div className="grid grid-cols-3 gap-4 mb-4">
        <div className="text-center">
           <div className="border-t border-slate-800 pt-1"></div>
           <p className="font-bold text-[9px] uppercase">Médico Ocupacional</p>
           <p className="text-[8px] text-slate-500">Suscrito en todas las páginas</p>
        </div>
        {(pageType === 'first' || pageType === 'last') && (
          <div className="text-center">
             <div className="border-t border-slate-800 pt-1"></div>
             <p className="font-bold text-[9px] uppercase">Seguridad e Higiene</p>
             <p className="text-[8px] text-slate-500">Reg. INPSASEL</p>
          </div>
        )}
        {pageType === 'last' && (
          <div className="text-center">
             <div className="border-t border-slate-800 pt-1"></div>
             <p className="font-bold text-[9px] uppercase">Representante CSSL</p>
             <p className="text-[8px] text-slate-500">Delegado / Patrono</p>
          </div>
        )}
      </div>
      <div className="flex justify-between text-[8px] text-slate-400 uppercase font-mono">
         <span>Alex Consulting SVE Report</span>
         <span className="page-number-display">Página </span>
      </div>
    </div>
  );

  if (loading) return <div className="p-8 text-center text-slate-500">Preparando reporte epidemiológico...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">

      {/* Controls */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 print:hidden flex flex-col gap-4">
         <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
            <ShieldCheck className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-bold text-slate-800">Generador SVE (Normativa 2024)</h2>
         </div>
         <div className="flex flex-wrap gap-4 items-end">
            <div className="flex-1 min-w-[200px]">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Entidad de Trabajo</label>
               <select 
                 value={selectedCompanyName}
                 onChange={(e) => setSelectedCompanyName(e.target.value)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white outline-none focus:ring-2 focus:ring-blue-500"
               >
                   <option value="">-- Seleccionar --</option>
                   {companies.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
               </select>
            </div>
            <div className="w-24">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Año</label>
               <input type="number" value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm" />
            </div>
            <div className="w-32">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Trimestre</label>
               <select value={selectedQuarter} onChange={e => setSelectedQuarter(e.target.value as Quarter)} className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white">
                  <option value="I">Ene-Mar</option>
                  <option value="II">Abr-Jun</option>
                  <option value="III">Jul-Sep</option>
                  <option value="IV">Oct-Dic</option>
               </select>
            </div>
            <div className="flex gap-2">
                <button 
                    onClick={() => window.print()} 
                    disabled={!selectedCompanyName}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 shadow-md hover:bg-blue-700 transition-colors disabled:bg-slate-300"
                >
                    <Printer className="w-4 h-4" /> Generar PDF
                </button>
                <button 
                    onClick={handleExportWord}
                    disabled={!selectedCompanyName}
                    className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 shadow-md hover:bg-indigo-700 transition-colors disabled:bg-slate-300"
                >
                    <FileDown className="w-4 h-4" /> Generar Word
                </button>
            </div>
         </div>
      </div>

      {/* REPORT VIEW */}
      <div ref={reportRef} className="print-container text-slate-900 bg-white md:p-12 print:p-0 rounded-xl shadow-2xl print:shadow-none">

        <style>{`
          @media print {
            body { background: white; -webkit-print-color-adjust: exact; }
            .print-hidden { display: none !important; }
            .page-break { 
              page-break-after: always; 
              min-height: 297mm; 
              display: flex; 
              flex-direction: column; 
              padding: 15mm; 
              position: relative;
            }
            .page-break:last-child { page-break-after: auto; }
            @page { size: A4; margin: 0; }
            .page-number-display::after { content: counter(page); }
          }
          .page-break { min-height: 297mm; position: relative; display: flex; flex-direction: column; background: white; margin-bottom: 20px; box-shadow: 0 0 10px rgba(0,0,0,0.1); padding: 20mm; }
          table { width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 15px; }
          th, td { border: 1px solid #94a3b8; padding: 4px 6px; text-align: left; }
          th { background-color: #f1f5f9; font-weight: bold; text-transform: uppercase; color: #1e293b; font-size: 8px; }
          .section-title { font-size: 11px; font-weight: bold; text-transform: uppercase; border-bottom: 2px solid #1e293b; margin: 15px 0 10px 0; padding-bottom: 2px; color: #0f172a; }
          .legal-intro { font-size: 10px; color: #475569; text-align: justify; margin-bottom: 20px; line-height: 1.4; }
          .bg-total { background-color: #f8fafc; font-weight: bold; }
        `}</style>

        {/* PAGINA 1: REGISTRO MENSUAL */}
        <div className="page-break" style={{ counterReset: 'page 1' }}>
            <HeaderSection />
            <div className="flex-1">
               <div className="text-center mb-6">
                  <h1 className="text-xl font-black text-slate-800 uppercase tracking-tighter">SISTEMA DE VIGILANCIA EPIDEMIOLÓGICA (SVE)</h1>
               </div>

               <div className="legal-intro">
                  Según lo indicado en la LOPCYMAT y NT-04-2023, se presenta el informe de vigilancia epidemiológica para <strong>{selectedCompanyName || 'ENTIDAD DE TRABAJO'}</strong> correspondiente al trimestre {selectedQuarter} del año {selectedYear}.
               </div>

               {/* NUEVA SECCIÓN: DISTRIBUCIÓN POR CARGOS */}
               <div className="section-title flex items-center gap-2">
                  <UsersIcon className="w-3.5 h-3.5" />
                  Discriminación de trabajadores por cargo y cantidad
               </div>
               <table>
                  <thead>
                     <tr>
                        <th>Cargo / Puesto de Trabajo</th>
                        <th className="text-center w-32">Cantidad de Trabajadores</th>
                     </tr>
                  </thead>
                  <tbody>
                     {jobDistribution.length > 0 ? jobDistribution.map(([job, count]) => (
                        <tr key={job}>
                           <td className="uppercase">{job}</td>
                           <td className="text-center font-bold">{count}</td>
                        </tr>
                     )) : (
                        <tr><td colSpan={2} className="text-center py-4 italic text-slate-400">Sin datos de trabajadores cargados para esta empresa.</td></tr>
                     )}
                     <tr className="bg-slate-200 font-bold">
                        <td className="uppercase text-right px-4">Total de Trabajadores en Nómina Activa:</td>
                        <td className="text-center text-blue-700">{patientsInScope.length}</td>
                     </tr>
                  </tbody>
               </table>

               <div className="section-title">1.- Registro mensual de la cantidad de trabajadores discriminados</div>
               <table>
                  <thead>
                     <tr>
                        <th>Mes / Período</th>
                        <th className="text-center">Total</th>
                        <th className="text-center">Masculino</th>
                        <th className="text-center">Femenino</th>
                        <th className="text-center">Discapacidad</th>
                        <th className="text-center">18-24</th>
                        <th className="text-center">25-34</th>
                        <th className="text-center">35-44</th>
                        <th className="text-center">45-54</th>
                        <th className="text-center">55+</th>
                     </tr>
                  </thead>
                  <tbody>
                     {getQuarterMonths(selectedQuarter).map(monthIdx => {
                        const stats = { total: 0, m: 0, f: 0, d: 0, a1: 0, a2: 0, a3: 0, a4: 0, a5: 0 };
                        patientsInScope.forEach(p => {
                            stats.total++;
                            if (p.gender === 'Masculino') stats.m++; else stats.f++;
                            if (p.hasDisability) stats.d++;
                            const age = calculateAge(p.birthDate);
                            if (age < 25) stats.a1++;
                            else if (age < 35) stats.a2++;
                            else if (age < 45) stats.a3++;
                            else if (age < 55) stats.a4++;
                            else stats.a5++;
                        });

                        return (
                           <tr key={monthIdx}>
                              <td className="font-bold">{getMonthName(monthIdx).toUpperCase()}</td>
                              <td className="text-center font-bold">{stats.total}</td>
                              <td className="text-center">{stats.m}</td>
                              <td className="text-center">{stats.f}</td>
                              <td className="text-center">{stats.d}</td>
                              <td className="text-center">{stats.a1}</td>
                              <td className="text-center">{stats.a2}</td>
                              <td className="text-center">{stats.a3}</td>
                              <td className="text-center">{stats.a4}</td>
                              <td className="text-center">{stats.a5}</td>
                           </tr>
                        );
                     })}
                  </tbody>
               </table>

               {/* ANÁLISIS DESCRIPTIVO DE LA POBLACIÓN */}
               {demographicStats && (
                 <div className="bg-slate-50 border border-slate-200 p-4 rounded-lg mt-2 mb-4 animate-in fade-in duration-700">
                    <h4 className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-700 mb-2">
                       <FileSearch className="w-3.5 h-3.5" />
                       Análisis descriptivo de la población trabajadora
                    </h4>
                    <p className="text-[10px] text-slate-600 leading-relaxed text-justify">
                       La entidad de trabajo presenta una población total activa de <strong>{demographicStats.total}</strong> trabajadores durante el período evaluado. 
                       Demográficamente, existe una predominancia del género <strong>{demographicStats.predominantGender}</strong>, el cual representa el <strong>{demographicStats.predominantGenderPercent}%</strong> de la nómina. 
                       Se reporta la presencia de un <strong>{demographicStats.disabilityPercent}%</strong> de trabajadores con alguna condición de discapacidad registrada.
                    </p>
                 </div>
               )}

               <div className="section-title">2.- Registro de los Accidentes Comunes</div>
               <table>
                  <thead>
                     <tr>
                        <th className="w-20">Fecha</th>
                        <th>Cargo</th>
                        <th>Departamento</th>
                        <th>Sistemas Afectados / Diagnóstico</th>
                        <th className="w-16">Días</th>
                     </tr>
                  </thead>
                  <tbody>
                     {structuredMorbidity['Accidentes Comunes'].length > 0 ? structuredMorbidity['Accidentes Comunes'].map(a => {
                        const p = allPatients.find(pat => pat.cedula === a.patientCedula);
                        return (
                           <tr key={a.id}>
                              <td>{a.attentionDate}</td>
                              <td className="uppercase">{p?.jobTitle || 'N/A'}</td>
                              <td className="uppercase">{p?.department || 'N/A'}</td>
                              <td>{a.diagnosis} {a.isExternal && <span className="text-[7px] bg-indigo-100 px-1 rounded">EXT</span>}</td>
                              <td className="text-center font-bold">{a.restDays}</td>
                           </tr>
                        );
                     }) : <tr><td colSpan={5} className="text-center italic text-slate-400 py-4">No hay accidentes comunes registrados.</td></tr>}
                  </tbody>
               </table>
            </div>
            <FooterSignatures pageType="first" />
        </div>

        {/* PAGINA 2: ENFERMEDADES Y EXAMENES */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1">
               <div className="section-title">4.- Registro de Enfermedades (Comunes y Ocupacionales)</div>

               <h4 className="font-bold text-[9px] uppercase mb-1">4.1 Enfermedades Comunes</h4>
               <table>
                  <thead>
                     <tr>
                        <th className="w-20">Fecha</th>
                        <th>Cargo</th>
                        <th>Departamento</th>
                        <th>Diagnóstico / Sistemas Afectados</th>
                        <th className="text-center w-12">Origen</th>
                     </tr>
                  </thead>
                  <tbody>
                     {structuredMorbidity['Enfermedades Comunes'].length > 0 ? structuredMorbidity['Enfermedades Comunes'].map(a => {
                        const p = allPatients.find(pat => pat.cedula === a.patientCedula);
                        return (
                           <tr key={a.id}>
                              <td>{a.attentionDate}</td>
                              <td className="uppercase">{p?.jobTitle || 'N/A'}</td>
                              <td className="uppercase">{p?.department || 'N/A'}</td>
                              <td>{a.diagnosis}</td>
                              <td className="text-center text-[8px] font-bold">{a.isExternal ? 'EXT' : 'INT'}</td>
                           </tr>
                        );
                     }) : <tr><td colSpan={5} className="text-center italic text-slate-400 py-4">Sin enfermedades comunes registradas.</td></tr>}
                  </tbody>
               </table>

               {/* TABLA DE RELACIÓN MENSUAL Y ANUAL */}
               <div className="section-title flex items-center gap-2">
                 <BarChart3 className="w-3.5 h-3.5" /> 
                 Relación mensual y anual de la ocurrencia de eventos
               </div>
               <table>
                  <thead>
                     <tr>
                        <th>Mes de Ocurrencia</th>
                        <th className="text-center">Accidentes Comunes</th>
                        <th className="text-center">Accidentes de Trabajo</th>
                        <th className="text-center">Enfermedades Comunes</th>
                        <th className="text-center">Enfermedades Ocupacionales</th>
                     </tr>
                  </thead>
                  <tbody>
                     {getQuarterMonths(selectedQuarter).map(monthIdx => (
                        <tr key={monthIdx}>
                           <td className="font-medium uppercase">{getMonthName(monthIdx)}</td>
                           <td className="text-center">{annualOccurrenceStats[monthIdx].ac}</td>
                           <td className="text-center font-bold">{annualOccurrenceStats[monthIdx].at}</td>
                           <td className="text-center">{annualOccurrenceStats[monthIdx].ec}</td>
                           <td className="text-center font-bold text-red-600">{annualOccurrenceStats[monthIdx].eo}</td>
                        </tr>
                     ))}
                  </tbody>
               </table>

               <div className="section-title">5.- Resultados de Exámenes y Evaluaciones de Salud</div>
               <table className="text-center">
                  <thead>
                     <tr>
                        <th className="text-left">Evaluación Practicada</th>
                        <th>Apto</th>
                        <th>No Apto</th>
                        <th>Postpuesta</th>
                        <th>No Aplica</th>
                        <th className="bg-slate-200">Cantidad</th>
                     </tr>
                  </thead>
                  <tbody>
                     {(Object.entries(examStats) as [string, { Apto: number, 'No Apto': number, Postpuesta: number, 'No Aplica': number, Total: number }][]).map(([type, s]) => (
                        <tr key={type}>
                           <td className="text-left font-medium">{type}</td>
                           <td>{s.Apto}</td>
                           <td>{s['No Apto']}</td>
                           <td>{s.Postpuesta}</td>
                           <td>{s['No Aplica']}</td>
                           <td className="bg-total">{s.Total}</td>
                        </tr>
                     ))}
                  </tbody>
               </table>
            </div>
            <FooterSignatures pageType="middle" />
        </div>

        {/* PAGINA 3: REPOSOS DETALLADOS (INTERNOS + EXTERNOS) */}
        <div className="page-break">
            <HeaderSection />
            <div className="flex-1">
               <div className="section-title">7.- Registro de los Reposos (Discriminado por Cantidad y Tiempo)</div>
               <h4 className="font-bold text-[9px] uppercase mb-1">7.1 Resumen Estadístico Consolidado (Internos + Externos)</h4>
               <p className="text-[8px] text-slate-500 mb-2">Estadística que incluye reposos emitidos por el servicio y validaciones externas según normativa.</p>
               <table>
                  <thead>
                     <tr>
                        <th>Categoría de Reposo Médico</th>
                        <th className="text-center">N° de Casos</th>
                        <th className="text-center">Días Internos</th>
                        <th className="text-center">Días Externos</th>
                        <th className="text-center bg-slate-100">Días Totales</th>
                     </tr>
                  </thead>
                  <tbody>
                     {(Object.entries(restStats) as [string, { count: number, days: number, internal: number, external: number }][]).map(([cat, s]) => (
                        <tr key={cat}>
                           <td className="font-medium">{cat}</td>
                           <td className="text-center font-bold">{s.count}</td>
                           <td className="text-center">{s.internal} d</td>
                           <td className="text-center">{s.external} d</td>
                           <td className="text-center font-bold bg-slate-50">{s.days} d</td>
                        </tr>
                     ))}
                     <tr className="bg-slate-200 font-bold">
                        <td>TOTAL TRIMESTRAL ACUMULADO</td>
                        {/* Fix: Added explicit typing to reduce callbacks to prevent 'unknown' type errors */}
                        <td className="text-center">{Object.values(restStats).reduce((a: number, c: any) => a + c.count, 0)}</td>
                        <td className="text-center">{Object.values(restStats).reduce((a: number, c: any) => a + c.internal, 0)} d</td>
                        <td className="text-center">{Object.values(restStats).reduce((a: number, c: any) => a + c.external, 0)} d</td>
                        <td className="text-center bg-slate-800 text-white">{Object.values(restStats).reduce((a: number, c: any) => a + c.days, 0)} d</td>
                     </tr>
                  </tbody>
               </table>

               <div className="section-title flex items-center gap-2">
                   <ClipboardCheck className="w-3.5 h-3.5" />
                   7.2 Relación de Reposos Externos Validados
               </div>
               <table className="text-[8px]">
                  <thead>
                     <tr>
                        <th className="w-20">Fecha Inicio</th>
                        <th>Trabajador</th>
                        <th className="w-16">Días</th>
                        <th>Motivo SVE</th>
                        <th>Médico Externo / Institución</th>
                        <th>Diagnóstico Referido</th>
                     </tr>
                  </thead>
                  <tbody>
                     {externalRepososList.length > 0 ? externalRepososList.map((rep) => (
                        <tr key={rep.id}>
                           <td>{rep.restStartDate}</td>
                           <td className="font-bold uppercase">{rep.patientName}</td>
                           <td className="text-center font-bold">{rep.restDays}</td>
                           <td>{rep.reason}</td>
                           <td className="uppercase text-[7px]">{rep.externalDoctor} / {rep.externalInstitution}</td>
                           <td className="italic">{rep.diagnosis}</td>
                        </tr>
                     )) : (
                        <tr><td colSpan={6} className="text-center py-4 italic text-slate-400">No se registraron reposos externos validados en el trimestre.</td></tr>
                     )}
                  </tbody>
               </table>

               <div className="section-title">11.- Estadísticas de Accidentalidad y Morbilidad</div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 border rounded bg-slate-50 text-[9px]">
                     <p className="font-bold border-b mb-1 uppercase text-slate-500">Frecuencia Bruta (IFB)</p>
                     <p className="text-blue-600 font-black text-lg">
                       {((structuredMorbidity['Accidentes de Trabajo'].length / (patientsInScope.length || 1)) * 100).toFixed(2)}
                     </p>
                  </div>
                  <div className="p-3 border rounded bg-slate-50 text-[9px]">
                     <p className="font-bold border-b mb-1 uppercase text-slate-500">Índice de Gravedad (IG)</p>
                     <p className="text-blue-600 font-black text-lg">
                       {((restStats['Accidentes de Trabajo'].days / (patientsInScope.length || 1)) * 100).toFixed(2)}
                     </p>
                  </div>
               </div>
            </div>
            <FooterSignatures pageType="last" />
        </div>

      </div>
    </div>
  );
};

