                  <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white print:border print:border-black">
                     <ShieldCheck className="w-10 h-10" />
                  </div>
                  <div>
                    <h1 className="text-2xl font-black uppercase tracking-tighter">ALEX CONSULTING</h1>
                    <p className="text-blue-400 print:text-black text-sm font-bold tracking-widest uppercase">Expediente Médico de Salud en el Trabajo</p>
                  </div>
                </div>
                <div className="text-right">
                   <p className="text-[10px] text-slate-500 uppercase font-black mb-1">Código de Documento</p>
