                       <div className="absolute inset-0 border-[6px] border-white/30 pointer-events-none rounded-3xl"></div>
                     </div>
                  </div>
                  <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-y-5 gap-x-10">
                    <div className="md:col-span-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-0.5">Nombres y Apellidos Completos</label>
                      <h2 className="text-2xl font-bold text-slate-900 leading-tight">{patient.firstName}</h2>
