import React, { useState, useEffect, useMemo, useRef } from 'react';
import { getAllMedicalAttentions, getAllPatients, getCompanies, getDoctors } from '../utils/storage';
import { MedicalAttention, Patient, Company, Doctor } from '../types';
import { Printer, ShieldCheck, Building2, Table as TableIcon, BarChart3, FileText, FileDown, Users as UsersIcon, PieChart as PieIcon, FileSearch, ClipboardCheck } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';

type Quarter = 'I' | 'II' | 'III' | 'IV';
const COLORS = ['#1e3a8a', '#db2777', '#0ea5e9', '#f43f5e'];

// Definition of stats structure to avoid 'unknown' type errors
interface RestCategoryStats {
  count: number;
  days: number;
  internal: number;
  external: number;
}

const SVEReport: React.FC = () => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedQuarter, setSelectedQuarter] = useState<Quarter>('I');
  const [allPatients, setAllPatients] = useState<Patient[]>([]);
  const [allAttentions, setAllAttentions] = useState<MedicalAttention[]>([]);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCompanyName, setSelectedCompanyName] = useState<string>('');

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [pats, atts, comps] = await Promise.all([
            getAllPatients(), 
            getAllMedicalAttentions(),
            getCompanies()
        ]);
        setAllPatients(pats);
        setAllAttentions(atts);
        setCompanies(comps);
      } catch (e) {
        console.error("Error fetching data", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const getQuarterMonths = (q: Quarter) => {
    switch (q) {
      case 'I': return [0, 1, 2];
      case 'II': return [3, 4, 5];
      case 'III': return [6, 7, 8];
      case 'IV': return [9, 10, 11];
    }
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2024, monthIndex, 1).toLocaleDateString('es-ES', { month: 'long' });
  };

  const calculateAge = (birthDateString: string) => {
    const today = new Date();
    const birthDate = new Date(birthDateString);
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
    return age;
  };

  const patientsInScope = useMemo(() => {
      if (!selectedCompanyName) return [];
      return allPatients.filter(p => p.company === selectedCompanyName);
  }, [allPatients, selectedCompanyName]);

  const demographicStats = useMemo(() => {
      if (patientsInScope.length === 0) return null;
      const total = patientsInScope.length;
      const males = patientsInScope.filter(p => p.gender === 'Masculino').length;
      const females = total - males;
      const withDisability = patientsInScope.filter(p => p.hasDisability).length;
      const predominantGender = males >= females ? 'Masculino' : 'Femenino';
      const predominantGenderPercent = ((predominantGender === 'Masculino' ? males : females) / total * 100).toFixed(1);
      return {
          total, males, females, withDisability, 
          disabilityPercent: (withDisability / total * 100).toFixed(1),
          predominantGender, predominantGenderPercent
      };
  }, [patientsInScope]);

  const jobDistribution = useMemo(() => {
      const stats: Record<string, number> = {};
      patientsInScope.forEach(p => {
          const job = p.jobTitle || 'No especificado';
          stats[job] = (stats[job] || 0) + 1;
      });
      return Object.entries(stats).sort((a, b) => b[1] - a[1]);
  }, [patientsInScope]);

  const attentionsInScope = useMemo(() => {
      if (!selectedCompanyName) return allAttentions;
      const patientCedulas = new Set(patientsInScope.map(p => p.cedula));
      return allAttentions.filter(a => patientCedulas.has(a.patientCedula));
  }, [allAttentions, patientsInScope, selectedCompanyName]);

  const currentCompany = useMemo(() => {
      return companies.find(c => c.name === selectedCompanyName);
  }, [companies, selectedCompanyName]);

  const quarterAttentions = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    return attentionsInScope.filter(att => {
      const d = new Date(att.attentionDate);
      return d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
  }, [attentionsInScope, selectedYear, selectedQuarter]);

  const annualOccurrenceStats = useMemo(() => {
    const stats: Record<number, { ac: number, at: number, ec: number, eo: number }> = {};
    for (let i = 0; i < 12; i++) stats[i] = { ac: 0, at: 0, ec: 0, eo: 0 };
    attentionsInScope.forEach(att => {
        const d = new Date(att.attentionDate);
        if (d.getFullYear() === selectedYear) {
            const month = d.getMonth();
            if (att.reason === 'Accidente Común') stats[month].ac++;
            else if (att.reason === 'Accidente Ocupacional') stats[month].at++;
            else if (att.reason === 'Enfermedad Común') stats[month].ec++;
            else if (att.reason === 'Enfermedad Ocupacional') stats[month].eo++;
        }
    });
    return stats;
  }, [attentionsInScope, selectedYear]);

  const examStats = useMemo(() => {
    const data = {
      'Ingreso (Pre-empleo)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Prevacacional': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Postvacacional (Periódica)': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Egreso': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
      'Especiales / Otros': { Apto: 0, 'No Apto': 0, Postpuesta: 0, 'No Aplica': 0, Total: 0 },
    };
    quarterAttentions.forEach(att => {
       if (att.isExternal) return;
       let key: keyof typeof data | null = null;
       if (att.attentionType === 'Pre Empleo') key = 'Ingreso (Pre-empleo)';
       else if (att.attentionType === 'Pre Vacaciones') key = 'Prevacacional';
       else if (att.attentionType === 'Egreso') key = 'Egreso';
       else if (att.attentionType === 'Periódica') key = 'Postvacacional (Periódica)';
       else if (att.attentionType === 'General') key = 'Especiales / Otros';
       if (key && data[key]) {
           data[key].Total++;
           const result = att.evaluationResult;
           if (result === 'Apto') data[key].Apto++;
           else if (result === 'No Apto') data[key]['No Apto']++;
           else if (result === 'Postpuesta') data[key].Postpuesta++;
           else data[key]['No Aplica']++;
       }
    });
    return data;
  }, [quarterAttentions]);

  const structuredMorbidity = useMemo(() => {
     return {
        'Accidentes Comunes': quarterAttentions.filter(a => a.reason === 'Accidente Común'),
        'Accidentes de Trabajo': quarterAttentions.filter(a => a.reason === 'Accidente Ocupacional'),
        'Enfermedades Comunes': quarterAttentions.filter(a => a.reason === 'Enfermedad Común'),
        'Enfermedades Ocupacionales': quarterAttentions.filter(a => a.reason === 'Enfermedad Ocupacional'),
     };
  }, [quarterAttentions]);

  const restStats = useMemo(() => {
     const stats: Record<string, RestCategoryStats> = {
        'Accidentes Comunes': { count: 0, days: 0, internal: 0, external: 0 },
        'Accidentes de Trabajo': { count: 0, days: 0, internal: 0, external: 0 },
        'Enfermedades Comunes': { count: 0, days: 0, internal: 0, external: 0 },
        'Enfermedades Ocupacionales': { count: 0, days: 0, internal: 0, external: 0 },
     };
     quarterAttentions.forEach(a => {
        let key = '';
        if (a.reason === 'Accidente Común') key = 'Accidentes Comunes';
        else if (a.reason === 'Accidente Ocupacional') key = 'Accidentes de Trabajo';
        else if (a.reason === 'Enfermedad Común') key = 'Enfermedad Común';
        else if (a.reason === 'Enfermedad Ocupacional') key = 'Enfermedad Ocupacional';
        if (key && a.restDays > 0) {
            stats[key].count++;
            stats[key].days += a.restDays;
            if (a.isExternal) stats[key].external += a.restDays;
            else stats[key].internal += a.restDays;
        }
     });
     return stats;
  }, [quarterAttentions]);

  const handleExportWord = () => {
    if (!reportRef.current) return;
    const content = reportRef.current.innerHTML;
    const header = "<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Informe SVE Alex Consulting</title><style>body { font-family: 'Arial', sans-serif; font-size: 10pt; } table { border-collapse: collapse; width: 100%; margin-bottom: 10px; } th, td { border: 1px solid #000; padding: 5px; text-align: left; } th { background-color: #f3f4f6; font-weight: bold; } .section-title { font-weight: bold; text-transform: uppercase; border-bottom: 2px solid #000; margin-top: 20px; margin-bottom: 10px; } .page-break { page-break-after: always; }</style></head><body>";
    const footer = "</body></html>";
    const sourceHTML = header + content + footer;
    const blob = new Blob(['\ufeff', sourceHTML], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `SVE_AlexConsulting_${selectedCompanyName || 'Reporte'}_T${selectedQuarter}_${selectedYear}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const HeaderSection = () => (
    <div className="flex justify-between items-center mb-6 border-b-2 border-slate-900 pb-4">
       <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-100 rounded flex items-center justify-center border border-slate-300">
             {currentCompany ? <Building2 className="w-8 h-8 text-slate-400"/> : "LOGO"}
          </div>
          <div>
             <h1 className="text-lg font-bold text-slate-900 uppercase">{currentCompany?.name || 'ENTIDAD DE TRABAJO'}</h1>
             <p className="text-xs font-semibold text-slate-700">RIF: {currentCompany?.rif || 'N/A'}</p>
             <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Servicio de Seguridad y Salud en el Trabajo</p>
          </div>
       </div>
       <div className="text-right">
          <h2 className="text-sm font-bold text-slate-800 uppercase">Informe Trimestral SVE</h2>
          <p className="text-xs font-medium text-slate-700">Trimestre: {selectedQuarter} - Año: {selectedYear}</p>
          <p className="text-[9px] text-slate-400 mt-1 uppercase">LOPCYMAT / NT-04-2023</p>
       </div>
    </div>
  );

  const FooterSignatures = ({ pageType }: { pageType: 'first' | 'middle' | 'last' }) => (
    <div className="mt-auto pt-6 border-t border-slate-200">
      <div className="grid grid-cols-3 gap-4 mb-4">
        <div className="text-center">
           <div className="border-t border-slate-800 pt-1"></div>
           <p className="font-bold text-[9px] uppercase">Médico Ocupacional</p>
        </div>
        {pageType === 'last' && (
          <div className="text-center">
             <div className="border-t border-slate-800 pt-1"></div>
             <p className="font-bold text-[9px] uppercase">Representante CSSL</p>
          </div>
        )}
      </div>
      <div className="flex justify-between text-[8px] text-slate-400 uppercase font-mono">
         <span>Alex Consulting SVE Report</span>
         <span className="page-number-display">Página </span>
      </div>
    </div>
  );

  if (loading) return <div className="p-8 text-center text-slate-500">Preparando reporte epidemiológico...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 print:hidden flex flex-col gap-4">
         <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
            <ShieldCheck className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-bold text-slate-800">Generador SVE - Alex Consulting</h2>
         </div>
         <div className="flex flex-wrap gap-4 items-end">
            <div className="flex-1 min-w-[200px]">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Entidad de Trabajo</label>
               <select 
                 value={selectedCompanyName}
                 onChange={(e) => setSelectedCompanyName(e.target.value)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white outline-none focus:ring-2 focus:ring-blue-500"
               >
                   <option value="">-- Seleccionar --</option>
                   {companies.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
               </select>
            </div>
            <div className="flex gap-2">
                <button 
                    onClick={() => window.print()} 
                    disabled={!selectedCompanyName}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 shadow-md hover:bg-blue-700 transition-colors disabled:bg-slate-300"
                >
                    <Printer className="w-4 h-4" /> Generar PDF
                </button>
                <button 
                    onClick={handleExportWord}
                    disabled={!selectedCompanyName}
                    className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 shadow-md hover:bg-indigo-700 transition-colors disabled:bg-slate-300"
                >
                    <FileDown className="w-4 h-4" /> Generar Word
                </button>
            </div>
         </div>
      </div>

      <div ref={reportRef} className="print-container text-slate-900 bg-white md:p-12 print:p-0 rounded-xl shadow-2xl print:shadow-none">
        <style>{`
