          .bg-total { background-color: #f8fafc; font-weight: bold; }
        `}</style>

        <div className="page-break" style={{ counterReset: 'page 1' }}>
            <HeaderSection />
            <div className="flex-1">
               <div className="text-center mb-6">
                  <h1 className="text-xl font-black text-slate-800 uppercase tracking-tighter text-center">SISTEMA DE VIGILANCIA EPIDEMIOLÓGICA (SVE) - ALEX CONSULTING</h1>
               </div>
               <div className="legal-intro">
                  Según lo indicado en la LOPCYMAT y NT-04-2023, se presenta el informe de vigilancia epidemiológica para <strong>{selectedCompanyName || 'ENTIDAD DE TRABAJO'}</strong> correspondiente al trimestre {selectedQuarter} del año {selectedYear}.
               </div>
               <div className="section-title">1.- Registro mensual de la cantidad de trabajadores discriminados</div>
               <table>
                  <thead>
                     <tr>
                        <th>Mes / Período</th>
                        <th className="text-center">Total</th>
                        <th className="text-center">Masculino</th>
                        <th className="text-center">Femenino</th>
                        <th className="text-center">Discapacidad</th>
                     </tr>
                  </thead>
                  <tbody>
                     {getQuarterMonths(selectedQuarter).map(monthIdx => (
                        <tr key={monthIdx}>
                           <td className="font-bold">{getMonthName(monthIdx).toUpperCase()}</td>
                           <td className="text-center font-bold">{patientsInScope.length}</td>
                           <td className="text-center">{patientsInScope.filter(p => p.gender === 'Masculino').length}</td>
                           <td className="text-center">{patientsInScope.filter(p => p.gender === 'Femenino').length}</td>
                           <td className="text-center">{patientsInScope.filter(p => p.hasDisability).length}</td>
                        </tr>
                     ))}
                  </tbody>
               </table>
               <div className="section-title">2.- Registro de los Accidentes Comunes</div>
               <table>
                  <thead>
                     <tr><th className="w-20">Fecha</th><th>Cargo</th><th>Diagnóstico / Sistemas Afectados</th><th className="w-16">Días</th></tr>
                  </thead>
                  <tbody>
                     {structuredMorbidity['Accidentes Comunes'].length > 0 ? structuredMorbidity['Accidentes Comunes'].map(a => (
                        <tr key={a.id}><td>{a.attentionDate}</td><td className="uppercase">{allPatients.find(p => p.cedula === a.patientCedula)?.jobTitle || 'N/A'}</td><td>{a.diagnosis}</td><td className="text-center font-bold">{a.restDays}</td></tr>
                     )) : <tr><td colSpan={4} className="text-center italic text-slate-400 py-4">Sin datos registrados.</td></tr>}
                  </tbody>
               </table>
            </div>
            <FooterSignatures pageType="first" />
        </div>
        <div className="page-break">
           <HeaderSection />
           <div className="flex-1">
              <div className="section-title">Relación de Reposos (Alex Consulting System)</div>
              <table>
                 <thead>
                    <tr><th>Categoría</th><th className="text-center">N° de Casos</th><th className="text-center">Días Totales</th></tr>
                 </thead>
                 <tbody>
                    {Object.entries(restStats).map(([cat, s]) => (
                       <tr key={cat}><td>{cat}</td><td className="text-center font-bold">{s.count}</td><td className="text-center font-bold">{s.days} d</td></tr>
                    ))}
                 </tbody>
              </table>
           </div>
           <FooterSignatures pageType="last" />
        </div>
      </div>
    </div>
  );
};
