                   <option value="I">I (Ene-Mar)</option>
                   <option value="II">II (Abr-Jun)</option>
                   <option value="III">III (Jul-Sep)</option>
                   <option value="IV">IV (Oct-Dic)</option>
               </select>
            </div>
            <div className="flex gap-2">
                <button onClick={() => window.print()} disabled={!selectedCompanyName} className="flex-1 px-4 py-2.5 bg-blue-600 text-white rounded-lg text-xs font-bold flex items-center justify-center gap-2 shadow-md hover:bg-blue-700 disabled:bg-slate-300">
