                @media print {
                    body { background: white; }
                    .print-report { width: 100%; max-width: none; }
                    .page-break { page-break-after: always; padding-top: 20px; }
                    table { page-break-inside: auto; }
                    tr { page-break-inside: avoid; page-break-after: auto; }
