                    </thead>
                    <tbody>
                        {Array.from({ length: 12 }, (_, i) => i).map(monthIdx => {
                            const stats = annualOccurrenceSummary[monthIdx];
                            const monthTotal = stats.ac + stats.at + stats.ec + stats.eo;
                            return (
                                <tr key={monthIdx}>
                                    <td className="font-bold uppercase">{getMonthName(monthIdx)}</td>
