export const checkAvailability = async (date: string, time: string, excludeId?: string): Promise<boolean> => {
  const appointments = await getAppointments();
  return !appointments.some(a => 
    a.date === date && 
    a.time === time && 
    a.status !== 'Cancelada' &&
    a.id !== excludeId
  );
};

import React, { useState } from 'react';
